/* 平成29年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h29.committeeSessions.push(...[{"id":"h29-20171005-4","meetingId":"h29-c-settlement","date":"2017年10月5日","dateIso":"2017-10-05","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時２９分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を156件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"横山委員","kind":"質問","question":"１４５ページ、１４４ページ、すまいるスクール運営費についてお伺いいたします。１点目に、認知症高齢者の支援とケアの充実についてをお伺いいたします。","respondent":"寺嶋高齢者福祉課長","answer":"認知症サポーター養成講座の件ですけれども、まず平成２８年度、合計で６９回実施をいたしました。もともとくるみぷらんにつきましては、品川ぐるみでつくっていこうという取り組みでございまして、いい成果が出ているものと認識しております。","id":"exchange-001"},{"speaker":"横山委員","kind":"確認","question":"それから大人までということで、幅広い層にアピールをしていただいているということで、確認をさせていただきました。品川区におけるヤングケアラー、ダブルケアなど、ケアラーの支援の現状と課題についてもの説明を求めました。","respondent":"寺嶋高齢者福祉課長","answer":"今年度も引き続き実施しています。その方が抱える背景の部分につきましてもしっかりとサポートしていけるような体制をつくっているところです。","id":"exchange-002"},{"speaker":"横山委員","kind":"質問・要望","question":"今後の展開についてお伺いします。より多くの方が利用しやすい仕組みへのバージョンアップを検討していただきたいと考えますが、いかがか尋ねました。","respondent":"寺嶋高齢者福祉課長、高山子ども育成課長","answer":"複数の課題を抱えてらっしゃるという事例が多々あるということは十分認識しておりますので、今後も他部署との連携を強化し、支援に努めていきたいと考えております。産後の家事・育児支援につきましては、心と体のケアにも対応できる家事・育児支援ヘルパーをご家庭のほうに、ご紹介のとおり。","id":"exchange-003"},{"speaker":"横山委員","kind":"質問・要望","question":"３点目にすまいるスクール運営費、ファミリー・サポート・センターについてお伺いいたします。そして、今後のあり方について、在宅子育てをする方々にもさらに利用しやすいような制度へと考え方を移行していただきたいと要望いたします。","respondent":"高山子ども育成課長、廣田子ども家庭支援課長","answer":"平成２８年４月より、それまで大幅な事業の見直しは行ってまいりませんでしたが、利用時間の延長と、そして利用料の見直しをさせていただきました。私からはファミリー・サポート・センター事業についてご説明申し上げます。就労率が上がっている、また今後はシルバー世帯でありますとか、別の世代にアプローチをしていこうと考えているところです。","id":"exchange-004"},{"speaker":"横山委員","kind":"質問・要望","question":"これは要望です。子育て支援の施策を考えていただきたいと思っているのですけれども、ファミリー・サポート・センターの在宅子育て支援についてお伺いします。","respondent":"廣田子ども家庭支援課長","answer":"今現在も習い事の援助でありますとか、保護者の求職活動でありますとか、あとはお母さんが病気のときの援助などにも使っていますけれども、利用目的が広がるように努めていこうと考えています。","id":"exchange-005"},{"speaker":"新妻委員","kind":"質問・要望","question":"１３７ページ、１３８ページ、プレーパーク整備についてお伺いいたします。本年６月に品川区ではしながわ子ども食堂フォーラムを開催し、また支援をしたいという会社の方が集まって、約８０人が参加をされたとお伺いました。","respondent":"廣田子ども家庭支援課長","answer":"地域全体で子どもを育てていくという活動ですので、行政だけではやり切れない部分について一緒にやっていくということで、支援をしていこうというふうに考えているものです。","id":"exchange-006"},{"speaker":"新妻委員","kind":"質問・要望","question":"先日の款別質疑の中で、品川区が把握しています子ども食堂は８カ所、そして検討されているところが４カ所というご答弁がありました。この８カ所のエリアを具体的に教えてほしいと求めました。","respondent":"廣田子ども家庭支援課長","answer":"現在、子ども食堂が開設されているエリアにつきましては、北品川二丁目、南品川六丁目、大井三丁目、南大井六丁目の４カ所が品川・大井地区で豊町四丁目、二葉四丁目、西中延一丁目、戸越二丁目のところが荏原地区となっています。","id":"exchange-007"},{"speaker":"新妻委員","kind":"質問・要望","question":"要望としましては、本当に子どもたち、またご家庭の親御さんが利用しやすいように、全品川区のエリアにあるということが望ましいと思います。","respondent":"廣田子ども家庭支援課長","answer":"現在マップに落とし込みをしておりまして、空白地域がどこにあるのかというところを検討、調査しております。その空白地域については開設しにくいところではないかと考えますので、そちらについて開設が広がるように支援をしていこうと考えているところです。","id":"exchange-008"},{"speaker":"新妻委員","kind":"提案","question":"お子さんが何を求めているのか、こちらから手を差し伸べるという形も非常に大事ではないかなと考えています。続きまして２点目に臨時福祉給付金についてお伺いをいたしますとの意見を述べました。","respondent":"大串臨時給付金担当課長","answer":"平成２８年度は３つの臨時福祉給付金がございました。そこから始まったもので９月１５日まで受付を行っておりました経済対策分ということでの臨時福祉給付金、この３つが平成２８年度は実施されたです。","id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"申請をしなければもらえないという制度であります。その１つが９月１５日で終わったですが、この９月１５日に間に合わなかった方、この方への救済措置があるのか教えてほしいと求めました。","respondent":"大串臨時給付金担当課長","answer":"ただ、申請率が先ほど８０％と申し上げましたとおり全員が全員申請をしてくれているというわけではございません。そういった理由、事情をご説明いただいた上で申請をしていただければ支給はしているというものです。","id":"exchange-010"},{"speaker":"新妻委員","kind":"確認","question":"締め切りは過ぎているけれども、しっかりと理由を説明し申請をしてもらえれば救済して支給されるということが確認されました。最後にプレーパークの運営費についてお伺いいたします。","respondent":"高山子ども育成課長","answer":"予算額の内訳です。プレーパークに関しましては、昨年度の予算を用いまして、北品川にあります北浜こども冒険ひろばの運営費も計上させていただいているものです。","id":"exchange-011"},{"speaker":"新妻委員","kind":"質問・要望","question":"しながわ区民公園、大変に好評であると伺っております。この現場のスタッフの皆さんの声を聞く場が定期的にあるのか、そして今後の方向性をお聞かせほしいと求めました。","respondent":"高山子ども育成課長","answer":"運営をしておりますＮＰＯ法人ふれあいの家－おばちゃんちとは定期的に情報交換などはさせていただいているところです。今後の方向性ですが、まずは２カ所目であるしながわ子ども冒険ひろばを安定的に運営していくということを念頭に進めてまいりたいと考えております。","id":"exchange-012"},{"speaker":"新妻委員","kind":"確認","question":"２カ所目のしながわ区民公園の状況もよく確認をしていただきながら、他の地域にも拡大ができるよう取り組みをお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問・要望","question":"１３７ページの特別養護老人ホーム等整備費より今後の特養ホームの整備について、ニコンにかかわって伺いたいと思います。かいろいろお話を伺いますが、いかがか尋ねました。","respondent":"中山障害者福祉課長","answer":"社会福祉協議会の杖の交付につきましては、提供という形で差し上げておりまして、修理の対応ができていないという状況です。社会福祉協議会のほうが割と速やかに、まずは社会福祉協議会でもらって、その後自分によく合ったつえを補装具で提供する形が多いと考えております。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"命綱ですから、どちらであっても修理や取りかえを自己負担なくできる制度にしていただきたいと思うのですけれども、改めてお伺いしたいと思います。品川区と社協を含め、現在何人ぐらいの方が品川区で使っているのか、現状についてもお伺いしたいと思います。","respondent":"中山障害者福祉課長","answer":"なかなか修理の事業者の紹介というところが難しいかなと考えています。あるいは修理が効くものは修理ということで対応していますので、そこについては交付を受ける視覚障害の方に十分周知をしていきたいと考えています。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひどちらであっても修理や取りかえができるようにしていただきたいと思うのですけれども、これがなぜできないのかご説明ほしいと求めました。これはちょっと改善が必要だと思うのですけれども、改めていかがか尋ねました。","respondent":"中山障害者福祉課長","answer":"やはり情報が複雑になればなるほど利用される方も混乱するところもあるかと思いますので、社会福祉協議会と話し合いをしながら、修理ができるかどうか、そうした委託ができるかどうかを検討してまいります。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"どういうときになったら取りかえられるのかとか、修理が可能だとか、こうした情報がなかなか目が不自由ですから把握するのが難しいわけですよね。","respondent":"中山障害者福祉課長","answer":"その中で修理であったり新たな杖の交付であったりということで対応しています。どうしてもなかなか塗りかえていくことができないということもありますので、その辺は丁寧な対応ということを努めていきたいと考えております。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひいろいろ改善や検討を進めてほしいと求めましたし、丁寧な対応を強く要望して、次に特養ホームについて伺いたいと思います。民間の土地を区が購入して特養ホームの整備を進める考えはあるのか、考えについてお伺いしたいと思います。","respondent":"大串福祉計画課長","answer":"特養ホームにつきましては、委員ご案内のように去年、今年と平塚橋、上大崎と１００人規模の特養ホームを相次いで開設をしてまいりました。ただ、今のところ具体的なというところでは、適地といったところではまだないです。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問","question":"ちょっと後半が聞きにくかったので、要するに民間の土地も区が購入して特養ホームをつくる考えはあるということなのでしょうか。もう一度お願いいたします。","respondent":"大串福祉計画課長","answer":"特養ホームを整備する、あるいは高齢者施設を整備するといったところで、民有地といったところも適地選定の中には候補として入ってくるです。","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"今年１月２６日付で区長名で株式会社ニコンの牛田社長宛てに要望書が提出されました。ぜひ認可保育園や特養ホームの整備などについて具体化を進めてほしいと求めましたけれども、いかがか尋ねました。","respondent":"柏原企画調整課長","answer":"そういった中でもし、その中の相手先の１つに区としても参加といいますか、お声がけいただけないかというお話をさせていただいているです。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"私が伺ったのは、この区長の要望書を見ると、「保育所や高齢者施設などの需要の高まりから」という記述があるのですけれども、改めてずばり品川区は、ニコンの土地を購入して保育園や高齢者施設をつくりたいという考えがあるということでよいのか、確認させてください。","respondent":"柏原企画調整課長","answer":"まだニコン、相手方のほうがどういった形で使用するのかというところが見えない状況であります。その相手先として声をかけていただきたいというものですので、いろいろな行政需要がある中で、トータルでの判断ということになろうかと思います。","id":"exchange-021"},{"speaker":"中塚委員","kind":"質問","question":"これはどういう意味なのかということなのです。改めて、ニコンの土地を購入してこの保育園や高齢者施設をつくりたいという考えがあるということでよいのか伺いたいと思います。","respondent":"柏原企画調整課長","answer":"例えば、それぞれの行政需要に見合うような広さなども考えながら、そのときに必要なものをつくりたいという思いがあるです。そういったニーズがあるという需要についても考えたいというところですから、こういった施設の検討をしたいという思いです。","id":"exchange-022"},{"speaker":"中塚委員","kind":"質問・要望","question":"こういった施設を検討したいとはおっしゃるのですけれども、つまりその行政需要の中に保育園や高齢者施設はあるということでよろしいのでしょうか。ぜひ進めていただきたいという思いなのですけれども、いかがか尋ねました。","respondent":"柏原企画調整課長","answer":"こちらの要望書にもあるように、福祉であったり子どもの施設であったり、さまざまな行政ニーズがあるという行政の課題があります。それに対応していくために、そういったニーズ、行政需要の中にはそういったものも入っているということでご理解いただければと思います。","id":"exchange-023"},{"speaker":"中塚委員","kind":"質問・要望","question":"地域からは認可保育園はもちろん、特養ホーム、また公園や防災広場など、さまざまな願いがありますので、ぜひ交渉を積極的に進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"松永委員","kind":"質問","question":"平成２７年、平成２８年、平成２９年のここ３年間ではそれぞれどのような結果が出たのでしょうか。このホームレスの実態調査に関してはどのような方法で行われているのか、この２点を伺いたいと思います。","respondent":"矢木生活福祉課長","answer":"１点目ですが、委員ご指摘の調査につきましては、都による外観調査ということで年に２度、８月と１月に実施しています。両方ありますが、こちらにつきましては２名１組になりまして、巡回して調査を行うといった形になってあります。","id":"exchange-025"},{"speaker":"松永委員","kind":"質問","question":"２名１組という形なのですけれども、これは都の８月と１月の調査と何か変わってくるのか、その点についてお伺いします。昨年度に比べて約２６５万円から約５８７万円と、約３２２万円増額となっておりますけれども、その理由についてお知らせください。","respondent":"矢木生活福祉課長","answer":"私どもは２３区を５つのブロックに分けまして、平成２７年４月から生活困窮者自立支援法の施行に伴い、自立支援センターもつくってあります。","id":"exchange-026"},{"speaker":"松永委員","kind":"質問","question":"例えば若年層のホームレスについて伺いたいのですが、少しあれなのですけれども、今。そういったネットカフェ難民等に対する対策というものは、今後とっていかれるのかどうか、その点について伺いたいと思います。","respondent":"矢木生活福祉課長","answer":"ネットカフェやファストフード店における若年層を中心としたホームレスの方についての対応ですが、営業妨害的なところも出てきてしまいますし。ですので区としては特に対応する考えはございません。","id":"exchange-027"},{"speaker":"松永委員","kind":"質問・要望","question":"少し関連しますが、１４６ページの生活保護費についてなのですけれども、答えられる範囲でいいのでどういう結果が出ているのかお知らせください。平成２８年度ではおよそどれくらいおられたのか、またどういう結果を得られているのか、改めて伺いたいと思います。","respondent":"矢木生活福祉課長","answer":"平成２８年度７月末現在で５,６２９名ということで、２０代、３０代の方につきましては２８６名といった状況になってあります。今、数が見当たりませんので、後ほど出します。","id":"exchange-028"},{"speaker":"松永委員","kind":"質問","question":"そうした自立支援の中でいろいろと取り組まれているということで、少しお伺いしました。これは主にどういった理由で入所されているのか、この８,３０６日というのは、それらについて伺いたいと思います。","respondent":"矢木生活福祉課長、中山障害者福祉課長","answer":"先ほどのご質問ですが、平成２８年度につきましては、就労して自立廃止になりましたのが４０世帯４５名ということになってあります。こちらの緊急一時保護の短期入所になりますが、８,３０６日分ということでショートステイを利用された方の数になります。","id":"exchange-029"},{"speaker":"松永委員","kind":"質問・要望","question":"先ほどの自立支援につきましてもしっかりと今後とも取り組んでほしいと求めました。障害者虐待防止対策費として６０万円とあるのですが、そのパンフレットをどのような形で今周知に活用されているのか伺いたいと思います。","respondent":"中山障害者福祉課長","answer":"虐待につきましてはパンフレットのほか、施設の職員が業務対応マニュアルということで活用しております。こちらについては研修等のときに活用すると同時に、パンフレットについては広く区民に周知することを目的に配布しているものです。","id":"exchange-030"},{"speaker":"松永委員","kind":"質問・要望","question":"例えばそういったパンフレットを広く周知するため、地域センター、病院など、そういった関係機関にやはり配布というか置いてほしいと求めました。それについて少し伺いたいと思います。","respondent":"中山障害者福祉課長","answer":"現在、病院ですとか地域センターには置いていない状況ですので、配布先について今後検討してまいります。障害者だけではなく子どもの児童虐待ですとか高齢者虐待、ＤＶ、人権啓発課のほうでまとめて周知のパンフレットやポスターをつくっているところです。","id":"exchange-031"},{"speaker":"松永委員","kind":"質問","question":"最後になりますが１３８ページの幼児二人同乗用自転車レンタル事業補助、１３万２,０００円について伺いたいと思います。今現在このレンタル自転車について平成２７年度、平成２８年度の利用実績がどういった形になっているのか伺いたいと思います。","respondent":"高山子ども育成課長","answer":"こちらの事業につきましては、事業発足の当初は適正な乗車方法の啓発を先導的に区が示していきたいということで事業を開始したものです。こちらの実績といたしましては、具体的には６歳未満で、２人以上のお子さんをお持ちの方に利用者負担前提でレンタル事業を実施しています。","id":"exchange-032"},{"speaker":"松永委員","kind":"質問","question":"２台、１台という形なのですけれども、実際、保護者からすると今現在ではやはりレンタル自転車ではなくて普通に買われている方が多いと思います。","respondent":"高山子ども育成課長","answer":"事業発足当初は、まず法改正の周知徹底を速やかにやらねばならないということでこの事業を開始いたしました。なお、自転車の値段等も非常に廉価になってきているという背景を踏まえまして、この事業の見直しについて考えているところです。","id":"exchange-033"},{"speaker":"藤原委員","kind":"質問","question":"毎回伺っていると思うのですが、それと、他自治体等からの視察はどういう形になっているかということをお伺いします。それと１４５ページの障害児者総合支援施設なのですけれども、それと児童学園は八潮に仮移転し運営されて、この運営状況についてもお伺いします。","respondent":"大串福祉計画課長、松山高齢者地域支援課長、飛田障害者施策推進担当課長、中山障害者福祉課長","answer":"そちらでの対応というふうになっております。マスコミ等の取材も多く来ているというふうに認識をしています。友愛活動は歴史が古く、全国老人クラブ連合会で、まず話し相手を基本とした暮らしを支え合う高齢者相互の支援活動として始まりました。旧品川児童学園の跡地で新しく建設中の（仮称）品川区立障害児者総合支援施設についてですが、その後、ちょうど山留め等を始めているところです。八潮のこみゅにてぃぷらざ全体の館の使い方とか、前運営事業者がすごく苦労をしながら運営をされたところです。","id":"exchange-034"},{"speaker":"藤原委員","kind":"質問","question":"その辺のシステムについてどう思うかと、ソフトな生きがいを感じられてこれはすばらしい制度だと思うので、その辺についてお伺いします。","respondent":"松山高齢者地域支援課長、飛田障害者施策推進担当課長","answer":"その連絡会の中で、なかなか難しい支援の必要な方がいらっしゃった場合は、区としては在宅介護支援センターを通じてつないだりしております。今まで児童学園の機能でした児童発達支援センターは同じように行います。ショートステイ、就労支援Ｂ型ということも入れまして、子どもから大人まで、児・者という施設になります。","id":"exchange-035"},{"speaker":"藤原委員","kind":"質問","question":"建設の時点からもう目的が変わっていれば、より適切なところに移すべきだと思うのですけれども、それはいかがでしょうか。５年に一遍の厚生労働大臣賞を品高連がいただけるという話を伺ったのですけれども、もし課長にその辺の情報が入っていれば説明していただけますか。","respondent":"秋山財政課長、松山高齢者地域支援課長","answer":"これが改築等になって性格が変わってくるというところで検討、いろいろ状況が変わってきたところをあわせて変えていく必要があると思ってあります。１０月の全国老人クラブ大会に会長が行きまして受賞を受けるという段取りの連絡が東京都のほうからまいりました。品川区高齢者クラブ連合会の活動が高く評価された結果だと、うれしく思っております。","id":"exchange-036"},{"speaker":"藤原委員","kind":"質問","question":"次が１９５ページの国民健康保険制度と、２１３ページの後期高齢者医療制度についてお伺いしますが、収納率が１位だったということを歳入のときに伺いましたけれども、一方で国保の保険料が少し高いのではないかという思いで質問するのですが。","respondent":"三ッ橋国保医療年金課長","answer":"平成２８年度の被保険者数ですが、約８万３,０００人となっております。","id":"exchange-037"},{"speaker":"藤原委員","kind":"質問","question":"その中で、厚生委員会では報告されたと思うのですけれども、国保の制度が大きく改正するというような情報が入っていますが、具体的にはどのような動きをするのかの説明を求めました。","respondent":"三ッ橋国保医療年金課長","answer":"平成３０年度からは東京都が主として財政運営を担っていくというような制度になり、制度の安定化を図るということが目的です。具体的には医療給付費が東京都から全額区に入って、区は納付金を東京都に支払うという形で安定化を図るというものです。","id":"exchange-038"},{"speaker":"藤原委員","kind":"質問・要望","question":"本当にこれは皆保険という意味において国家の根幹ですから、安定していただきたいという思いが、本当に私にはあります。今後、保険料はどうなるのか、もうできるだけ上げないでいただきたいのですけれども、その辺についてはいかがか尋ねました。","respondent":"三ッ橋国保医療年金課長","answer":"年々医療費が高額になってまいりまして、国や都からもできる限り法定外繰入金等々考えるようにというふうに言われております。特別区２３区全体、どこの区に行っても、区といたしましてもできる限り保険料を上げないように努力してまいりたいと思います。","id":"exchange-039"},{"speaker":"藤原委員","kind":"質問・要望","question":"できる限り保険料を上げないよう、これは皆さんが受ける医療ですから、ぜひそういう意味で安定させていってほしいと求めました。後期高齢者医療制度ですけれども、今の被保険者数は８万３,０００人ぐらいと伺っているのですけれども、傾向があれば教えていただけますか。","respondent":"三ッ橋国保医療年金課長","answer":"今まで平成２８年度と平成２９年度が同じものでございまして、来年度平成３０年度、平成３１年度について今現在見直しを図っているところです。公費を引いたもの、その総額が保険料となっておりまして、そちらを所得割であったり均等割であったりに案分しているものです。","id":"exchange-040"},{"speaker":"藤原委員","kind":"質問","question":"事務的な処理をする課長に保険料のことを具体的にどうしてほしいというのは違うかもしれませんけれども、日本全部、品川区のことですけれども。","respondent":"三ッ橋国保医療年金課長、柏原企画調整課長","answer":"保険料の部分ですけれども、医療費の適正化というものが一番大きいと考えています。どうしてもだんだん医療費等が上がってまいりますけれども、少しでも抑制できるように区として何か努力をしてまいりたいと考えています。今の財政の状況であったり、継続的に運営ができるように保っていくかというのは、品川区としても大きな行政の課題だというふうに捉えております。","id":"exchange-041"},{"speaker":"藤原委員","kind":"質問・要望","question":"自分の質問で、いわゆる予防、医療費よりも予防ということにこれから視点を当てていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"吉田委員","kind":"質問・要望","question":"同じ項から３目障害者福祉費、１３８ページの２項児童福祉費１目児童福祉総務費、聞けるところまで伺いたいと思います。私たちが求めてきた、生活者ネットワークが求めてきたレベルアップのための事業として理解していいのでしょうかというのが１点です。","respondent":"中山障害者福祉課長","answer":"１つには窓口の受付職員の非常勤経費として１名、それから新たに指導検査を始めましたので、専門の会計士を週２日雇用しております。あるいは不十分な説明になっているのではないかということについては、職員のスキルアップについて引き続き努力してまいりたいと考えております。","id":"exchange-043"},{"speaker":"吉田委員","kind":"確認","question":"相談支援の、障害者の方たちが計画相談などに行く窓口についてはこの事業に入っていないのでしょうか。その辺を確認させてください。","respondent":"中山障害者福祉課長","answer":"それで地域の相談支援センター、そちらの経費というところですが、少々お待ちください。自立支援サービスの計画相談支援事業、それぞれの地域のケアマネージャーの経費のほうも計上させていただいているところです。","id":"exchange-044"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひ相談支援専門員の数を増やすということを求めたいのですが、お考えをお聞かせください。そして、歳入のところで児童の計画相談支援体制について伺ったのですが、これはもう労働的にも無理なのではないかなと思いました。","respondent":"中山障害者福祉課長","answer":"児のほうは歳入のときに１００件から１５０件ということでかなり大変な状況の中で対応しているところなのですが。そこはまだ現在できていないところですので、少し考えていければと考えています。","id":"exchange-045"},{"speaker":"吉田委員","kind":"質問・要望","question":"自立支援協議会の議事録の公開をこれまで求めてまいりましたが、このたび実現をしてよかったと考えています。知的障害者、精神障害者それぞれの実績の数字と実績についてどういうふうに評価しておられるかの説明を求めました。","respondent":"中山障害者福祉課長","answer":"それぞれ３障害についての内訳というのは設けておりません。それで生活訓練の実績ですが、延べ人数で約６００件のご利用があるような状況です。","id":"exchange-046"},{"speaker":"吉田委員","kind":"質問・要望","question":"やはり障害種別と言うのですか、それで初めて次の計画をどうするかと検討ができると思いますので、他にもいろいろあります。２０１６年度の予算特別委員会でこの事業について質問をしたときに、周知の問題もあって４月開始は難しいというふうに答弁されています。","respondent":"中山障害者福祉課長","answer":"申し訳ございません。在宅レスパイトのお話なのか、途中からピッコロのレスパイトなのか、そちらが私のほうでよく聞きとれなかったので、もう一度お願いいたします。","id":"exchange-047"},{"speaker":"吉田委員","kind":"質問","question":"なぜ要綱で対象を絞ったのか、その方たちがそれほど対象者としていないのであれば、もう少し対象者を広げるという考えはできないでしょうか。要綱の読み取り方と、もう少し対象者を広げられないかということについて、答えるよう求めました。","respondent":"中山障害者福祉課長","answer":"それを横引きにして区でも対応しているような事業となっております。今後の課題ということで、例えば学校に通われているのだけれども、そこのところについてどうするかは検討させていただければと考えています。","id":"exchange-048"},{"speaker":"吉田委員","kind":"質問・要望","question":"最後、１３８ページの２項児童福祉費１目児童福祉総務費、ひとり親家庭支援事業です。この数字をどのように評価したらいいのか、事業実績について少し説明をお願いいたします。","respondent":"廣田子ども家庭支援課長","answer":"平成２７年度と平成２８年度では、小学校低学年まで入っていた対象を、小学校の高学年から高校生までに変えてあります。平成２８年度から冬期も５日間ということで日にちを増やしたことが大きな要因で、平成２８年度は丸亀製麺と警視庁へ見学に連れていっております。","id":"exchange-049"},{"speaker":"吉田委員","kind":"質問・要望","question":"それからボランティアのコーディネートを行っているキッズドアに伺ったら、ボランティアの確保が難しくなるのではと心配をしていらっしゃいました。今後の方向性と、今年度の新規事業になりますが、低所得者向け学習支援の事業の進捗について、時間の範囲内での説明を求めました。","respondent":"廣田子ども家庭支援課長","answer":"ボランティアについては今のところ確保できています。新しい学習支援事業につきましては、１０名定員で今のところ４名来ていて、新しく３名入る予定で順調に進んでいるところです。","id":"exchange-050"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"そして、１３６ページ、障害者福祉施設運営費、高次脳機能障害専門相談員についてもお伺いいたします。初めに１３３ページ、高齢者見守り事業、地域見守りネットワーク事業についてお伺いしたいと思います。","respondent":"大串福祉計画課長","answer":"その説明会後には幾つかの町会・自治会からお問い合わせをいただき、趣旨をご理解いただき、今回このような数になったです。引き続きＰＲ、普及啓発といったことを進めていければというふうに考えているところです。","id":"exchange-051"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"もう１点お伺いしたいのですけれども、これは平成２７年度、荏原第四地区では西中延三丁目町会が今助成を受けて活動していると思われるのですけれども、第四地区に限って今年度はどのような形で、他に参加団体が増えたのかをお知らせほしいと求めました。","respondent":"大串福祉計画課長","answer":"各町会の取り組みということでしょうか。","id":"exchange-052"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"続きまして１３６ページ、障害者福祉施設運営費の中の高次脳機能障害専門相談員についてお伺いいたします。この金額が３５５万５,０００円なのですけれども、これは常勤なのか、それと何名体制で行っているのか、の説明を求めました。","respondent":"中山障害者福祉課長","answer":"こちらの高次脳機能障害専門相談員ですけれども、週に２回の非常勤の先生をお願いしている経費です。","id":"exchange-053"},{"speaker":"高橋（伸）委員","kind":"質問","question":"その中でもやはり失語です。そういった相談、失語症の方に対して高次脳機能障害なのですよという相談を受付けていらっしゃるのかお伺いしたいと思います。","respondent":"中山障害者福祉課長","answer":"失語症も当然その中の症状ということになっております。ただ、失語症に関する相談件数の具体的な数について細かいところまでは資料を持ちあわせておりません。","id":"exchange-054"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"その会だけではなく啓発活動、仲間づくりをしていただきたいと思うのですけれども、その辺のところをお聞きしたいと思います。","respondent":"中山障害者福祉課長","answer":"今、高次脳機能障害者と家族の会があるほかに、失語症友の会もあります。例えば記憶障害ですとか注意障害ですとか、広くいろいろな方のお声を聞きながら家族会が運営できるような形でサポートしていければと考えています。","id":"exchange-055"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"それからこれは要望なのですけれども、目黒区の心身障害者センターで失語症会話パートナー養成講座というのを行っております。ぜひ養成講座、会話パートナー養成講座をとり入れてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"あくつ委員","kind":"確認","question":"東京都が標準様式を定めたことで、品川区でも３年前でしたでしょうか、これをとり入れて配布をされていらっしゃいます。確認なのですが、対象となる方の範囲、また配布場所についての説明を求めました。","respondent":"中山障害者福祉課長","answer":"高齢者ですとかさまざま周囲の方にちょっと手伝いをしてほしい、そういうふうに望まれる方に対して、区として配布をしております。現在の配布場所ですが、障害者福祉課、高齢者福祉課、それから３つの保健センターで配布をしています。","id":"exchange-057"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私の地域で一番近いところはどこなのでしょうかというところで調べたところ、在庫がなかったら困ってしまうので所長に確認をしてから。お困りの支援が必要な方、こういう場所での配布をぜひ行っていただきたいと要望しますが、ご検討いただけますか尋ねました。","respondent":"大串福祉計画課長","answer":"委員ご案内のように全地区で支え愛・ほっとステーションを開設することができました。そちらの窓口等でこういったヘルプカードの配布についても実施していきたいというふうに考えているところです。","id":"exchange-058"},{"speaker":"あくつ委員","kind":"質問・要望","question":"次に、品川区障害者週間・記念のつどいについて伺います。こういう取り組みをぜひ活用していただきたいと思うのですが、もしくは人権啓発課長、どちらかにお答えをほしいと求めました。","respondent":"島袋人権啓発課長","answer":"しかし１２月の人権週間における講演と映画のつどいですが、こちらは講演がメインとなっています。したがいましてどのような方法で行うのがふさわしいのか研究してまいりたいと考えているところです。","id":"exchange-059"},{"speaker":"あくつ委員","kind":"質問・要望","question":"障害者福祉課の所管だと思うのですが、私としてはこれは歓迎しているのですけれども、その意図を伺いたいのが１つです。障害とは何かということを考える、非常にいい絶好の手法になりますので、今回こういったことが行われるのかどうか伺いたいと思います。","respondent":"中山障害者福祉課長","answer":"最初２年間はやはり障害者福祉課で、地域で共生していくということを考えますと、障害のある方ない方にかかわらずということになってくると思います。その後２時から２時３０分の間で、ちょうど品川区在住の作家にギャラリートークをしていただく予定になっております。","id":"exchange-060"},{"speaker":"あくつ委員","kind":"質問・要望","question":"続けて伺いますけれども、演者や担当課、社協スタッフの方も大変ご苦労されたというのは聞いております。この２つをお伺いします。","respondent":"中山障害者福祉課長","answer":"来年度についてなのですが、来年度も今のところ中小企業センターの改修が続く予定だと聞いておりますので。その中で、会場の特にステージと、それから観客席のところについては、何かしら日よけができるような工夫をしていきたいと考えております。","id":"exchange-061"},{"speaker":"あくつ委員","kind":"提案","question":"平成２５年度一般質問で、そういったものを品川区で実施したらどうですかということは申し上げていたのですが、このようなご答弁がありました。ぜひこの模擬訓練を広げていってほしいと求めましたが、この２点について伺いますとの意見を述べました。","respondent":"寺嶋高齢者福祉課長","answer":"ただいまご紹介いただきました、今年５月２６日に品川第二地区の地区民協主催ということで模擬訓練を実施していただきました。まず今回品川第二地区で模擬訓練が実施できたのは、会議を行ってきたというその下地があってこその結果だというふうに捉えております。","id":"exchange-062"},{"speaker":"あくつ委員","kind":"質問","question":"引き続きそれについて内容を伺いたいのですが、今回のくるみぷらんの中でこれがどういう形で構築をされているのか、最後に伺いたいと思います。","respondent":"寺嶋高齢者福祉課長","answer":"品川区で実施しております徘徊高齢者の探索という取り組みにつきましては、しなメールに登録をいただきまして、徘徊情報。それ以外にはＧＰＳ機能のついた機器の貸与、それからアイテム、各在宅支援センターに連絡をすれば本人が特定できるというシステムを導入しています。","id":"exchange-063"},{"speaker":"安藤委員","kind":"質問・要望","question":"私からは、１３９ページ、区立保育園の民営化、待機児童解消について伺います。多数派になっているのか伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"次に、運動会の会場ですけれども、公立と同じように各園で学校の校庭をお借りするなどして実施しております。運動会の場所につきましては、保育課にご相談があった場合はこちらで対応もしております。","id":"exchange-064"},{"speaker":"安藤委員","kind":"質問・要望","question":"伺いますが、そして勤務年数が５年以下の正規保育士というのは、全体の何％を５年以下の保育士が占めているのか教えてください。同様に、品川区立の保育園はどうかということで、区の正規保育士の数字も伺いたいと思います。","respondent":"大澤待機児童対策担当課長、黒田人事課長","answer":"お尋ねのあった平均就業年数ですが、全体で５.１％、正規職員で４.６％という数字が出ております。５年以下の就業年数につきましては、全体で６９.７％、正規職員で７７.２％という調査結果になってあります。品川区の正規の保育園職員の平均勤務年数ですが、平成２９年４月１日現在の在籍の職員で、平均で１６.４年です。次に、採用した職員は当然ゼロということになりますが、勤続年数が５年以下ですと合計で３７.２％です。","id":"exchange-065"},{"speaker":"安藤委員","kind":"確認","question":"保育のスキルの蓄積や交流などが弱くなり、結果として保育の質にも影響してくるのではないかと思いますけれども、どうでしょうか。伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"平成２７年から都のほうでキャリアアップ補助金の導入をしておりますので、大分状況は変わってきているのではないかというふうに考えております。","id":"exchange-066"},{"speaker":"安藤委員","kind":"質問","question":"ですから、この点がやはり保育の質に影響をしてくるのではないかということを伺ったので、もう一言答弁をお願いしたいと思います。それから来年４月の申請数は何人と見込んでいるのか、またその根拠についても伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"０から２歳児の平成３０年４月の入園の見込みですが、２歳児が４２７人、計２,３０１人となります。申請に関しましては０歳児から順に１,０５２人、１歳児が１,３７５人、２歳児が５１７人、計で２,９４４人を見込んでおります。","id":"exchange-067"},{"speaker":"安藤委員","kind":"質問・要望","question":"それを伺ったのではなくて、保育の質にかかわることなのではないですか、勤務年数と保育の質との関係をどう考えているのですかと伺ったので。それを求めますけれどもいかがか尋ねました。","respondent":"大澤待機児童対策担当課長","answer":"保育士の定着は保育の質に関連すると認識していますので、保育士が定着できるように処遇改善に取り組むです。ニーズ量を算出していますので、今回の予測には反映していませんけれども、今後の見直しの中では反映させていきます。","id":"exchange-068"},{"speaker":"安藤委員","kind":"質問・要望","question":"子ども・子育て計画ではかなり緻密にやっていると言うのですけれども、来年４月にゼロにしなければいけないのです。仕事を辞めるという方が出るわけですから、そして分園方式も含めて必要な対策をとっていくといったことを求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"筒井委員","kind":"質問","question":"私からは１３５ページ、１３３ページ、そして時間があれば高齢者地域配食サービス事業について伺いたいと思います。こうした高齢者と多世代の方々の交流、世代間交流等を考えたイベントや行事、またそうした関連した活動というのは行われているのか尋ねました。","respondent":"松山高齢者地域支援課長","answer":"こちらですけれども、運営者が企画する交流イベント、あるいは季節行事としまして、年間１３件ほど行われております。周知につきましてはまだまだ不足しておりますので、今後ＰＲに努めていきたいと考えています。","id":"exchange-070"},{"speaker":"筒井委員","kind":"質問・要望","question":"利用状況はどうなっているのか、そしてその利用者数は多いのか少ないのか、それからその評価としてどうお考えなのかをお伺いします。この２点をお伺いします。","respondent":"大串福祉計画課長","answer":"その地域支援員のほうに窓口で相談のあったご要望に応じた形でコーディネートをして、あるいは簡易なお手伝いといったことを実施しています。少ないところはやはり開始時期からまだ日が浅いといったところで、件数が伸びてきていないといったところです。","id":"exchange-071"},{"speaker":"筒井委員","kind":"質問","question":"２４８件が、かなり潜在的にこうしたサービスを必要としている高齢者の方はもっと多くおられると思います。ぜひともその改善をお願いしたいところなのですけれども、その点のご見解はいかがか尋ねました。","respondent":"大串福祉計画課長","answer":"さまざまな形でＰＲを行ってまいりたいと考えています。さまざまな手段・場所を活用しながら、この支え愛・ほっとステーションのご紹介・ＰＲに努めていきたいというふうに考えています。","id":"exchange-072"},{"speaker":"筒井委員","kind":"質問・要望","question":"現在６２町会ということで、ぜひ行っていただきたいのですけれども、例えば町会内に福祉に興味がある人が必ずいらっしゃると思うのです。一見、それぞれの事業の横の連携ということを行っていただきたいのですけれども、そのあたりのご見解はいかがか尋ねました。","respondent":"大串福祉計画課長","answer":"あるいは従来から見守りをやっていただいている民生委員ですとか、そういったさまざまな地域で高齢者を支える担い手の方たちがいらっしゃいます。そういった方たちとの連携を図りながら、あるいは支援といったものもできてくるのかなというふうに考えているところです。","id":"exchange-073"},{"speaker":"鈴木（博）委員","kind":"質問","question":"成果報告書１３８ページ、２項児童福祉費、時間があれば幼保一体施設運営費に関連して認定こども園についてお伺いしたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"乳幼児人口や保育園への希望者の割合が今後急激に増加しますと、ゼロの実現は難しくなってまいりますけれども、現在、先ほど申し上げた想定以上のお申し込みがあった場合の、対応策を検討していますので、何らかの対応をする考えです。","id":"exchange-074"},{"speaker":"鈴木（博）委員","kind":"質問","question":"しかしながら、事業費のほうも心配です。最近の保育課の事業費の状況と財源構成はどのようになっているのか、その点について伺いたいと思います。","respondent":"佐藤保育課長","answer":"逆に一般財源は５７％で、約４％減っております。国や都の補助金を最大限活用していることが反映されていると考えています。","id":"exchange-075"},{"speaker":"鈴木（博）委員","kind":"質問","question":"ただ、国などの補助金というのは待機児童対策のうち施設整備の分が大きいというふうにお聞きしています。利用者負担である保育料の徴収の考え方を今一度簡単にごの説明を求めました。","respondent":"佐藤保育課長","answer":"したがいまして、応能負担が基本であり、第１子、第２子にかかわらず、応能負担をベースとして保育料を負担していただくことが原則です。この原則を踏まえまして、多子軽減や低所得世帯の軽減策を実施しているものです。","id":"exchange-076"},{"speaker":"鈴木（博）委員","kind":"確認","question":"応能負担が大原則であるということは確認できました。保育課としてはこの事態に対してどのような対策をお考えになっているのかご説明ください。","respondent":"佐藤保育課長","answer":"事務仕事や事業・行事等の廃止・縮小・見直しを検討しておりまして、既に２８項目の事業や事務について縮小を図る予定です。今後３年ぐらいはまだ必要だと考えていますので、順次事務や事業等の省力化を進めまして、保育士等の年休の取得の拡大につなげたいと考えています。","id":"exchange-077"},{"speaker":"鈴木（博）委員","kind":"質問","question":"次に、保育所の感染症対策についてお尋ねいたします。区はこの現状をご認識されているのでしょうか、お伺いします。","respondent":"大澤待機児童対策担当課長","answer":"保育園の嘱託医を決めるに当たっては、難しい状況になっているということはお聞きしております。新規開設の事業者につきましては、見つからない場合には医師会に相談するなど、区としても調整を図ってまいりたいと考えています。","id":"exchange-078"},{"speaker":"鈴木（博）委員","kind":"提案","question":"特に何回か一般質問、委員会でも取り上げてきましたが、今、保育園では感染症が次々と大流行しています。保育園をまたがって幾つかの地域ごとに区が立ち上げることを再度提案いたしますが、それに対するお考えはいかがか尋ねました。","respondent":"佐藤保育課長","answer":"園医の確保が難しい状況も先ほどご答弁したとおりです。その辺を見直して、委員ご提案のブロック別の相談体制についてはさまざま調査を進めて、検討等していきたいと考えています。","id":"exchange-079"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"面接時に１万円相当の品物が選べるカタログ、事業に使用できるようにすれば、子育て家庭にとっては非常に喜ばれるのではないでしょうか。子育て応援券の発行を再度要望したいと思いますが、区のお考えはいかがか尋ねました。","respondent":"鷹箸品川保健センター所長","answer":"もう既に実施しています産後ケアサービスの自己負担金といったものにも使えるような子育て応援券への変更ということは、現在検討しています。","id":"exchange-080"},{"speaker":"鈴木（博）委員","kind":"質問","question":"次に、しながわネウボラネットワークについてお伺いします。現在、５カ所で行われている子育てネウボラ相談員による子育て相談の相談件数の推移と、その相談内容についても簡単にご紹介ください。","respondent":"高山子ども育成課長","answer":"昨年度は事業の構築に当たって見込みました件数を下回るようなものではあったのですが、既に昨年度を上回る勢いでこの利用が進んでいるところです。これは今年度に置きかえますと、徐々に相談事業が定着し、そして適切に相談につながっているという認識でおります。","id":"exchange-081"},{"speaker":"鈴木（博）委員","kind":"意見","question":"今後、品川区民とご家族にとって大きな育児支援になると期待されますので、ますますの発展を期待しております。ところで、現在国が進めている子育て世代包括支援センターの構想と、品川区のネウボラネットワークの関連についても簡単にご説明くださいとの意見を述べました。","respondent":"高山子ども育成課長","answer":"妊産婦や保護者の相談に保健師等の専門家が対応するとともに、必要な支援を調整、そのようなものがこのセンターの目指す姿かと考えております。","id":"exchange-082"},{"speaker":"木村委員","kind":"質問","question":"お聞きいたします。平成２７年にバリアフリー計画が策定された大井町を例に挙げてお聞きしますけれども、また道路や公園のバリアフリー計画等の説明を求めました。","respondent":"大串福祉計画課長、中村都市計画課長","answer":"ご紹介いただきました大井町、それから旗の台と２地区でバリアフリー計画を策定し、順次今その計画を進めているといったところです。ハード面ですけれども、大井町、それから今年度旗の台のほうの駅周辺バリアフリー計画を策定いたしまして、今後具体的に周辺の事業者等の協力を得ながら進めていくという計画です。","id":"exchange-083"},{"speaker":"木村委員","kind":"質問・要望","question":"これは要望です。高齢者の活動に拍車がかかることに対して、行政としての考えの説明を求めました。","respondent":"松山高齢者地域支援課長","answer":"そういった自主的な活動をしている団体の方々に向けまして、区としてはバックアップをしていきたいと考えています。そういった地域の力が生かせるような場づくりというのも大切であると考えております。","id":"exchange-084"},{"speaker":"木村委員","kind":"意見","question":"本区でも単独世帯の割合が高く、７年前の平成２２年にはもう３８.１％と全国平均の２４.８％を大きく超えています。今後もこの事業が大変注目されると思いますけれども、特に注意をして進めていきたいという点がありましたらの説明を求めました。","respondent":"松山高齢者地域支援課長","answer":"高齢者と一口に言いましても、６５歳の方から９０歳以上の方までいらっしゃるということで、それぞれの高齢者によってニーズが異なってまいります。歩いて通える、高齢者が集まれる、気軽にふらっと寄れる場というのも必要になってくるかと考えています。","id":"exchange-085"},{"speaker":"木村委員","kind":"質問","question":"３９５万円余からですけれども、高齢者、先に言ったようにグラウンドゴルフ等の６つの趣味・健康づくり等の事業があります。お聞きいたしますけれども、健康が第一と考える区民が増えてきていることに対し、区としてはこの考えをどのように評価するのかの説明を求めました。","respondent":"松山高齢者地域支援課長","answer":"おひとり暮らしの方が増えるということでは、こういったような事業を通じて仲間づくりというものが大事になってくるかと考えています。あるいはボランティアの方々も、皆さん高齢化が進んでおりますので、この事業を区といたしましては丁寧に進めていきたいと考えています。","id":"exchange-086"},{"speaker":"木村委員","kind":"質問","question":"６０歳以上の区民が町会・自治会を単位として結成した自主的なグループ、現在区内には１１０以上のクラブ、正確には１１４とお聞きしております。お聞きいたしますけれども、この役立つ活動とは具体的にどのようなことがあるのか、あればの説明を求めました。","respondent":"松山高齢者地域支援課長","answer":"高齢者クラブの活動に関するお尋ねについてお答えいたします。地域の公園や神社といったものの清掃活動、あるいは先ほど出ておりました高齢者が高齢者の方を見守る友愛活動等が該当するものと考えています。","id":"exchange-087","title":"町会・自治会支援"},{"speaker":"塚本委員","kind":"質問","question":"２３２ページ、あともし時間がありましたら１４０ページの小規模保育事業等経費、これは連携施設のことについてお伺いしたいと思います。","respondent":"松山高齢者地域支援課長","answer":"こういった事業者の特徴を生かして、協議し、相談しながら進めている次第です。事業者に対しまして、区ともう一度協議をさせていただいて提出してもらっていますので、今のところはこちらの今ある仕組みで行きたいと考えています。","id":"exchange-088"},{"speaker":"塚本委員","kind":"質問・要望","question":"今後の総合事業の発展という意味で、発展とか持続可能性というか、ぜひご検討いただきたいというふうに要望したいと思います。この和光市と品川区というか、全国と言ってもいいかもしれませんが、認定率の違いをどのように分析しているのかお聞かせほしいと求めました。","respondent":"寺嶋高齢者福祉課長","answer":"その取り組みの内容によって一定程度差が出てくるということ、他市の取り組みの詳細までは、申しわけございません。把握はしていないのですが、品川区は先ほどご案内いただいたとおり、ほぼほぼ平均の値だというふうに捉えております。","id":"exchange-089"},{"speaker":"塚本委員","kind":"質問・要望","question":"どういうゴールを目指してこの保険事業というのを進めていくのかということを非常に共有しているというところが見受けられるかなと思います。","respondent":"寺嶋高齢者福祉課長","answer":"当然介護サービスはもとより、介護保険制度は成り立たないというところにつきましては、私どもも十分認識しているところです。保険料の見込み、今の段階では見込みまして、第七期に向けて取り組んでいるといったところです。","id":"exchange-090"},{"speaker":"塚本委員","kind":"意見","question":"そういう意味では、ある意味この理念の共有とか、そういうものが進めやすい体制になっているというふうにも言えると思います。特に利用者にこういったものを、ぜひお願いしたいというふうに思いますけれども、もう一言だけ最後ほしいと求めました。","respondent":"寺嶋高齢者福祉課長","answer":"ただいまご指摘いただいたとおり、利用者に対する周知は引き続き徹底して行っていきたいと思います。特に在宅での生活支援ということで、品川区の場合は特に、従来から地区の２０ある在宅介護支援センターと地域が非常に一体化してやっておりますので。","id":"exchange-091"},{"speaker":"塚本委員","kind":"意見","question":"２、３年でいいのですけれども、あとは生活習慣病重症化予防事業といったことを実施されていたかと思います。それらの事業の実績、また何か課題があればあわせてお聞かせほしいと求めました。","respondent":"三ッ橋国保医療年金課長","answer":"高額療養費ですが、前年度比よりもプラス１.５３％程度上がっておりますので、高額療養費につきましては若干上がっております。軽度リスク者対策、１人当たり月額ですと４０万円ほどかかってしまう状況がありますので、そちらに対しても十二分に取り組んでいるところです。","id":"exchange-092"},{"speaker":"塚本委員","kind":"質問","question":"平成３０年から財政運営の責任主体が区から都に移管されるというところで、基本的には一律という考え方が原則というか根底にあるのかもしれません。２３区においては、その自治体の保険料の増減ということは、どういうふうな関係性にあるのかの説明を求めました。","respondent":"三ッ橋国保医療年金課長","answer":"今現在は２３区が統一保険料方式を使っておりますので、平成３０年度からはそれぞれの各区に保険料率が算定されますので、分かれてまいります。","id":"exchange-093"},{"speaker":"塚本委員","kind":"質問・要望","question":"これは品川区が今後も続けていくという事業ですので、ぜひ力を入れて重症化予防等について成果が上がるよう事業を続けていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-094"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"２３３ページの介護保険の地域包括支援センターについて、それから１３３ページの障害者福祉費についてお伺いをしたいと思います。この２３３ページの２,７４８万円余というところの確認と、１カ所当たり幾らぐらいなのかということについてまずの説明を求めました。","respondent":"寺嶋高齢者福祉課長","answer":"それから在宅介護支援センターの経費につきましては、２０カ所それぞればらばらなので、１カ所幾らというふうには数字をお出しできないところです。申しわけございません。","id":"exchange-095"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"３億１,０００万円余ということで、２０カ所全体でこの額だということでいいのかということを確認をさせてほしいと求めました。他区の地域包括支援センターはどれくらい委託費が出ているのかをお伺いしたときに、確認をお願いしたいと思います。","respondent":"寺嶋高齢者福祉課長","answer":"１点目の在宅介護支援センターの経費３億円強というのは、総額という意味ではこちらの額になります。公開につきましては、委員ご指摘のホームページに公開しているもののみで今のところは対応しております。","id":"exchange-096"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"厚生労働省でも求められておりますので、ぜひこれはすべきではないかと思うのですけれども、いかがでしょうか。厚生労働省が求めているところも、ぜひこの公表を求めたいと思いますけれども、いかがか尋ねました。","respondent":"寺嶋高齢者福祉課長","answer":"品川区のホームページとして公開しているのは先ほど申し上げたとおりですけれども、２３区につきましては東京都のほうに情報を一括して集約して、東京都のホームページによって公開しているといったスタイルをとっております。","id":"exchange-097"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"都道府県とともに市町村に対してもこれは公表という形で求めておりますので、改めてご答弁をお願いしたいと思います。合わせて３職種で３９人、３職種、それともそれから一気に増えて３職種が８５人ということになっているのかについても実態の説明を求めました。","respondent":"寺嶋高齢者福祉課長","answer":"１点目の公開につきましては、２３区、他の自治体の状況も見ながら検討していきたいと思います。内訳としましては、保健師については４.５人、社会福祉士については３０.５人、主任ケアマネ２９人、その他というふうになっています。","id":"exchange-098"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今日の時点で、私は東京都のホームページを確認したのが今の数字だったのですけれども。市町村に対しても厚生労働省が求めており、またそういう法改正になっていますので、ぜひよろしくお願いしたいと思います。","respondent":"寺嶋高齢者福祉課長","answer":"それから２０の在宅介護支援センターと連携して対応するというシステムをとっていまして。この運用解釈について問題ないというふうにいただいておりますので、今現在この形でベストと思われる対応をさせていただいているところです。","id":"exchange-099"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その点についていかがでしょうか。今回私たちは保健センターの保健師の増員及び地域包括ケア事業への参画ということで要望もいただいているのですけれども、いかがか尋ねました。","respondent":"寺嶋高齢者福祉課長","answer":"現在、品川区の地域包括支援センター、十分、しっかり対応していると自負しておりますが、これからもサービス向上に向けて対応していきたいと考えております。","id":"exchange-100","title":"町会・自治会支援"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"保健師の配置をぜひ求めていきたいと思います。全体としても保健師が足りないですし、こういう形でも保健師が足りないですので、ぜひ増員を。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-101"},{"speaker":"本多委員","kind":"質問","question":"１３１ページの福祉人材確保・定着事業について伺いますが、その前に民生費全般にわたりまして１つお伺いいたします。なかなかトイレの中でも回転しづらいとか、全体的にそのような課題があると思うのですが、その対応をどのようにお考えか尋ねました。","respondent":"中山障害者福祉課長","answer":"委員ご指摘のとおり、例えばストレッチャータイプのものもありますし、最近大きくなる傾向になっております。現在、そういったものに変えていく予定ですので、そういった中ではだれでもトイレの大きさが少し大きくなってくるものと考えております。","id":"exchange-102"},{"speaker":"本多委員","kind":"質問・要望","question":"平成２８年度の取り組みとしましては、実績で３件、平成２９年度も継続しています。平成２９年度が廃止となっているのですが、その部分をどうやってフォローしていくのか、その点についての説明を求めました。","respondent":"寺嶋高齢者福祉課長","answer":"法人を通して助成をするということで始めた事業ですけれども、引き続き各法人に働きかけて、人材確保に努めていきたいと考えているところです。","id":"exchange-103"},{"speaker":"本多委員","kind":"質問・要望","question":"在校生の９割超が利用しているものの、３年の間に離職し返還しているケースも多く、これが１つです。もう１つが、仮称品川福祉人材バンクをつくるという強い決意をもって対策に取り組んでほしいという意見・指摘に対してご見解を聞きたいと思います。","respondent":"寺嶋高齢者福祉課長","answer":"この辺の相談につきましてはこの４月以降も随時入ってきているところで、今、学校側とも内容については詰めているところです。新しい支援策を見つけて、学校の充実と福祉人材の定着に関しては強化していきたいと考えております。","id":"exchange-104"},{"speaker":"本多委員","kind":"質問","question":"介護福祉専門学校、働きながら通うとか、例えば夜学の創設ですとか、他の区内の専門学校との連携とか、新たな何か工夫がやはり必要かと思うのですね。","respondent":"寺嶋高齢者福祉課長","answer":"それからオープンキャンパスを年に８回、９回程度開いておりまして、事前に学校を見ていただくといった取り組みもして今ＰＲに努めているところです。","id":"exchange-105"},{"speaker":"本多委員","kind":"質問","question":"これは世の中ですね、一般論ですが、民間保育士の平均月給は月約２２万円、全産業平均を約１１万円下回る。そして、資格を持ちながら、福祉人材を取り巻く社会環境をどのように捉えているのかの説明を求めました。","respondent":"寺嶋高齢者福祉課長","answer":"ただいまご案内いただきました賃金等につきましては、介護職員につきましてもほぼ同様の数値であるというふうに認識しています。いずれにしましても、いろいろ法人同士の取り組み等もお互いに共有しながら、何かいい策を講じていければというふうに考えております。","id":"exchange-106"},{"speaker":"浅野委員","kind":"質問","question":"そして、１３４ページの自動車運転免許取得経費助成、これらの２点について時間の限り質問します。延べ人数は先ほど言いました１,１４４人ですけれども、また軒数、施設規模というのはどのぐらいなのかについての説明を求めました。","respondent":"寺嶋高齢者福祉課長","answer":"入所先としましては区部に２７名、市部に６０名、それから都外に３名といった状況になってあります。施設規模は、それぞれ定員数が違っているので、申しわけございません、ただいま数字を持ち合わせておりません。","id":"exchange-107"},{"speaker":"浅野委員","kind":"質問","question":"今、都内に３４カ所、区部に２７名、また市部に６０名、都外３名というふうに伺いました。どのような制度と言うのでしょうか、例えばどこまでそういう自由な行動が許されているのかについてお伺いします。","respondent":"寺嶋高齢者福祉課長","answer":"将来的に介護が必要になったときに、基本的に養護老人ホームは介護施設ではありませんので、実際には機能等も含めて介護施設ではないと。その辺がありますので、その後の例えば特養ホームとの連携等につきましては、しっかり対応していく必要があろうかという認識はしています。","id":"exchange-108"},{"speaker":"浅野委員","kind":"質問","question":"さて、１３４ページの自動車運転免許取得経費助成について質問をさせてほしいと求めました。この金額に設定されている理由、多分普通に免許をとるためにかかる費用なのか、また自己負担とかそういうものがあるのかの説明を求めました。","respondent":"中山障害者福祉課長","answer":"そのうち１６万４,８００円分だけを区が負担するというものになっております。おおむね半分程度の、２分の１の助成ということで設定しているものです。","id":"exchange-109"},{"speaker":"浅野委員","kind":"質問","question":"１６万４,８００円の助成ということで、うまく運転と言うのでしょうか、教習が進まない方は自己負担がさらにかかっていくことになるかと思います。","respondent":"中山障害者福祉課長","answer":"ですので、免許が取得できなかったということになると助成はできませんので、１０分の１０の負担になってしまいます。最終的にはこちらの１６万４,８００円をお支払いするような手続きをとらせていただきました。","id":"exchange-110"},{"speaker":"西本委員","kind":"確認","question":"我が子が病気になったら休める、今回もう１つ施設ができましたが、それはどういうことなのでしょうかということ。非常に大きな広がりがある、そういう事業の展開になるのではないかなというふうに思うのですけれども、いかがか尋ねました。","respondent":"佐藤保育課長、廣田子ども家庭支援課長","answer":"就労支援という側面で、計画の達成に向けて一定数の病児保育の施設は開設していかなければならないというように判断をしております。子ども食堂の役割については、区として支援を始めるときに、貧困だけを意識して支援しようと始めているわけではありません。","id":"exchange-111"},{"speaker":"西本委員","kind":"質問・要望","question":"要は地域の力を借りて広げていくということは、本当にすばらしい動きだと私は思っているので、児童センターの活用はどうなのでしょうか。これから検討してほしいと求めましたが、担当の課長からもご答弁をほしいと求めましたが、いかがか尋ねました。","respondent":"佐藤保育課長、廣田子ども家庭支援課長","answer":"１日保育士体験でありましたり、よく見る、交流を持つと話をさせていただいています。地域の方に関しましてはチャイルドステーションということでさまざまな相談を受けているところです。先ほどご答弁いたしましたとおり、さまざまな選択肢を当たりながら、必要に応じて区有施設につきましては所管の課長と連携をとってまいります。","id":"exchange-112"},{"speaker":"西本委員","kind":"質問・要望","question":"そこを間違えないようにしていただきたいのです。やはり親として子ども、子育てをしっかりやっていただけるような、いろいろな事業の展開をしていただきたいと要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-113"},{"speaker":"大沢委員","kind":"質問","question":"２３３ページ、地域包括支援について、それと時間がありますれば１３０ページの法人に対する助成金について伺いますが、まずは先ほど来、何人か委員から話がありましたが、支え愛・ほっとステーションについて概略は先ほど来お伺いしましたので。","respondent":"大串福祉計画課長","answer":"は福祉の身近な相談窓口というのが大きな役割になっております。したがいまして、各地域センターの中に設置し、ちょっとした困り事や相談に応じるというのが大きな目的です。","id":"exchange-114"},{"speaker":"大沢委員","kind":"質問","question":"これは、この事業については地域包括ケアシステムですか、この構築においては大変重要な位置を占めていると思うのですけれども、ではこの地域包括ケアシステムについての定義についてお知らせください。","respondent":"大串福祉計画課長","answer":"これから増えていく高齢者の方たちを地域全体で支えていくという大きなシステムです。あるいは在宅介護支援センターに代表されるような相談体制の整備、あるいは生活支援、それから医療と介護の連携といった多職種連携等々。","id":"exchange-115"},{"speaker":"大沢委員","kind":"意見","question":"さてこの医療と介護の連携においては、この４月に福祉計画課に、地域包括ケア推進係が新設をされたということで承知をしております。そこで、この係の主な目的、それと事業内容についてお知らせくださいとの意見を述べました。","respondent":"大串福祉計画課長","answer":"従来の庶務係、あるいは地域福祉を進めていく担当の係、これを統合した形でこの地域包括ケア推進係というものができたところです。この医療連携という形、大変重要なものと考えておりますし、そちらについても鋭意取り組んでいければというふうに思っております。","id":"exchange-116"},{"speaker":"大沢委員","kind":"質問・要望","question":"次に、先ほど来のお言葉に出てきております医療と介護の連携についてお伺いをします。走り出したばかりですので、そしてまた考えられる支援ができれば、それはどの程度可能であるとお考えになっているのか教えてほしいと求めました。","respondent":"寺嶋高齢者福祉課長","answer":"直近の取り組みとしては医師会に委託をしまして、それから必要な協力体制を組んでいくというところでの強化の支援が必要だと考えておりまして、その取り組みを実施することを計画しています。","id":"exchange-117"},{"speaker":"大沢委員","kind":"意見","question":"今の連携について、まさに先ほど通告をいたしました２３３ページにおける介護支援システムの構築が、ここにも書いてあるように事業化されました。この介護システムの主な機能の導入目的についてお知らせくださいとの意見を述べました。","respondent":"寺嶋高齢者福祉課長","answer":"大きくはまず２点ございまして、１つは高齢者福祉課が実際には扱っております在宅介護支援システム、それから例えば給付管理システムとか。１つは今回この地域包括ケアのシステムということで新しい考え方ができましたので、そういった機能を付加するといった計画です。","id":"exchange-118"},{"speaker":"大沢委員","kind":"質問","question":"今、私が質問をしようとしたところのお答えで、まさにこの連携の上には情報の共有化、そして共有化するための協議が必要だと思いますけれども、それについてのお考えなり取り組みのビジョンというか、それがありましたらの説明を求めました。","respondent":"寺嶋高齢者福祉課長","answer":"歯科医師会、薬剤師会等の方にも入っていただきまして、このシステムについて検討の場を何度か設けてあります。システム上のセキュリティー、それから取り扱い上のセキュリティー、この辺をきちんと精査した上での運用をしていく必要があるというふうな段階です。","id":"exchange-119"},{"speaker":"大沢委員","kind":"質問","question":"２番目の質問はやめます。これから予算編成が始まると思いますけれども、さらなるいいシステムが構築できるようにお願いをして、私の質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-120"},{"speaker":"たけうち委員","kind":"質問","question":"その考え方を伺いたいのと、主要成果報告書の３１ページに、８地域センターでの実績が書いてありまして。１３４ページの知的障害者地域生活サポート事業ですが、利用回数、そして何か課題があるかどうかの説明を求めました。","respondent":"大串福祉計画課長、中山障害者福祉課長","answer":"今現在設置件数として５７４件という累計出ておりますけれども、これの内数が支え愛・ほっとステーションの数です。平成２９年度になって今４０人ということになっていますが、平成２８年度の支援の実績といたしましては、１,２２５件の支援を実施しているものです。","id":"exchange-121"},{"speaker":"たけうち委員","kind":"確認","question":"支え愛・ほっとステーションについてもう１回確認なのですけれども、そのただ考え方、そこをざっくりでいいので教えてください。なかなか見てあげられるのかなと思うのだけれども、先ほど課長がおっしゃったような中で、今後そういったものもできるのかどうかをお聞きします。","respondent":"秋山財政課長、大串福祉計画課長、中山障害者福祉課長","answer":"予算書と決算書の表記の件ですけれども、平成２９年度予算を決定しているのは平成２９年の頭、１月ぐらいです。各地区の取り組みの違いです。相談支援センターであったり、あるいは日中活動の支援の場というところで、もしあったときには適正に対応できればと考えています。","id":"exchange-122"},{"speaker":"たけうち委員","kind":"質問・要望","question":"要望になりますけれども、支え愛・ほっとステーションのほうは、地域によっての取り組みの特徴を踏まえて、いい取り組みがあったら他の地域でも展開できるように、ぜひお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-123"},{"speaker":"南委員","kind":"質問・要望","question":"利用時間が一人ひとり違うことなど、専門性が求められる事業だと思いますけれども、どうでしょうか。児童センターは後に伺います。","respondent":"佐藤保育課長","answer":"１点目の保育園の役割ですが、児童の発達と保護者の就労を支援する施設ということで、今後も引き続きこのような施設として運営をしてまいります。その辺に関しましては保育にやや集中できないという部分もあるのかと思いまして、今、来年度に向けて改善の検討をしております。","id":"exchange-124"},{"speaker":"南委員","kind":"提案","question":"私が昨日行ったのは８畳１間ぐらいのスペースしかないところで、こういう点についてどうなのか、だめだと禁止している理由は何かを伺います。こういう点について、どういう理由でそういうふうな対応になったのかを伺い、また改善するべきだと思いますがいかがか尋ねました。","respondent":"佐藤保育課長","answer":"３点目、こちらに関しましても、東京都の一時預かり事業所は看護師の設置が義務づけられていない点と。保育園の役割をご案内に書くという件ですが、そちらについては検討したいと思います。","id":"exchange-125"},{"speaker":"南委員","kind":"質問・要望","question":"改めて保育園の役割、保育園のご案内には記載をするべきだというふうに思いますので、それを要望しておきます。むしろやってはならないと私は思っておりますので、これはぜひ現場の声を聞いて改善をしていただきたいと要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-126"},{"speaker":"高橋（し）委員","kind":"意見","question":"早期発見、早期対応の具体的な施策の１つで、大変重要な、有意義なものだと考えています。この取り組みを数年かけて行ってきたわけですが、その成果と課題について、そしてそれを踏まえて今後の方向性をお尋ねいたしますとの意見を述べました。","respondent":"佐藤保育課長","answer":"成果なのですが、例えば１０年前ですと特別支援のお子さんというのは約３６名というふうに記録が残っていまして、今現在は２５６名です。方々当たりまして巡回相談できるようなスキルを持った方の確保の見込みが立ちつつありますので、さらに拡充をしていきたいと考えております。","id":"exchange-127"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ぜひ今後の政策充実に向けて取り組んでいただきたいのです。この巡回相談の実施に伴って、お子さんの生活情報があると思うのですが、それが小学校にどのように伝えられているのか尋ねました。","respondent":"佐藤保育課長","answer":"特別支援の関係のお子さんとの小学校との連携ですが、まず小学校に上がる前に、保育所児童保育要録という発達記録を作成いたします。保育課といたしましては、可能な範囲で学校に情報の提供を行っているです。","id":"exchange-128"},{"speaker":"高橋（し）委員","kind":"質問","question":"相談を踏まえて、小学校のほうではその情報を受けてどのような指導をされているかというのは款が違うので、別の機会にします。乳幼児期と学齢期と、その後社会に出て、施策ではどのように連携されているのか尋ねました。","respondent":"中山障害者福祉課長","answer":"そのケアプランをもとに学校とも連携をしていきますし、その先の就労に向けた支援というところでもかかわりはあるところです。逆にその中に支援の記録なども入れてステージごとに、ご自身のお子さんの理解を深めていただく、そういうものにも活用していただいているところです。","id":"exchange-129"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"それも小学校等に全部見せるようにというふうなご指導は、障害者福祉課のほうでどれぐらいの強さと言いますか、見せていただきたいということをどれぐらいの感じで言ってらっしゃるのか尋ねました。","respondent":"中山障害者福祉課長","answer":"実はサポートブック、今年度まだできたばかりです。できるだけ支援者で共有していただけるように、そうしたお話もさせていただければと考えています。","id":"exchange-130"},{"speaker":"高橋（し）委員","kind":"意見","question":"どうしても３障害である知的、身体、歴史があるのでライフステージに合わせた対応が確立されています。乳幼児から高齢になられた方までのステージを見据えて、あるいは今後どういう構想を持たれているのかということをお尋ねしますとの意見を述べました。","respondent":"中山障害者福祉課長","answer":"発達障害の方は力はそれぞれ持ってらして、ただ特性から自己認知が難しかったり、人とのかかわり方が難しいというような方が多いように思います。二次障害がなければ、普通に社会で活躍できる、そういったところを目指していければいいなと考えております。","id":"exchange-131"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"保育課や教育委員会を俯瞰する形で障害者福祉課のリーダーシップと言いますか、この件に関しては非常に求められるところだと思います。そのあたりについて最後にお願いします。","respondent":"中山障害者福祉課長","answer":"親御さんの悩みも結構大きいところがありますので、当事者の方、それから親御さんに対する支援ということで十分に相談に乗っていける体制をとっていきたいと考えております。","id":"exchange-132"},{"speaker":"石田（秀）委員","kind":"確認","question":"確認ですけれども、今回は３９億４,０００万円ぐらいですけれども、約４０億円ぐらい出ているのかなという感じであります。それは国もこういうふうに入れていきましょうという制度があるのだけれども、この法定外繰入金についてどう考えるかを改めて伺いたいと思います。","respondent":"三ッ橋国保医療年金課長","answer":"委員ご指摘のように、２３区は統一保険料方式をつかっておりますので、今まさに検討しています。各区ばらばらな保険料を算定していく状況が平成３０年度からなのですけれども、また各区ばらばらになっていくか、今まさに検討しています。","id":"exchange-133"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ですからこの辺は、その考え方をもう１回、答弁を後でください。その辺のところを肌感覚でもいいのだけれども、どういうふうな感覚をお持ちなのかも合わせてお聞きしたいです。","respondent":"三ッ橋国保医療年金課長、寺嶋高齢者福祉課長","answer":"は国保制度のあり方ですが、健康という宝物を支えるための大切な制度です。確かに急激な保険料の上昇が起きないように考えてまいりたいと思います。先ほど高齢者地域支援課長からご答弁したように、必要な方がそれを利用できる、そういう組み方をしたというところはあります。","id":"exchange-134"},{"speaker":"石田（秀）委員","kind":"質問","question":"それから先ほど地域包括ケアの話が出たので、住まいについて伺います。それともあっせんをしてご紹介をして、そっちにという話で行くのか、その辺の考え方を教えてほしい。","respondent":"寺嶋高齢者福祉課長","answer":"事業者に今後も適切に運営していただくような形でいろいろご相談を受けながら取り組んでいきたいというふうに考えてあります。多摩地域の特養ホーム等の、広い視野でそういった取り組みについてできることがないかということで検討しているというといった現況があります。","id":"exchange-135"},{"speaker":"石田（秀）委員","kind":"質問","question":"私はそこのところを積極的にやっていくとか、どうかというところのもう一段突っ込んだ答えがあればありがたいです。そこだけ最後に質問します。","respondent":"寺嶋高齢者福祉課長","answer":"先ほど申し上げたような、今、大変いいネットワークの関係が他の自治体とできておりますので、この取り組みを継続して情報収集に努めていきたいと思います。","id":"exchange-136"},{"speaker":"石田（し）委員","kind":"質問","question":"１３８ページ、それと１３４ページ、１３３ページから１３５ページの障害者理解促進・普及啓発事業と芸術活動支援事業などについてお伺いします。そして今回の五反田駅前での事件において、どのような連携がなされてきたのかお知らせください。","respondent":"矢木生活福祉課長","answer":"２日ほど前に担当の係長と職員が緊急に五反田駅、訪問いたしまして、確認をしたところです。今私どものほうで先ほど申し上げたとおり自立支援センターというのも設けてありますので、そういったご相談に丁寧に対応しています。","id":"exchange-137"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"それと関連して、１２９ページに受験生チャレンジ支援事業というのがあるのですが、この辺との関連性はどのようになっているのか教えてください。とりあえずそこまでお願いします。","respondent":"寺嶋高齢者福祉課長、中山障害者福祉課長、矢木生活福祉課長、廣田子ども家庭支援課長","answer":"私が知り得るところで高齢者福祉施設に関しましては虐待の事例はございません。区内の施設について言えば研修の実施ですとか、あるいはマニュアルの作成をしておりますので、そういったものの提供もしております。受験生チャレンジ支援事業ですが、こちらは東京都の貸付の窓口をやってございまして、塾代と中３、高３に受験料を貸し付けるものです。学習支援事業につきましては、それを受けて平成２８年度から集中コースというものを増やしているのですけれども、拡充をしたところです。","id":"exchange-138"},{"speaker":"石田（し）委員","kind":"質問","question":"社会福祉施設の虐待の件ですが、高齢者の施設の対応、どのように予防されているのか、対応策の説明を求めました。","respondent":"寺嶋高齢者福祉課長","answer":"各施設のほうで虐待防止に対する取り組みについて、会議や事例検証等を含めて啓発に取り組んでいるという報告を受けております。","id":"exchange-139"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"なぜかと言うと、就業支援のほうで区内企業とはさまざま連携をとられていると思うので、ぜひそこも含めて連携をとっていただきたいなと思います。","respondent":"中山障害者福祉課長","answer":"逆にこれは一般化されている商品ということもありまして、そこに入れるソフトについて何か日生具で活用できないかということは今検討しています。東京２０２０大会に向けてどのような事業ができるか、オリンピック・パラリンピック準備課とも検討してまいりたいと思います。","id":"exchange-140"},{"speaker":"のだて委員","kind":"質問・要望","question":"介護保険の中の２３２ページ、いわゆる総合事業について、２３３ページの介護給付費等準備基金積立金について伺います。そのいきいき活動支援プログラムをやっている事業者とその割合を伺いたいと思います。","respondent":"松山高齢者地域支援課長","answer":"平成２７年にいち早く始めたということで、品川区は先だって円滑にサービスを進めております。続きまして、いきいき活動支援プログラムということですが、大体４割ぐらいの事業所からいきいき活動支援プログラムのご提案をいただいております。","id":"exchange-141"},{"speaker":"のだて委員","kind":"質問","question":"いきいき活動支援プログラムについては今４割の事業者しかやっていないということで、そうなると残りの６割の事業者はこの国の介護報酬よりも引き下げられた費用でやられているということで。","respondent":"松山高齢者地域支援課長","answer":"もともと半分以上は短時間のサービス事業者でして、いきいき活動支援プログラムというのはケアプランに基づきまして長時間の支援が必要な利用者への提供プログラムということで、区が独自でつくったものです。","id":"exchange-142"},{"speaker":"のだて委員","kind":"質問","question":"今、私がお聞きしたのは、このいきいき活動支援プログラムをやっていない６割の事業者の運営状況をつかんでいるのかということですので、その部分をぜひ、答えるよう求めました。","respondent":"松山高齢者地域支援課長","answer":"６割の事業者の運営状況ですけれども、２カ月に１回事業者連絡会を行っておりますので、その中で事業者とは意見交換を行っております。各事業者からは安定した運営を行っているということと、総合事業への移行はスムーズにできているという回答をいただいてあります。","id":"exchange-143"},{"speaker":"のだて委員","kind":"質問","question":"スムーズにやられていると、２カ月に１回協議、話し合いをしているということですけれども、その中で運営が厳しい事業者はいないのか尋ねました。","respondent":"寺嶋高齢者福祉課長、松山高齢者地域支援課長","answer":"これはやはり制度上問題があるということで、見直しがかかったと、このように認識しています。先ほどお尋ねの短時間のサービスの事業者ですけれども、午前と午後で回している事業者が多うあります。いきいき活動支援プログラムという形で質の担保を図り、その分、単価を上乗せしているものです。","id":"exchange-144"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうすると、そういったところもしっかりと考慮してほしいと求めました。この間の介護給付費等準備基金の推移を伺いたいと思います。","respondent":"寺嶋高齢者福祉課長","answer":"例えば体調とか急な入院とか、きちんと日帰りで対応できるようなこともやっておりますので、これについてはきちんと対応していると認識しております。それから直近の第五期につきましては、２億１,２５１万４３３円の取り崩しをしております。","id":"exchange-145"},{"speaker":"のだて委員","kind":"質問・要望","question":"総合事業については、入院のときには配慮しているというお話でしたけれども、入院の場合、利用者の料金が減るということですか。当初の見込みと、この基金は６５歳以上の方の保険料が余ったものを積み立てているということですから、具体的にご説明ほしいと求めました。","respondent":"寺嶋高齢者福祉課長","answer":"計画と実績の差異につきましては、介護保険の会計には、保険料がショートした場合に一般会計からの繰入が認められておりません。この場合、対応できる方法としては東京都から借り入れることになりますが、それを避けるために安全を見て取り崩しの額を決めております。","id":"exchange-146"},{"speaker":"こんの委員","kind":"質問","question":"１４２ページ、非常勤職員について、それから２３２ページのデイサービスセンター等活用型介護予防事業というところでお聞きしたいと思います。こちらは保育園の看護師の配置についてお聞きしたいのですけれども、どれぐらいの割合で配置をされているのか、の説明を求めました。","respondent":"小林施設整備課長、佐藤保育課長","answer":"デシベルで行きますと、２０等級とかいろいろあるのですけれども、一般的な防音のサッシを入れているところです。看護師の数の件ですが、公立保育園につきましては、０歳児園の３５園について、全て正看護師が配属されております。","id":"exchange-147"},{"speaker":"こんの委員","kind":"質問","question":"そうしたときの音の関係というのはどのように考えらえていますでしょうか。こうした細かい点なのですが、今後建てられるところ、また既存のところはどのように対応していくのかというお考えを聞かせてください。","respondent":"小林施設整備課長","answer":"それと下のほうの天井材、それの下地に防振の、やはり振動が伝わらないような防振の下地材というのがありますので、そういうのを使ったりします。下のほうの既存の階で１、２階あるとすれば、そういうふうな工夫をしております。","id":"exchange-148"},{"speaker":"こんの委員","kind":"質問・要望","question":"そこを１点確認させてほしいと求めました。准看護師を雇用した場合には、派遣でないとだめだということがあるようなのですが、その点はいかがか尋ねました。","respondent":"小林施設整備課長、大澤待機児童対策担当課長","answer":"今後の新築・改築につきましては、委員おっしゃるとおり上下の配置について十分考慮して計画をすべきだと私も考えておりますので、そういうところを全て工夫をしながらそういうふうな問題が起きないように努めてまいります。私立の看護師も全て今、正規の看護師で雇用しております。","id":"exchange-149"},{"speaker":"こんの委員","kind":"質問","question":"そうですか。この問題、課題を取り上げさせていただきましたが、いかがか尋ねました。","respondent":"大澤待機児童対策担当課長","answer":"区では０歳児園に対し、安全上の観点から看護師の配置をお願いして、配置された場合は加算をしているものです。看護師を保育士としてみなすことができるのですけれども、都はそれを正看護師に限っておりますので、区のほうでもそれに倣っているです。","id":"exchange-150"},{"speaker":"こんの委員","kind":"質問・要望","question":"子どもの数に限らず、限ることなく一律の制度設計になっていると思いますけれども、その理解でいいかどうか。多胎児の家庭には対象要件、利用料金など、支援がありますよ、策を設けていますよということでしたら、ご説明ください。","respondent":"佐藤保育課長、高山子ども育成課長","answer":"複数のお子さんがいらっしゃっても一律１時間５００円の料金をいただいております。特に優遇等の制度はございません。子育て支援センターで行っております育児支援ヘルパー派遣事業におきましては、通常の場合ですと１０日を限度とするものではありますが、多胎の場合には３０日まで利用ができるといったような加算措置がとられているところです。","id":"exchange-151"},{"speaker":"こんの委員","kind":"質問","question":"ましてや近くに助けてくれる親族など知り合いがいないというご家庭もままあります。例えばオアシスルームなどは２人分、制度設計が必要だと思いますが、この件についてはいかがか尋ねました。","respondent":"高山子ども育成課長","answer":"お尋ねの件、さまざまな所管にまたがる事業ですので、ご指摘を踏まえまして現状の施策などを見直す機会としたいと考えております。","id":"exchange-152"},{"speaker":"こんの委員","kind":"質問・要望","question":"見直す機会と言ってくださいましてありがとうあります。今後の制度設計、見直しをと今言っていただきましたので、前向きなご検討をお願いして要望で終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-153"},{"speaker":"渡部委員","kind":"質問・要望","question":"事務事業概要で粗々わかっておりますが、どのような利用をされている方がいらっしゃるか等、データをとっているのでしょうか。その辺と、あと利用率というものはどのようになっているのか、合わせて教えていただけますか尋ねました。","respondent":"佐藤保育課長","answer":"時間帯ですが、最大８時間程度利用できるのですが、４時間まで利用している方が大体半分で、短い時間の範囲で利用している方が多いという状況です。利用率ですが、全体で約４０％とあまり高くない状況です。","id":"exchange-154"},{"speaker":"渡部委員","kind":"質問","question":"確かに４時間しか使わない方が、どういうふうに４時間をとるかによって、埋まっているからああだめだわということもあるのかなと思います。この利用率４０％というのは少し低いなというふうに感じるのですけれども、この原因は何かあるのか尋ねました。","respondent":"佐藤保育課長","answer":"利用率が低い原因ですが、２つあると考えております。２点目は先ほども答弁差し上げたとおり、予約が少し煩雑だという面があるためというふうに分析をしているものです。","id":"exchange-155"},{"speaker":"渡部委員","kind":"質問","question":"仕組みを考えて、例えば電話予約とかではなくて、ネット予約のような形はとれないでしょうか。何らかの処置をここはしていかないといけないと思うのですが、ネットの予約等々、キャンセル料のところを合わせてお伺いできればと思います。","respondent":"佐藤保育課長","answer":"実は今考えておりまして、在宅子育て世帯の支援事業ですから、多くの方に使っていただきたいと考えております。委員ご提案のネット予約システムに関しましては、費用対効果やセキュリティーの面の課題を見極めまして、検討していきたいと考えております。","id":"exchange-156"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/392487?Template=document&Id=1440#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":119536,"voices":371}},{"id":"h29-20171006-4","meetingId":"h29-c-settlement","date":"2017年10月6日","dateIso":"2017-10-06","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時１５分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を149件整理しています。","topics":[{"id":"topic-01","title":"◯鈴木（真）委員長 ただいまより、決算特別委員会を開きます。 それでは、平成２８年度品川区一般会計歳入歳出決算","agenda":"◯鈴木（真）委員長 ただいまより、決算特別委員会を開きます。 それでは、平成２８年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"横山委員","kind":"質問","question":"１５２ページ、１５９ページの大井町駅等イルミネーション設置経費、中小企業支援費についてお伺いしてまいります。１点目なのですけれども、不妊治療助成と出産・子育て応援事業についてお伺いいたします。","respondent":"川島健康課長、鷹箸品川保健センター所長","answer":"今、制度の再構築をせざるを得ないということで、予算編成に向けまして検討している最中です。それから、より多くの費用負担が生じる部分、特定不妊治療が何とかならないかというのも検討はしています。平成２８年１１月から予約開始、１２月から宿泊型は開始しておりますけれども、今年度９月末までに３０組のご利用がございました。","id":"exchange-001"},{"speaker":"横山委員","kind":"質問・要望","question":"ぜひアウトリーチ、家庭訪問型の産後ケアの展開をご検討いただきたいと思っています。全妊婦面接の面接率のアップにつきまして、多くの方々に今後受けていただくような方策を要望いたしますが、区のお考えの説明を求めました。","respondent":"鷹箸品川保健センター所長","answer":"現在、妊娠届が一番多く届けられるのは実は区役所でございまして、面接については３保健センターで実施している。予約してから３保健センターにおいでいただいている状況なのですけれども、現在、検討を進めているところです。","id":"exchange-002"},{"speaker":"横山委員","kind":"質問・要望","question":"こちらは要望で終わらせていただきます。２点目、大井町駅等イルミネーション設置経費についてお伺いいたします。","respondent":"鈴木文化観光課長、山崎商業・ものづくり課長","answer":"地域の３つの商店街がありますが、そこの中の実行委員会の皆さんと連携しながら、役割分担をしたものです。それをもとにしまして、今年度も来年２月から３月にかけまして、さらに中身を拡充しながら実施する予定で準備をしています。そういう意味では、個々の企業において、さまざま人材に対するニーズというのは多様です。それにきめ細かく対応するために、昨年度から就業支援コーディネーターを配置しまして、ずばり採用活動そのものの支援でありますとか。","id":"exchange-003"},{"speaker":"横山委員","kind":"質問・要望","question":"地域が目黒区との連携を強く希望しておりますので、こちらもぜひ進めていただきたい、ご支援いただきたいというふうに要望いたします。きめ細やかなマッチングを進めていただいて、潜在労働力の発掘をお願いしたいと思います、要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"新妻委員","kind":"提案","question":"２００８年の第２回一般質問で、品川区版のヘブンアーティストの認定をと、このヘブンアーティストの推進を提案してきた経緯があります。町会・自治会などへ、ヘブンアーティストの活動の場の提供を推進してほしいと求めましたが、いかがか尋ねました。","respondent":"鈴木文化観光課長","answer":"団体が、会場の手配から何から全て自分たちで実施されておりますので、そこにはぜひ。やはり町会でもいろいろな行事などを予定されておりますので、区と連携して活躍の場を用意できればと考えております。","id":"exchange-005"},{"speaker":"新妻委員","kind":"質問・要望","question":"次に動物愛護について伺います。品川区で取り組まれております動物愛護事業について簡単に教えてほしいと求めました。","respondent":"井浦生活衛生課長","answer":"品川区で取り組んでおります動物愛護の取組みですが、まず犬の飼い方、あるいは猫の飼い方についての講座を年に３回開催しております。マイクロチップの装着というようなことの啓発のチラシも今年度用意するような形で、取り組んでいるところです。","id":"exchange-006"},{"speaker":"新妻委員","kind":"質問・要望","question":"避難所への同行避難への理解を求めていくには、飼い主の心がけが大事だと思います。ぜひ品川区でも、飼い主に対しての意識啓発に取り組んでほしいと求めましたが、ご見解の説明を求めました。","respondent":"井浦生活衛生課長","answer":"ペットの防災対策につきましても、広報紙の中で、９月２３日のイベントについては紹介しています。犬のしつけ方教室や猫の飼い方教室の中でも、防災についての項目を必ず入れまして、飼い主の皆さんに啓発を行っているです。","id":"exchange-007"},{"speaker":"新妻委員","kind":"質問・要望","question":"現在、愛玩動物の受入れルールを具体化し、ペットの避難ということも意識を高くしていただいているところであります。生活衛生課、防災課と連携して、具体的にしっかりと対応ができるように取り組んでほしいと求めましたが、いかがか尋ねました。","respondent":"井浦生活衛生課長","answer":"動物愛護法の観点から、日頃から、獣医師会の先生方と防災課と、この三者で災害対策におけるペットの同行避難等々について課題等を検討しています。","id":"exchange-008"},{"speaker":"新妻委員","kind":"質問・要望","question":"いわゆる婚活事業について伺います。募集を終わったところか、１０月２２日にしながわ水族館での交流会があると聞いておりますが、現在の状況をお知らせほしいと求めました。","respondent":"伊崎地域活動課長","answer":"今年度から、地域活動課で、しながわ発見出会い事業を行っております。１０月２２日のしながわ水族館のイベントが第１回目なのですが、募集は１０月１日で締め切りまして、２６人の応募をいただいているところです。","id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"１６名の募集人数に対して２６名の応募ということで、好評であると受けとめております。区がやることに関して、しっかりと現状を見極めて、成果をしっかりと確認していただきながら、ぜひ区でしっかり進めていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"１５８ページの就業支援費にかかわって、若者のブラック企業対策について伺いたいと思います。各店舗の店内の内装などリニューアルするための工事について、商店街支援として補助制度を進めてほしいと求めましたが、いかがか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"ご案内の設備関係の支援としましては、現状、利子補給などを中心に取り組ませていただいているところが軸として１つはあります。環境対応型で、あと空き店舗のチャレンジマート事業としましては、ハード整備を支援させていただいているところがあります。","id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"こうした各自治体の実践について品川区でも把握してほしいと求めましたが、いかがでしょうか。そして、他の自治体も参考に、店舗の工事費への補助制度を改めて求めたいと思いますが、いかがか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"それから大切なのは、資金需要に応えるための事前の相談という部分をすごく重視しております。そうしたサービス内容相談の上で、資金需要にも応えているというようなことで、そうしたことを主眼に対応させていただいているです。","id":"exchange-012"},{"speaker":"中塚委員","kind":"質問・要望","question":"東京都の対応も変わり、商店街の次回の告知を一部入れることは可能になったと伺いましたが、まずこの点を確認させてほしいと求めました。商店街や地域の実状に沿って改善してほしいと求めましたが、いかがか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"次のイベント告知などについて柔軟に対応しているような状況もあって、そこの違いで現場で少し混乱が起きているようなケースも伺えております。今年度から一定、柔軟に、そこの部分については東京都も考慮いただいているというような状況になってあります。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問・要望","question":"実際に商店街のお話を伺うと、何でこれが認められて、何でこれがだめなのだろうと。ぜひ他の自治体と連携して、東京都に改善を引き続き求めてほしいと求めましたが、この点はいかがか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"地域イベントの実施主体で、商店街に対する補助メニューだからというようなことではありました。そういったところで、東京都のほうにも区としまして柔軟な対応などは求めていくようなことをやってまいりたいとは思ってあります。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ、周辺の自治体の方とも連携して、これは東京都に求めていただきたいと要望しておきたいと思います。こうしたセミナーで若者のどんな力になりたいと考えているのか、ぜひ事業の充実を求めたいと思いますが、いかがか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"区としましても就業部門あるいは雇用部門につきましては、この間、力を入れて取り組んできているところです。関連機関と十分連携しながら、区としてもしっかり取り組んでまいりたいと考えているところです。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問","question":"それに対して、こうした事業を通じて品川区はどんな力として役割を発揮したいのか、改めて伺いたいと思います。ぜひ学生も参加ができるように工夫が必要ではないかと思いますが、今後の展開についてお伺いしたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"働く人にとって、若い方々のそうした一般的な雇用関係法令などの正しい知識を持っていただくというのは、基本的には必要だと考えています。そうした雇用側としての法的な部分の知識、これは両面必要ですので、両面から関係機関と連携しながら対応してまいりたいと考えています。","id":"exchange-016"},{"speaker":"木村委員","kind":"質問","question":"よく考えるのですが、選挙権が１８歳からになったということもいろいろありますし、１９歳と２０歳との境目というものがなぜできたのでしょうか。もし１８歳からということになれば、予算がどれぐらい必要になるのかということも、仮に想定しての説明を求めました。","respondent":"川島健康課長","answer":"それから、以前からやっておりました３５歳からの健康診査などを見ましても、予防のためにこのような健診を年齢を引き下げて実施してきたです。","id":"exchange-017"},{"speaker":"木村委員","kind":"意見","question":"本区は他区と比べて高いほうなのか安いほうなのか、また、なぜこの金額に設定されたのか、お聞かせください。そして、区内の野良猫の数というものは年々増えてきているようにも思いますけれども、今後の対策というものに対してもの説明を求めました。","respondent":"井浦生活衛生課長","answer":"こちらの料金の設定の考え方ですが、２３区全体での助成の状況等を見まして設定しています。２つ目の野良猫について、５年前に比べると大幅に野良猫が減っていて、このあたりは不妊助成手術の効果があったのかと考えているところです。","id":"exchange-018"},{"speaker":"木村委員","kind":"意見","question":"区内には３６カ所の公衆便所がありますけれども、４行下、小破修理ですが、昔はトイレットペーパーの持ち去りというものが大変問題になっていましたとの意見を述べました。","respondent":"溝口公園課長","answer":"トイレですと、フラッシュバルブという、水を流すバルブがあります。そういったものが壊れたり、また扉が壊されたり、そのようなものに対応するために小破修繕費用というものを予算計上して実行しているものです。","id":"exchange-019"},{"speaker":"木村委員","kind":"質問","question":"心なき区民によってもたらされる、本当に無駄なお金にあたりますけれども、区として指をくわえて見ているわけにはいかないと思っています。一刻も早く止めなければなりませんし、これをどうすれば防ぐことができるとお考えか尋ねました。","respondent":"溝口公園課長","answer":"トイレにつきましては、清掃業者が必ず少なくとも日に１回は清掃するような形になっています。公園巡回等も含めて対応していますので、今後もよりよい快適に使えるトイレを目指して取組みを行っていきたいと考えているものです。","id":"exchange-020"},{"speaker":"木村委員","kind":"質問","question":"お聞きいたしますけれども、昨年の受講生が６１９名でいいのか。開校後、卒業生というものはどのぐらいの数になったのかの説明を求めました。","respondent":"榎本荏原保健センター所長","answer":"区民の方々が新しく受講されたのは４０名ぐらいでございまして、そのほか、さまざまな公開講座等の受講の方々を足した数です。卒業生の累計ですが、純粋な卒業生につきましては２５０名ぐらいです。","id":"exchange-021"},{"speaker":"木村委員","kind":"質問","question":"卒業生は、健康に関して地域で活動されている人も多いということをお聞きしました。具体的にどのような活動をしているのかを簡単に、答えるよう求めました。","respondent":"榎本荏原保健センター所長","answer":"卒業生の活動ですけれども、地域のグループということで、５グループぐらいつくりまして、さまざま区民の方々に、ロコモや健康の介護予防などの活動をしてくださっています。","id":"exchange-022"},{"speaker":"藤原委員","kind":"質問","question":"１４７ページの人口動態調査５万１,１１４円ですけれども、これはどういう調査をしているのか。それと、この調査によって、どういうことがわかってくるのか、きたのか、の説明を求めました。","respondent":"井浦生活衛生課長","answer":"こちらの衛生統計の人口統計調査ですが、こちらは統計法に基づきまして、国の基幹統計として毎年実施されるものです。婚姻と離婚の数値につきましても、離婚のほうは１４％減っているという、５年前との比較でそのようなところがわかると言えるかと考えています。","id":"exchange-023"},{"speaker":"藤原委員","kind":"質問","question":"本当は、もう必要ないのではないのですかみたいな話を伺おうと思ったのですけれども、これは区の根幹の調査ですよね。東京２３区というのは人口が増えていますが、品川区以外で、いわゆる生まれてくる数のほうが亡くなる方の数より少ないという区はあるのか尋ねました。","respondent":"井浦生活衛生課長","answer":"東京都が発表している統計を見ますと、やはり数区については死亡者数のほうが上回っているというところも統計的にはあります。","id":"exchange-024"},{"speaker":"藤原委員","kind":"質問","question":"企画部門に少し伺いたいのですけれども、この人口動態調査を保健所でやっているのですけれども、まずはこういうデータが来るのでしょうか。それと、この人口というのが、財源的にも税収という意味でも重要になってくると思うのですけれども、その辺についてお伺いします。","respondent":"柏原企画調整課長","answer":"それから、４０歳代ぐらいのファミリー世帯の転出が、若干ですけれど多いというところが見受けられます。これは毎年いろいろなデータを見ながら分析をかけて、予算等にも反映させながら、施策に反映させていくといった状況です。","id":"exchange-025"},{"speaker":"藤原委員","kind":"確認","question":"ただ、確認をとりたいのですけれども、逆に品川区は一定の収入がないと住めないのかと。お子さんを生んでということが、品川区にいる世帯で７５０万円以上が６割ですから、この辺についてはどう思われますか。","respondent":"柏原企画調整課長","answer":"先ほど若干というふうには申しましたけれども、世帯で一定程度の４０歳代のファミリー世帯が、転出のほうが多いという状況があります。深い分析はもう少し必要だと考えてございまして、区としての施策に当てられるのかというのは、今後も分析・研究していきたいと思ってあります。","id":"exchange-026"},{"speaker":"藤原委員","kind":"質問・要望","question":"ぜひ、そういう調査も含めて、施策につなげていってほしいと求めました。大きい質問から細かい質問に変わるのですけれども、１４９ページで、まずお伺いします。","respondent":"井浦生活衛生課長","answer":"狂犬病の発症状況のお尋ねですが、全国、日本全体で見ましても、昭和３１年で１名お亡くなりになった方がいたというのが、国内発症としては最後です。","id":"exchange-027"},{"speaker":"藤原委員","kind":"質問","question":"よくわかりました。次に、１５２ページの健康づくり支援事業費だと思うのですけれども、よく健康寿命と言いますが、健康寿命の定義を教えていただけますか。","respondent":"川島健康課長","answer":"こちらは、日常生活に制限のない期間の平均ということで、日本全国のもの、それから都道府県別のものが出ています。最新のデータで平成２５年が、男性が７０.７６歳、女性が７３.５９歳ということになっております。","id":"exchange-028"},{"speaker":"藤原委員","kind":"質問","question":"年齢、ありがとうあります。降圧剤とか、例えば糖尿病の予防とか、そういう薬を飲んでいても健康寿命にはカウントされるのか尋ねました。","respondent":"川島健康課長","answer":"今ご説明しました健康寿命につきましては、自分は健康であると認識されている方については、健康のほうに入ってくるというような定義になっております。","id":"exchange-029"},{"speaker":"藤原委員","kind":"質問","question":"なぜこういうことを伺うかというと、団塊の世代でと質問させていただいたのですけれども、必ずわかっているわけです。その辺についてはいかがですかということと、やはりその辺も、そういう形ではどういうふうにやっていくのか教えていただけますか。","respondent":"鷹箸品川保健センター所長、池田スポーツ推進課長","answer":"先日「人生１００年、自分の足で」というフレーズで大変人気の番組でございましたけれども、要は死ぬまで自分の足で歩こう。今年６月にしながわ体操、スポーツ振興に関する協定というものを結びまして、それによって制作した体操です。","id":"exchange-030"},{"speaker":"藤原委員","kind":"質問","question":"最後に１４９ページの、大井保健センター所長に伺いたいのですけれども、まずそういう報告をします。今後について、どういう形でどういうふうな対処をしていくのか、最後にお伺いします。","respondent":"間部大井保健センター所長","answer":"思春期、子どもの相談を含めて、幅広くご相談に乗っているところです。家族支援ということで、ひきこもり家族の支援事業も充実して行っているところですので、より充実した事業になるよう取り組んでまいりたいと思います。","id":"exchange-031"},{"speaker":"田中委員","kind":"質問・要望","question":"その日に合わせて相談者は就業相談や区への相談ができるというような環境を整えてほしいと考えますが、いかがでしょうか。ぜひ、有効活用されるように、託児者の配置について前向きに検討いただきたいのですが、いかがか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"交替で託児室でお子さんを見たり、いわゆる相互活用の場としてご認識いただいて、ご利用していただいているというような現状です。したがいまして、現時点では、区のほうで託児室について託児者を配置するというようなところまでは考えてございません。","id":"exchange-032"},{"speaker":"田中委員","kind":"質問","question":"８回から１０回、わかりました。託児する方を配置するということだったら、多分適応できるのではないかと思うのですが、いかがか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"保育士を登録して、そのような方も含めて、中小企業センターの託児室をご利用いただいているというような状況もあります。そのような方面のニーズにも耳を傾けながら、最適な状況といいますか、それは考えていく必要はあるのだろうとは思ってあります。","id":"exchange-033"},{"speaker":"田中委員","kind":"質問・要望","question":"昨日の質疑では、庁舎に用のある子ども連れの方にオアシスルームの利用の特別枠を設置するのはどうかという質問がありました。就労相談に来た方にもオアシスルーム利用の預け枠を設けてほしいと要望しますが、見解を伺います。","respondent":"佐藤保育課長","answer":"お答えしましたが、基本は在宅子育て支援の事業ということで、そのような保護者がお子様をお預けしてリフレッシュ等する施設として考えております。区に近いという立地もありますので、さまざま事務の流れ等も勘案して、いろいろ調査・検討していきたいと考えております。","id":"exchange-034"},{"speaker":"田中委員","kind":"質問・要望","question":"明石市や松山市でも、託児時間の条件は１時間で実施しています。できることはさまざまあると思いますので、ぜひ検討いただきたいのですが、いかがか尋ねました。","respondent":"佐藤保育課長","answer":"オアシスルームも、短時間ですが命をお預かりする施設ですので、子どもの健康状態や発達状態を事前に確認する必要があると考えております。さまざま課題がありますが、検討していきたいと思います。","id":"exchange-035"},{"speaker":"田中委員","kind":"質問","question":"２０１６年度予算特別委員会の中で、品川区、自治体として環境に対する取組みを進める」と答弁しています。現在、環境三計画の改訂プロジェクトの進捗状況をお知らせください。","respondent":"小林環境課長","answer":"今年度につきましては、現在までに、区の現況の把握や現行計画の評価の確認とあわせ、各施策の設定等、各関係課と実施したところです。現在は、１２月に実施予定のパブリックコメントに向けまして、重点目標の設定や、計画作成後の進行管理方法等の検討を進めているところです。","id":"exchange-036"},{"speaker":"田中委員","kind":"質問","question":"次期計画策定にあたり、どのように区民参加を図ってきたのでしょうか。協働を進めるには、計画の段階から市民参加を進める必要があると考えますが、今の計画策定の中で区民の参加をどのように促してきたのか伺います。","respondent":"小林環境課長","answer":"我々、区の自治体として環境施策を考えていく上で、やはり区民の皆様の機運醸成を図っていくことは非常に重要なことと考えています。今回の計画につきましても、そういったものの内容が盛り込まれるように十分把握した上で、計画を策定していきたいと考えています。","id":"exchange-037"},{"speaker":"田中委員","kind":"質問・要望","question":"けれど、分別対象のプラスチックの範囲をもう少し広げてほしいと要望いたします。リサイクルよりリユースが優先されるように、市民への積極的な呼びかけも要望いたしますが、いかがか尋ねました。","respondent":"工藤品川区清掃事務所長","answer":"廃プラスチックの焼却につきましては、平成２０年からサーマルリサイクルを実施させていただいておるところです。廃プラスチックは焼却しましてサーマルリサイクルを実施するというところで、今、進めてまいるところです。","id":"exchange-038"},{"speaker":"田中委員","kind":"質問・要望","question":"以前も要望しましたが、区から斎場へ定期的に排気状況の報告を求めるべきだと考えますが、区の見解を伺います。ぜひ独自での計測を求めますが、見解を伺います。","respondent":"小林環境課長","answer":"引き続き、必要に応じて、桐ヶ谷斎場につきましては状況を把握していきたいと考えております。やはり１事業者が発するものとして測定していくべきと考えておりますので、現在のところ、区としては測定する予定はございません。","id":"exchange-039"},{"speaker":"田中委員","kind":"質問・要望","question":"第３次品川区地球温暖化防止対策実行計画があり、エネルギー施策にも積極的に取り組んでいると評価し、さらに推進してほしいという立場で質問します。そして、河川下水道課として継続的に雨水の利用状況を点検しているのかも、あわせて伺います。","respondent":"持田河川下水道課長","answer":"これまで区有施設に５６カ所、タンクの量としては約２万９,０００リットルのタンクを設置しています。やはり設置のＰＲとともに、設置とともに、使い方のＰＲについても注力していきたいと考えています。","id":"exchange-040"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"続けまして、１５８ページ、公衆浴場商業協同組合についてお伺いいたします。これから観光・文化の観点からも、どういうふうに公衆浴場とのかかわりを区としてお考えになっているのか、お聞きいたします。","respondent":"川島健康課長、山崎商業・ものづくり課長","answer":"決算の３６件の内訳ということですが、１つの浴場で幾つか、修理が補助対象になってあります。現在、補助対象という中に入ってございませんが、これはこれから先のいろいろな状況を見て検討させていただければと思います。私どもでは、決算額２７０万円の補助金の交付を通じまして、組合の振興・発展のためにというような意味合いです。","id":"exchange-041"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"やはり整備のところは、今後とも継続的にやってほしいと求めました。定期的な会議をやっていただきたいと思っているのですけれども、そのことはこれからどういうふうにお考えになっているのかお知らせください。","respondent":"川島健康課長","answer":"公衆浴場と、浴場組合との関係ということで申しますと、先ほどの補助の申請等がありますので、定期的に窓口にはいらっしゃる。役員の方との打ち合わせをする場を持ってありますので、今まで以上にその辺の要望を酌み取れるような場としての活用をしていきたいと考えています。","id":"exchange-042"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"続きまして１５５ページ、環境費のもったいないプロジェクトについてお伺いいたします。今現在、商店街は１１に対して８９店舗の推進店があるということなのですけれども、これからの展望と現在の課題を教えてほしいと求めました。","respondent":"小林環境課長","answer":"現在、ホームページのみでの周知ですが、今年度、１００店舗達成した際には、冊子を作成しまして、商店街等で配布する予定にしております。ツイッターやフェイスブックなどのＳＮＳの活用も今後検討してまいりたいと考えております。","id":"exchange-043"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"北九州市でもやはり同じようなプロジェクトをやっておりましたけれども、これは当然、地域性が違うのはわかっております。ぜひとも告知をいろいろ考えていただいて、啓発活動に取り組んでいただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"あくつ委員","kind":"質問・要望","question":"新年度入学する１年生は、周知のために、新１年生に関しては配布をお願いできないでしょうかということ。４月以降の新入学の１年生・７年生には、継続して配布を行っていただきたいのですが、いかがか尋ねました。","respondent":"品川庶務課長、有馬学務課長","answer":"学校に配布しまして、学校の中で見ていただくというような状況で対応しております。今後の１年生および７年生への配布につきましては、少し教育委員会側で校長会ともいろいろ議論をしながら考えていきたいと考えています。同様に、現在の就学時前の就学時健診におきましても、今のところは具体的な配布ということは予定していませんので、それについてもまた検討していきたいと思ってあります。","id":"exchange-045"},{"speaker":"あくつ委員","kind":"質問","question":"今年は配布はなかったということでよろしいか尋ねました。","respondent":"有馬学務課長、舟木保健予防課長","answer":"昨年の、平成２８年度のものについては間に合っていなかったのかと思います。就学時健診の際には、パンフレットについては同封して送っているです。新しく入学する小学校１年生と、あと中学校１年生、合わせて約５,５００部を配布していただくという形でやりとりをしております。来年度につきましても、今後につきましても、そういう対象で配布できればと思っているところです。","id":"exchange-046"},{"speaker":"あくつ委員","kind":"提案","question":"この思いを酌んでいただいて、確認していただいて、配布してほしいと求めました。これは高額ですから、品川区でのご検討を求めたのですけれども、健康課長から次のようなご答弁をいただきましたとの意見を述べました。","respondent":"川島健康課長","answer":"先行実施自治体であります港区に調査にお伺いするとともに、相談支援を実際に行っている方にもお話をお伺いに行ってまいりました。必要な人がその人に合ったような情報を得られるような支援が必要ではないか、ＮＴＴ東日本関東病院における患者の支援の状況を調べるところから。","id":"exchange-047"},{"speaker":"あくつ委員","kind":"提案","question":"特に少し花火大会で伺いたいのですが、私もずっと議会提案をさせていただいていて、本当に良かったと思うのですが。今回の花火は苦情はどうだったのか、またその理由はどうだったのか、の説明を求めました。","respondent":"鈴木文化観光課長","answer":"今回の地域のイベントでの花火大会についての苦情ですが、区のほうに直接の苦情をいただいたというのは、今のところございません。１つは地域の皆さんがご自分たちの手で実施した花火大会であるということ、今回の苦情がなかった原因ではないかと推測しています。","id":"exchange-048"},{"speaker":"あくつ委員","kind":"質問","question":"私も前もって苦情がなかったですかと問い合わせしたら、なかったと聞いていたので。これがオリンピックを控えた、例えば１年前からなど、どういうふうにお考えなのか、念のためもう一度伺いたいと思います。","respondent":"鈴木文化観光課長","answer":"今年度になりまして、オリンピック・パラリンピック準備課のほうで、新しく品川版の文化プログラム制度を始めたところです。しっかりと区内全体で文化・芸術に親しんでいただくようなイベントを継続していきたいと考えておりますので、至るところで文化芸術活動が行われ。","id":"exchange-049"},{"speaker":"あくつ委員","kind":"質問・要望","question":"本当にそこの思いは１つだと思いますし、８１％の英国民の方が、より自国を誇りに思うようになったというところであります。こんなオリンピックを迎えたいと思いますので、いろいろとまた力を合わせていただきたい、いきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"飯沼委員","kind":"質問","question":"１５４ページの環境調査測定費、１５９ページ、中小企業支援費でお伺いします。環境調査の中に風環境の調査が含まれているのかどうかお伺いします。","respondent":"小林環境課長","answer":"昨年度につきましては、風に関するご相談というところで１件お受けしたところです。今年度につきましては０件です。","id":"exchange-051"},{"speaker":"飯沼委員","kind":"質問","question":"風速計、移動式の測定器によいものができていますが、区でぜひ測定の体制をとってほしいと思います。貸出用の測定器を用意してほしいのですが、この点はいかがか尋ねました。","respondent":"小林環境課長","answer":"貸出につきましてですが、今、環境課におきましては、放射線量の測定器、騒音計、振動計、それら３種類を保有しております。はそちらの業務をしっかりとこなしていくということが大事なところかと考えています。","id":"exchange-052"},{"speaker":"飯沼委員","kind":"質問・要望","question":"騒音測定器や放射能の測定器、振動計などと同じように、やはり区民が求めるところに、ぜひ貸出体制をつくっていただきたい。中小企業の支援なのですけれども、景況調査の結果をどう見ているのかお伺いします。","respondent":"山崎商業・ものづくり課長","answer":"その値につきましては、もうほぼリーマンショックの前に戻っておりまして、その数字を見る限りでは良化傾向がうかがえるというような状況です。業績そのものにつきましてはかなり良好な状況というようなことと、反面、人手不足のほうが少し顕在化しているかというような状況です。","id":"exchange-053"},{"speaker":"飯沼委員","kind":"提案","question":"マッチングの支援を求めています。品川区でもぜひ企業の意見を聞いて、こういった対策・支援をしてほしいのですが、いかがか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"とりわけ業種によって人材難というようなところよりも、全ての業種に対応すべく施策を考えていく必要もあるのだろうと、区としては思っております。","id":"exchange-054"},{"speaker":"飯沼委員","kind":"提案","question":"目黒区は第４回定例会に条例提案を行うということです。公契約条例について、建設業界、関係団体などの意見を聞く場をぜひつくってほしいと求めましたが、いかがか尋ねました。","respondent":"立川経理課長","answer":"区としましては、いわゆる建設業界の労働者の方と年１回、定期的にお話し合いをしております。区としましては、これからも改善を図っていきたいと考えているところです。","id":"exchange-055"},{"speaker":"飯沼委員","kind":"質問・要望","question":"予算決算のときも質問されていますが、一人ひとりの賃金が幾らになっているのかつかめているのでしょうか、お伺いしたいと思います。品川区はつかめているのかどうか、１点お伺いします。","respondent":"立川経理課長","answer":"使用者と労働者が双方で定める事項と区では考えておりますので、事業者にもその都度、遵守の徹底をお願いしています。すぐ即座に設定し直しておりますので、その都度、事業者に要請しています。","id":"exchange-056"},{"speaker":"飯沼委員","kind":"意見","question":"最低価格を把握していない。これから経験を豊かにして働き続けたいという若い方が、その業種に入ってこないという深刻な事態なので、ぜひ検討してくださいとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-057"},{"speaker":"筒井委員","kind":"提案","question":"１５９ページ、特に１６２ページ、品川ビジネスクラブ助成金についてお伺いいたします。そこで確認なのですけれども、今、行っている抽選システムについてお伺いいたしますとの意見を述べました。","respondent":"山崎商業・ものづくり課長","answer":"それから、そうした抽選方式に基づく委託料が、以前と比較しまして追加になるということで、それが２００万円程度です。パンフレットも、各商店街あるいは郵便局と連携しながらやっておりますので、区内各４０カ所の郵便局などで周知を図っているというようなことです。","id":"exchange-058"},{"speaker":"筒井委員","kind":"質問・要望","question":"品川区の掲示板ではチラシなどを貼ったりされていないということなのでしょうか。はがきそのものの設置場所が品川区商店街連合会事務局や区内４２カ所の郵便局なのですけれども、駅に設置するというお考えはいかがか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"車ですけれども、そういったものも運行したりしながら、いろいろな媒体を使ってＰＲということでやらせていただきたいと考えています。それから駅などのご提案につきましては、貴重なご提案ということで、検討します。","id":"exchange-059"},{"speaker":"筒井委員","kind":"質問・要望","question":"基礎的自治体によるものですから、初歩的なレベルの支援をぜひともお願いしたいと考えておりますけれども、いかがでしょうか。仕組みづくりをお願いしたいのですけれども、その点、いかがお考えか尋ねました。","respondent":"川島健康課長、山崎商業・ものづくり課長","answer":"不妊治療の啓発のご質問ですが、そちらは今、広報しながわとホームページでやってあります。はホームページのほうを工夫しまして、啓発にも今まで以上に力を入れていきたいと考えています。ビジネスクラブの自主事業として、ご指摘の部分につきましては、区としても工夫しながら積極的に取り組んでまいる必要があると考えています。","id":"exchange-060"},{"speaker":"本多委員","kind":"質問・要望","question":"１４７ページからの保健衛生費で蚊の対策、それと１５９ページの消費者対策費、消費生活相談や特殊詐欺対策について伺います。取り組む範囲、品川区全域を見てどこのエリアが対象になるのかの説明を求めました。","respondent":"井浦生活衛生課長","answer":"平成２８年度につきましては、区内全域３万４,０００カ所の、ボウフラの成長を抑制する薬剤を投入するという事業です。５月から１０月にかけまして年に４回、投入するという作業を行いまして、蚊が少なくなったという声が寄せられているです。","id":"exchange-061"},{"speaker":"本多委員","kind":"質問","question":"もう、今年で３年目になるので、かなり成果が出ていると、本当に区民の方も感じていると思いますし、私もそう感じます。ただ、どうしても川は水があったり緑が多かったりして、川沿いは効果が出ていないのかと私は思うのですが、その点はいかがか尋ねました。","respondent":"井浦生活衛生課長","answer":"ただいま、川沿いあるいは緑が多いところというご指摘がございました。それぞれ河川管理者、道路管理者とも連絡を密にしまして、それらのところの蚊の対策もあわせて進めていきたいと考えています。","id":"exchange-062"},{"speaker":"本多委員","kind":"質問","question":"進めていくということでわかりました。今まではあまりやっていなかったのか尋ねました。","respondent":"井浦生活衛生課長","answer":"風通しはできるだけよくしてください、あるいは草木についての雑草の草刈り等については、ホームページ、広報紙で繰り返し啓発しておりましたが、川沿いと、あるいは私有地ではないようなところについては、今後、関係機関と連携を密にしていきたいと考えています。","id":"exchange-063"},{"speaker":"本多委員","kind":"質問・要望","question":"完全に蚊が発生しないわけではないが、発生しにくくしているという取組みがあるそうです。対応が求められていますが、そういったところの対策を意識してほしいと求めましたが、いかがか尋ねました。","respondent":"井浦生活衛生課長","answer":"保健所としましては、まず公衆衛生第一というところがありますので、委員ご指摘の点も踏まえまして、今後、研究を深めていきたいと考えています。","id":"exchange-064"},{"speaker":"本多委員","kind":"意見","question":"今後の取組みで、道路課など、ほかの課とも連携していくという答弁をいただきましたけれども、立会川、目黒川、運河などを対象に、環境課や道路課、河川下水道課など、ほかの課との連携について、改めてどのような取組みでいくのかの説明を求めました。","respondent":"井浦生活衛生課長","answer":"区内の公共物も含めまして、総合的に関係課とは連絡を密にして連携していきたいと考えています。塩分濃度にボウフラが弱いというところがありますので、今のところ、この２つの河川については大丈夫かと考えています。","id":"exchange-065"},{"speaker":"本多委員","kind":"質問","question":"次の質問に移ります。１５９ページの消費者対策費の消費者被害防止啓発ということで、消費生活相談２,６２４件ということですが、背景や課題についての説明を求めました。","respondent":"山崎商業・ものづくり課長","answer":"２,０００件を超える相談内容を分析しますと、最近、特徴があるかというふうなことです。来所いただく、あるいは電話等がありますけれども、ケース・バイ・ケースで相談員が適切に対応させていただいているような状況です。","id":"exchange-066"},{"speaker":"本多委員","kind":"質問","question":"今年の上半期だけでも特殊詐欺が２万１,６３０件、１１％も件数が増えているということで、いろいろ啓蒙をやっていると感じます。そういった現況ですけれども、生活安全のほうになりますか、その利用状況と拡大展開についてはどういう方向なのかの説明を求めました。","respondent":"菅生活安全担当課長","answer":"今年度も５００台を購入いたしまして、それぞれ区内４警察署、それぞれ区民の方に設置促進を図っているところです。本年度調達した５００台が８月末に来た段階ですので、まだこれから各警察署とも連携しながら、また設置促進を図っていきたいと考えております。","id":"exchange-067"},{"speaker":"本多委員","kind":"質問","question":"着眼するべきだと思いますが、ぜひそういった方たちを対象に、抜本的に電話機を使わないようなことも必要なのではないでしょうか。その方法を言うと、普及するとやはりよくないですから、まさに個人情報になってしまいますので、その辺はいかがか尋ねました。","respondent":"菅生活安全担当課長","answer":"とにかくすぐに電話に出ないです。以前は、親族、子ども・息子・孫を語っている場合には、例えば事前に合い言葉を決めるなどといったことも推奨していたところです。","id":"exchange-068"},{"speaker":"本多委員","kind":"質問・要望","question":"ほとんどのきっかけが電話ということらしいので、ぜひその辺の対策強化をしてほしいと求めました。携帯電話になりますが、まずつながないことが一番の防止策と言われますが、その辺の啓蒙についてはいかがか尋ねました。","respondent":"菅生活安全担当課長","answer":"サイトの利用料の未払いがあるとか、裁判を起こすといった、少しおどしめいた文句で来るメールが最近また増えてきております。そういったサービスを利用していただいて、例えばブロックするとか、そのような対策をしていただくのが一番かと感じております。","id":"exchange-069"},{"speaker":"いながわ委員","kind":"質問・要望","question":"達成度合いというのですか、そういうものをお伺いしたいということと、受診者数。どうなのかということが１点と、１類から５類まで書いてありますけれども、もしそういうのがわかればの説明を求めました。","respondent":"川島健康課長、舟木保健予防課長、三ッ橋国保医療年金課長","answer":"今、検討しているところですので、その結果をどのように集計するかというようなところもあります。それにつきましては区も都と、あと関係機関と連携しながら取り組んでいきたいと考えています。平成２８年度から、過去１年間、そちらの方に歯科受診の受診勧奨通知を送っております。","id":"exchange-070"},{"speaker":"いながわ委員","kind":"質問・要望","question":"やはりお答えいただくときに、医療費の削減につながるというのを目標にして、しっかり私はやっていただきたいという思いで質問いたしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-071"},{"speaker":"塚本委員","kind":"質問","question":"それから１５８ページの就業支援費についてお伺いしたいと思います。やや時代にとってニーズをうまく把握し切れていないのかというような思いがするのですけれども、この点についていかがお考えか尋ねました。","respondent":"川島健康課長","answer":"訪問歯科診療というものはニーズがどんどん増えていくはずだという認識は私どもも持っているのですが、何かそれが普及していかない要因があるのではないかという部分も、私どもも考えていかなければいけないと考えているところです。","id":"exchange-072"},{"speaker":"塚本委員","kind":"質問・要望","question":"歯科医師会等からのご要望で、今後、まだまだ機材等の準備が十分にされていないのではないかと考えるところでもあります。今後の訪問歯科診療の充実に向けて、そのような拠点整備も含めて検討されるおつもりをどの程度持っていらっしゃるのか、お伺いしたいと思います。","respondent":"川島健康課長","answer":"必要性のほうは十分認識していますが、今、こちらの必要性は認識しているというようなところです。それから、拠点としての整備は、なかなか何か施設を新しくつくるとなると、非常に難しいのではないかと考えております。","id":"exchange-073"},{"speaker":"塚本委員","kind":"質問・要望","question":"機材整備についてはニーズを見ながらというところでお願いしたいと思いますけれども、老朽化等で今後、整備をするような予定も出てくるかと思います。","respondent":"川島健康課長","answer":"今の保健センターにも歯科のユニットがあるので、そちらを有効活用したらどうかというようなご提案も含めて、すぐ箱物をつくるわけではないというお話ですので、まず機材の配備の話をどうするかというところを含めて、今後の課題とさせていただければと思います。","id":"exchange-074"},{"speaker":"塚本委員","kind":"質問・要望","question":"人がいないとか、人といっても誰でもいいわけではなくて、求める人材というようなことまでいくと、本当に採用において大きな厳しい問題がある。求職者側の支援というのも今後とも引き続き実行してほしいと求めましたけれども、今後、区の見解をお伺いしたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"若者あるいは女性に対しての就業支援の部分ですけれども、平成２５年に、力を入れてきたところです。今後、とりわけ小規模の中小企業にとっては喫緊の課題としての求人企業への支援などに、柔軟に図っていくべきだと認識しています。","id":"exchange-075"},{"speaker":"塚本委員","kind":"質問・要望","question":"例えば少し具体的にお話を伺いたいのですが、どういうところに今後、新たな就職の人を求めるのか。中小企業の人材確保における支援策というのも、いろいろ今後必要になってくるかと思いますけれども、その点についてお伺いしたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"これからきめ細かく対応してまいりたいという考えと、技術者というようなところも、非常にニーズが高いです。そのような人材の機関とも連携を図りつつ、少し取組みをしていますので、両面で頑張っていきたいと考えています。","id":"exchange-076"},{"speaker":"塚本委員","kind":"意見","question":"中小企業の雇用の支援、働く環境の整備やいろいろな準備といったことの具体的ニーズも出てくるかと思います。そのような、基礎自治体としてなし得る支援の部分かとも思いますので、人材不足解消への今後の施策展開をよろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-077"},{"speaker":"大沢委員","kind":"質問","question":"１６０ページの商店街の支援の質問と、それともう一個、１６１ページの商店街の国際化ということ、２点について聞きます。一昨日、では一体国際化というのは何なのでしょうかという疑問がまず湧いてくるのですけれども、商店街の国際化について思われるか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"こうした身近な商店街が、例えば区の観光施策などでも、１つの区を代表する資源の一つだというようなことになってきてあります。商店街の魅力を継続しつつ、あるいはあってほしいというようなことで、さまざま取り組んでいるというような状況です。","id":"exchange-078"},{"speaker":"大沢委員","kind":"意見","question":"少し前には、運河まつりのときに、大学の偉い先生の答申から、品川区は観光資源がないのではなかろかと。その点について、本当に品川区の商店街は活性化あるいは再生できるのか、それについてお願いしますとの意見を述べました。","respondent":"山崎商業・ものづくり課長","answer":"多様な区の魅力の一つには、いろいろな経過があって、現在の１００を超える商店街も生き生きと地域で活動されているというようなことです。そこの活力が、持続可能な流れの中で、しっかりこの先も生き生きと活動していけるだろうと感じているところです。","id":"exchange-079"},{"speaker":"大沢委員","kind":"提案","question":"私が提案させていただきまして、逆に、ある資源。この間２回ばかり課長をご指名させていただいて、お伺いしようと思ったのですけれども、おわかりになったらの説明を求めました。","respondent":"山崎商業・ものづくり課長","answer":"３５６軒です。大変申し訳ございません。","id":"exchange-080"},{"speaker":"大沢委員","kind":"質問・要望","question":"その３５６軒のうちでも、おそらくインドの料理の方は多いと思います。連携を強めるような取組みというのが可能なものか、可能でないものかというのを、率直にご意見をほしいと求めました。","respondent":"山崎商業・ものづくり課長","answer":"取り組んでおります、日本で母国の味を供する方々のお店といったところも、もちろん本事業のターゲットになり得る部分です。いろいろ２年目、３年目と続けていきたい事業ですので、工夫して、何か品川区の魅力を発信する一つになればいいかとは、今、思うところです。","id":"exchange-081"},{"speaker":"大沢委員","kind":"質問・要望","question":"むしろ日本人がボディーランゲージでやったら感動するわけで、そのほうがより確かなおもてなしになると思いますけれども、答弁は結構です。そのような形で、おもてなしというのはどんなものかということで、英語だけではないということをお話しさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-082"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"１４９ページの健康診査費と、１４８ページの予防接種について伺いたいと思います。対象も３.６倍に増えたのですけれど、３.２倍ぐらいに増えたのですけれども、区としてはどう捉えられているか尋ねました。","respondent":"川島健康課長","answer":"ただ、今ご指摘のとおり、対象者数からすると、やはりまだまだ受診の数は少ないという認識でいるところです。やはり、こちらを受診される方の健康状態というか結果が、３５歳からの健康診査と同様のような傾向があると分析しています。","id":"exchange-083"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう点ではどういう状況になっているのかということについてもお聞かせほしいと求めました。平成３１年度以降は、ぜひ若者健診を１６歳まで引き下げていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"川島健康課長","answer":"将来の医療費の減少に向けて何を考えていくのかというようなところですけれども、受診率を伸ばしていくというのは、必要になっていると考えています。その辺はスムーズに、わりと自分のところで検査を受けて、そのまま受診したりというふうな流れになっていると考えています。","id":"exchange-084"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ほとんどの会派が実施を繰り返し求めていますし、繰り返し、この眼科検診を実施していただきたいということで要望が出されていると思います。私は、いよいよ来年度からはこれを実施に移していただきたいと思うのですけれども、いかがか尋ねました。","respondent":"川島健康課長","answer":"こちらは、やはり大きく生活習慣が変わる２０歳というところから開始するということで、変更はございません。それから眼科検診、今、過去の答弁のご紹介があったとおりなのですが、今言われたとおり、なかなか来年度からの開始は難しい状況だと考えています。","id":"exchange-085"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それから来年はできないということなのですけれども、なぜできないのか、その課題についてもお聞かせほしいと求めました。それから、現時点で、２３区で何区がこの健診をされているかということについてもの説明を求めました。","respondent":"川島健康課長","answer":"緑内障検診ですとか眼科検診という形で実施しているところが１１区ほどあるということで、実施する自治体は増えているというようなところです。","id":"exchange-086"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"研究して明らかになったことというのは何かありますでしょうか。それから、あと課題、なぜできないのかという課題も教えてほしいと求めました。","respondent":"川島健康課長","answer":"繰り返しの答弁になりますが、ほかの区で実施も増えているということ、重要性というのがますます明らかになってきたというようなところです。","id":"exchange-087"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"杏林大学の眼科学の教授の方も、そういう答弁を繰り返すのではなく、ぜひ実施に移していただきたいということを強く要望しておきます。これも荏原医師会の先生方から強く求められているところで、高齢者の難聴を早期発見・早期対応するためにも、いかがか尋ねました。","respondent":"川島健康課長、舟木保健予防課長","answer":"７５歳以上の後期高齢者になりますと７０％以上の方が難聴になるということで、なかなか現状、実施は難しいのではないかという認識です。高齢者のインフルエンザについては、今、６５歳以上の方にＢ類の定期接種として、自己負担２,５００円で実施しているところです。","id":"exchange-088"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"インフルエンザのほうは、本当に高齢者の貧困というのは、特に６５歳以上の相対的貧困率が２２％ということで、一般の方より特に高齢者の貧困というのは大変な状況になっていますので、健康格差をなくすためにも、インフルエンザ無料化をぜひよろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-089"},{"speaker":"西本委員","kind":"質問","question":"それから１６１ページのプレミアム付商品券ですが、まだやるのですか。効果をどう考えているのでしょうかということをお聞きしたいと思います。","respondent":"鷹箸品川保健センター所長、小林環境課長、山崎商業・ものづくり課長","answer":"国でも推し進めている産後ケアの中の、３つ類型がある中の、訪問型と捉えて今後進めようとしています。事業所につきましては、件数自体は大幅な増加はしないところですが、これからも引き続き効率的な周知に努めてまいりたいと考えています。それから１年後の平成２８年春につきましては、通常に戻りましたので２８％ということで、アンケート結果上は受けとめているところです。","id":"exchange-090"},{"speaker":"西本委員","kind":"質問・要望","question":"それがなかなか検証できないのだというお話があったものですから、区民の皆さんの要望もあるのでしょうから、進めてほしいと求めました。","respondent":"立川経理課長、山崎商業・ものづくり課長","answer":"庁舎につきましては、平成２５年度から徐々に実施しておりまして、昨年度と今年度、第二庁舎のＬＥＤ化が完了するところです。今後につきましては、費用対効果も勘案しまして進めていくべきものかと考えております。産業振興の関係で、財団の持ち味と区の産業施策をうまくミックスさせて効果的に進めていこうというパートナーとして、もともと存在していました。","id":"exchange-091"},{"speaker":"西本委員","kind":"質問・要望","question":"費用対効果の問題ではありません。それと、ビジネスクラブは、もう少しお金の流れ方を明確にしてほしいと求めましたので、これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-092"},{"speaker":"石田（秀）委員","kind":"質問","question":"最終的には、いきなり質問してわからないというと悪いから健康課長には資料だけ渡しておきましたが、そういう形のものというのが行われているのか。","respondent":"川島健康課長","answer":"それから庁内連携も図れる。品川区でもできるのかというようなところを検討させていただければと思います。","id":"exchange-093"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"こっちはいい、これはだめ、何と言われると、非常に大変なので、その辺の減額部分というのがあるじゃないですか。余計わかりづらくなってしまっているから、その辺の感覚というのをもう一度、改めて教えてほしいと求めました。","respondent":"山崎商業・ものづくり課長","answer":"現在、実施後のアンケート調査をしっかりやって、そのような中でトータルにさまざま検討してまいりたいと考えるところです。それから区のものについては柔軟に対応します。","id":"exchange-094"},{"speaker":"石田（秀）委員","kind":"意見","question":"強くやってほしいけれども、その分をやはり区で柔軟にやっているのだったら、そこまで柔軟に広げてほしい。これは我々の思いでありますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-095"},{"speaker":"浅野委員","kind":"質問・要望","question":"どう見てもなかなかどう解釈していいのかわからないというのも、区としてのこの改訂の基本的な考え方、コンセプトについて教えてください。午前中の質疑の中で、１２月にパブリックコメントを実施するということでありましたので、この件についてもの説明を求めました。","respondent":"小林環境課長","answer":"パブリックコメントが１２月にありますが、１２月に向けて、今、鋭意、作業を進めている最中です。パブリックコメントを受けまして、来年４月からの計画実行に向けて進めていきたいと考えているところです。","id":"exchange-096"},{"speaker":"浅野委員","kind":"質問","question":"そしてまた、区民を対象とした説明会を開催するなどいかがでしょうか。そのような小冊子を作成して、子どもから家族に対しての啓発も検討してはいかがかと思いますが、いかがか尋ねました。","respondent":"小林環境課長","answer":"周知についてですが、現在はホームページ等々で公開する予定にしておりますが、作業を進めている最中です。親御様、いろいろとわかりやすい紙面づくりで構成して、誰でも見やすいものをつくっていきたいと考えているところです。","id":"exchange-097"},{"speaker":"浅野委員","kind":"質問","question":"１５８ページの中小企業ＢＣＰ作成支援事業、中小企業ＩＴ化推進事業、事業承継支援事業について質問します。再度、２回目か２回目以降になるかもしれませんが、事情によりまして再度支援を受けることができるのかの説明を求めました。","respondent":"山崎商業・ものづくり課長","answer":"当然、最初策定したときに助成を使っていただいてというような、その後の見直しも当然含めて支援するものです。それから、ＩＴ化、事業承継も同様の考え方で、制度を構成しているものと考えていただいて結構だと思います。","id":"exchange-098"},{"speaker":"浅野委員","kind":"意見","question":"２回目、３回目もあるかと思いますけれども、本当に感謝するところです。これからも品川区の中小企業を守っていくためにも、このようなさまざまな支援事業をこれからも続けていってほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-099"},{"speaker":"松永委員","kind":"質問","question":"そして１４９ページ、関連して１５７ページの動物死体処理費、１５２ページのウォーキングマップアプリ運用保守等について伺いたいと思います。その訓練に関しては、どこで訓練が行われたのか尋ねました。","respondent":"川島健康課長","answer":"それから救護所を設置するということになっている区内の病院の方にも、策定委員会を３回ですか、そのような内容でマニュアルを作成いたしました。もう一カ所が、一斉防災訓練で救護所を設置したという内容になってあります。","id":"exchange-100"},{"speaker":"松永委員","kind":"質問","question":"なぜ聞いたかといいますと、家族の一員として暮らしている高齢の動物たちを、長寿動物として表彰を行っております。超大型犬は１０歳というふうな形で決められておりまして、ペットに対するそのような事業を行ってみてはどうかということでご質問します。","respondent":"井浦生活衛生課長","answer":"犬の登録については、お亡くなりになっている犬については消除するというような形にしています。高齢の犬・猫につきましては、動物愛護のイベントを研究する中で、委員ご指摘のご提案についても研究してまいりたいと考えています。","id":"exchange-101"},{"speaker":"松永委員","kind":"質問","question":"そのような中で、アプリの更新時期というのはあるのでしょうか。そのようなことも含めて、アプリの更新時期というのはいつ頃行われるようになっているのか、伺いたいと思います。","respondent":"川島健康課長","answer":"主にＯＳのアップデート対応が中心になっておりまして、少し今、検討しています。写真も含めて、そこで何か検討できればということで、これはどうなるかわからないのですが、今、検討中です。","id":"exchange-102"},{"speaker":"松永委員","kind":"質問","question":"ぜひ、こうして活用しておりまして、ダウンロード数も、見たら５００と書いてありました。そのような中で、そのような方たちに対しても幅広く周知をしていただければと思うのですけれども、その点について最後に伺いたいと思います。","respondent":"川島健康課長","answer":"質問ではないのですが、ダウンロード数はもう少しございまして、平成２８年度が１,５４８件、平成２９年度が１,５３９件ということです。「私の散歩道」をもっと使っていただけるように活用していく必要があると考えていますので、その中で検討させていただければと思います。","id":"exchange-103"},{"speaker":"伊藤委員","kind":"確認","question":"まとめて質問しますけれど、１４７ページについては各種助成金、その更新についてはいかがでしょうかということを聞きます。成人歯科健診で確認したいところは、対前年度、どのように拡大したのかということについての実績を改めての説明を求めました。","respondent":"川島健康課長","answer":"かなり古いということは認識しておりますので、老朽化をどうしたらいいかというところで、対処しなければと認識しています。１年を通してどのように増えていくかというのは見る必要がありますが、このままで推移していくような推測をしています。","id":"exchange-104"},{"speaker":"伊藤委員","kind":"質問・要望","question":"どちらかというと観光アクションプランのほうを聞きたいので、話をしますけれど、品川区の公式チャンネルというものをYouTubeで確認しました。","respondent":"中元広報広聴課長","answer":"各課でつくられているアプリ等のユーザーの拡大につきましては、広報しながわなど紙媒体も含めて、あらゆる機会を通じてＰＲや啓発の記事ですとかを載せて、区として広めていきたいと思っているところです。","id":"exchange-105"},{"speaker":"伊藤委員","kind":"質問","question":"それはいろいろなコラボレーションをしていきながら、いろいろな方々に対して品川区のフォロワーになってほしいと思うのです。品川区の名所をＰＲしていくなり、もう少し具体的に活用していくべきだと思うのですが、いかがか尋ねました。","respondent":"中元広報広聴課長","answer":"委員のおっしゃるとおり、確かにシナモロールの認知度というのは本当に高いものですので、今後とも、また文化観光課、サンリオともご相談申し上げながら、活用できるところは拡大していければと思っているところです。","id":"exchange-106"},{"speaker":"伊藤委員","kind":"質問","question":"それから肖像権もあるでしょうから、簡単にこの場ですぐどうこうできるとは思わないのだけれども、しながわ水族館で踊ったのはご存知でしょうか。サンリオと連携をとった活動としていくべきだと思うのですけれども、改めて、もう少ししっかりと答弁をお願いいたします。","respondent":"中元広報広聴課長","answer":"やはり、この場ではすぐにはっきりしたお答えは、委員おっしゃるとおり難しいのですが、今後とも文化観光課を通しまして、サンリオにもお願いしながら、もう少し活用の幅を広げていければと思っているところです。","id":"exchange-107"},{"speaker":"伊藤委員","kind":"意見","question":"それは総合的な戦略の中で、シナモロールもいいでしょうし、不動麗子さんもいいでしょう。やはり新しいほうの拡大をしていかないと、YouTubeもフォロワー数も増えないと思うのですが、方向性等を考えた答弁をお願いいたしますとの意見を述べました。","respondent":"鈴木文化観光課長","answer":"今ご質問いただきましたシナモロールですが、ご指摘のとおり、非常に効果があるものです。いろいろなグッズをつくったりということで検討していますので、シティプロモーションの魅力の一つとして発信に活用したいと考えております。","id":"exchange-108"},{"speaker":"伊藤委員","kind":"質問・要望","question":"まとめていきますけれど、こちらの思いとしては、観光大使のシナモロールと十分連携していただいて、品川区の魅力等を発信していただけますように、YouTube、それからツイッターのフォロワーも含めてお願いしますということを要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-109"},{"speaker":"たけうち委員","kind":"質問","question":"品川区でも平成２５年ぐらいからですか、小型家電をやっているのですが、あまりそれについての周知などがなされていないのではないかと。","respondent":"工藤品川区清掃事務所長、山崎商業・ものづくり課長","answer":"１０月は３Ｒ推進月間ということで、広報の１面を使いまして、こちらの記事を入れたいと考えております。６人おりまして、１０年以上の経験者が３名、それから９年、５年、３年というようなことで、それぞれスキルのある相談員です。","id":"exchange-110"},{"speaker":"たけうち委員","kind":"質問","question":"それから、消費者センターについては、できれば何か、やはり非常勤でなければいけないのでしょうか。１人か２人でもご希望が、そのような人材確保、人材育成としての考え方の説明を求めました。","respondent":"工藤品川区清掃事務所長、山崎商業・ものづくり課長","answer":"私どもも、先ほど委員ご指摘のありましたように、関連所管、オリンピック・パラリンピック所管や、区の大きなイベント等があります。６人いらっしゃって、通常は平日３名を配置するというようなことで、ローテーションを組んでいるというようなことです。","id":"exchange-111"},{"speaker":"のだて委員","kind":"質問","question":"この休日診療事業の重要性を区はどう捉えているのか伺います。あわせて、１９９９年度、平成１１年度と昨年の患者数総数を伺いたいと思います。","respondent":"川島健康課長","answer":"内科・小児科の休日診療は、品川・荏原両医師会診療所で９時から２２時まで、大井地区は９時から１７時まで、輪番制で実施しております。歯科・柔道整復施術も輪番制で、同じく９時から１７時まで、調剤薬局は９時から２２時まで、品川・荏原両薬剤師会で実施しております。","id":"exchange-112"},{"speaker":"のだて委員","kind":"質問","question":"そのようなこともあるようで、委託料を上げていくべきだと思いますけれども、いかがでしょうか。なぜ変わっていないのか、できない理由もあわせて伺います。","respondent":"川島健康課長","answer":"人件費が変更していないというようなところで、委託料の内訳が、医師等の人件費がほとんどを占めるです。今年から１３日、さらに３日分、ご要望に沿った形での対応はしてきたところです。","id":"exchange-113"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ上げてほしいと求めましたけれども、この委託料ですけれども、人件費の部分は医師１人分の委託料になっているのか尋ねました。","respondent":"川島健康課長","answer":"委託の内訳という質問です。昼間８時間で医師が８万円、看護師が１万６,０００円、事務が１万２,０００円プラス税というような単価の構成になってあります。","id":"exchange-114"},{"speaker":"のだて委員","kind":"質問・要望","question":"毎年のように委託料の引上げを求める声が出ておりますので、やはり事業を継続していくという面を見ても、引き上げていってほしいと求めました。","respondent":"川島健康課長","answer":"そこまで私どもは細かく規定してというところではなくて、その辺は実態に合わせて運用していただければというようなところです。運用はお任せしているというようなところがありますので、その辺でお願いしたいというようなところです。","id":"exchange-115"},{"speaker":"のだて委員","kind":"質問・要望","question":"１人の医師の方がいてやっているのかと思うのですけれども、そのような面もしっかりと考えていただいて、２人いるという話もありますけれども。２３区の中でやっているところがないということで、委託料についても上げていってほしいと求めましたが、いかがか尋ねました。","respondent":"川島健康課長","answer":"昼間８時間で単価設定をしているというお話もしたと思いますが、しっかり休憩を順番にとっていただくですとか、そのような運用をしていただければという考え方です。","id":"exchange-116"},{"speaker":"のだて委員","kind":"質問・要望","question":"休日診療の単価の引上げについても伺っていますので、ぜひここは、やはり人事委員会勧告に倣ってということですけれども、そこは柔軟な対応をしてほしいと求めましたが、いかがか尋ねました。","respondent":"川島健康課長","answer":"こちらは毎年毎年の数を見まして、例えば先ほども申しました体制強化等で手当てをしていければと今は考えてあります。","id":"exchange-117"},{"speaker":"高橋（し）委員","kind":"質問","question":"公益社団法人として運営されていますが、もともとは品川区高齢者事業団として発足して、今年で４０周年と伺っております。ここの決算額１億５,０００万円余のうちの助成金と運営資金貸付、それぞれ７,８００万円の内容について、お尋ねします。","respondent":"山崎商業・ものづくり課長","answer":"歳入した受託収入が、先ほど１億円ぐらいの経費の中で、区が７,８００万円の比率で運営費などを持たせていただいているというような関係です。","id":"exchange-118"},{"speaker":"高橋（し）委員","kind":"質問","question":"このようなことにシルバー人材センターが直接応えていただけるのでしょうか。ほかの、このような方々の支援策があれば、これについてお尋ねいたします。","respondent":"山崎商業・ものづくり課長","answer":"ですから、例えばコンビニの小売などで、店長からの指示を直接受けるような形態ですと、少し苦しい部分もあります。サポしながわなどにおきましては、今言ったような形態でも対応して、マッチングさせていただいているような状況です。","id":"exchange-119"},{"speaker":"高橋（し）委員","kind":"質問","question":"ただ、現在の就業状況は、過去のシルバー人材センターができた頃とは変わっております。ですから、今お話があったような、シルバー人材センターが間に入って雇用できるような形態はできないのか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"シルバー人材センターが発足した４０年前とは、確かに雇用の状況、関係が大分変わっております。そのようなことに高齢者の方が対応していただけるような形の検討を、シルバー人材センター内部で検討を開始したということで伺ってあります。","id":"exchange-120"},{"speaker":"高橋（し）委員","kind":"質問","question":"今、シルバー型労働者派遣事業ということなのですが、今までの仕組みとどのようなところが違って、今後のそのような高齢者の方の雇用に可能な部分があるのか、私は勉強不足なので、その辺をお伺いします。","respondent":"山崎商業・ものづくり課長","answer":"派遣する業種が短期間であり、いわゆる軽作業であるというような、派遣先の業務が限定されるというようなところで大きく違いがあるです。","id":"exchange-121"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"このような声は区に届いているのでしょうか。それの改善というのでしょうか、対応策を、どのようになされているのか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"月１回、シルバー人材センターでは理事会等を開いて、区からもそこに出席しています。今、少しでも適正な就労サービスの提供に努めるという本来の目的に資するために、人材センターと連携しながら取り組んでいるというような状況です。","id":"exchange-122"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"措置要綱をつくられたということで、働かれる方々の労働の向上に使っていってほしいと求めました。高齢者の方々の就業機会や、さまざまな手だてをして、シルバー人材センターのさらなる充実を求めていきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-123"},{"speaker":"若林委員","kind":"質問・要望","question":"保健師とはどういう仕事を行う人なのでしょうか、教えてほしいと求めました。品川区全体として配置状況はどのようになっていますでしょうか、お知らせほしいと求めました。","respondent":"鷹箸品川保健センター所長","answer":"保健師の現在の品川区での配置状況ですが、９月１日現在、在籍数としては４１名になります。４１名ですけれども、配置としては高齢部門に３名、国保医療年金課に１名、保健予防課に４名、そして保健センターに３３名配置されております。","id":"exchange-124"},{"speaker":"若林委員","kind":"質問・要望","question":"そうしますと、今の言葉、市町村保健師と保健所保健師の違いというのは何かあるのでしょうか。その連携というのはあるのか尋ねました。","respondent":"鷹箸品川保健センター所長","answer":"それを双方連携して対応しているのが、特別区、品川区保健所の保健師です。保健予防課の保健師が感染症を中心とする対応をしておりまして、県型保健所の業務をしているという形で考えていただくとよろしいかと思います。","id":"exchange-125"},{"speaker":"若林委員","kind":"質問","question":"医療関係で３,７４５件、ざっくりと３つのカテゴリーで、どういう関係機関と連絡・連携をとっているかというデータが残っておりますけれども。あわせて今後の期待としてどのようなものがあるとお考えであるか、お聞かせほしいと求めました。","respondent":"鷹箸品川保健センター所長","answer":"３保健センターでは、個別の保健指導業務などを行っている中で、３種類の保健と福祉、医療が連携して現状では対応しております。保健師、具体的に地域で支援を必要とされている方々への指導・助言などの方法を現役の保健師に学びながら、その方に合った最適な支援をできるように。","id":"exchange-126"},{"speaker":"若林委員","kind":"質問・要望","question":"平成２７年度が１０７人、平成２８年度が９７人と、この数字から少し垣間見た気がいたします。こういう方々に、しっかりと区役所の中で両者のつなぎ役を果たしていただきたいという思いがあるのですけれども、最後にご答弁をお願いいたします。","respondent":"鷹箸品川保健センター所長","answer":"医療と介護の連携に果たす保健師の役割ということかと思いますが、ますます重要になるかと思ってありますので、保健師のこれからの活躍をぜひ見守っていただければと思います。","id":"exchange-127"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"そのため、平成２８年度第３回定例会で、４０歳以降の眼科検診の実施を要望いたしましたが、その実施は見送られました。他の会派からも要望がありましたが、その実施に向けて、何か区のほうで準備等、取組みがあれば、もう一歩踏み込んでご説明をお願いしたいと思います。","respondent":"川島健康課長","answer":"それから、自覚症状が少ないということから、早期発見・早期治療が重要になってくるということで、この検診は非常に重要であるというような認識です。","id":"exchange-128"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"皆が要望していることなので、一刻も早い眼科検診の実現を望みまして、次の質問に移りたいと思います。どのような効果が期待できるのか、またワクチンの接種方法について、簡単にまとめてご説明をお願いします。","respondent":"舟木保健予防課長","answer":"１３歳以上については、通常は１回の接種となっております。インフルエンザの発生状況から考えますと、大体１２月の上旬ぐらいまでに接種が済んでいることが望ましいと言われております。","id":"exchange-129"},{"speaker":"鈴木（博）委員","kind":"質問","question":"子どもは２回、成人・高齢者の場合は１回、接種します。区が把握している情報をもとに、今シーズン、インフルエンザワクチンが不足することになった経緯についてご説明をお願いします。","respondent":"舟木保健予防課長","answer":"そのままいくと７割程度になってしまうということが明らかになったため、途中で、例年より製造の開始が２カ月程度遅れております。製造の予定量が昨年の使用料を約４％、製造量としては約１０％下回る見込みだということで、厚生労働省から聞いております。","id":"exchange-130"},{"speaker":"鈴木（博）委員","kind":"質問","question":"しかも１０月にはちょぼちょぼ、１１月には出ない、１２月になるとそこそこの数が供給されるのではないかと言われています。ワクチンのシーズンの１０月、１１月にはほとんどワクチンが出回らないということになりまして、区の現状認識はいかがか尋ねました。","respondent":"舟木保健予防課長","answer":"１０月以降、毎週の供給については昨年度の需要量を上回る形で、今年度の供給予定量が組まれていると言っておりました。ただ、１１月もそれなりに流通はする予定だと、製造会社は言っておりました。","id":"exchange-131"},{"speaker":"鈴木（博）委員","kind":"質問","question":"「平成２９年度は、希望日には接種できず、医療機関にワクチンが納品されるまでお待ちいただくことがあります」という注意書きが挿入されています。","respondent":"舟木保健予防課長","answer":"もちろん９月１５日付の国の文書で初めて、必要に応じてすぐに対応できるよう、整えていきたいと思います。区民からのお問い合わせが少ないのかもしれませんが、医師会、医療機関とも連携しながら対応してまいりたいと思います。","id":"exchange-132"},{"speaker":"鈴木（博）委員","kind":"質問","question":"次に、歳入に続いて、おたふく風邪ワクチンの２回接種助成について再度お尋ねします。もしも品川区がおたふく風邪ワクチンの２回接種の助成を行っていたとしたら、昨年のおたふく風邪の流行はどうなったと区はお考えか尋ねました。","respondent":"舟木保健予防課長","answer":"おたふく風邪自体が非常に、不顕性感染が３割程度あるということで多く、流行そのものを抑えることはできなかったのではないかと思います。ただ、２回助成することで２回接種する方が少しでも増えれば、発生、患者の報告数自体は減った可能性はあるのかと思ってはいます。","id":"exchange-133"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"ぜひ中央区に続いておたふく風邪ワクチンの接種助成２回を実施することを強く要望したいと思います。行政などの関係者や国民にも広く、このワクチンの重要性を知っていただきたい」という、前向きな検討をぜひよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-134"},{"speaker":"石田（し）委員","kind":"提案","question":"まず初めにお伺いしたいのは、その企業の制度づくりを支援すべきだと思いますが、いかがでしょうか。１６０・１６１ページの、１つ提案を含めてご質問しますけれど、ものをつくっていけないかとの意見を述べました。","respondent":"川島健康課長、山崎商業・ものづくり課長","answer":"不妊治療に対する企業の支援等のお話につきましては、非常に重要なことだと思うのですが、私ども状況の把握はできてございません。有機的に結びつける場所としてＳＨＩＰなどもありますので、しっかり何か工夫して、趣旨を踏まえて取り組んでまいりたいと感じているところです。","id":"exchange-135"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"ぜひほかの区市町村を参考にして、いわゆる上乗せや、都の制度の漏れているところをフォローできるような制度構築をしてほしいと求めました。１年間の年度の上限を１００万円に設定して、そのようなことも踏まえて、ぜひご検討をお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-136"},{"speaker":"南委員","kind":"質問・要望","question":"１５３ページの公害健康被害補償事業費、そして同じページの環境費に関連して、飛行機の落下物の問題について質問したいと思います。そして、２,６７０人という数は、この間、減少傾向にあるのか、増えている傾向にあるのか、全体の状況を教えてほしいと求めました。","respondent":"川島健康課長","answer":"年々減っているというところがまず１つあります。それから１８歳から３９歳までが６１７人、それから４０歳から５９歳までが１,０２４人、６０歳以上が９６５人という年齢構成になってあります。","id":"exchange-137"},{"speaker":"南委員","kind":"質問","question":"それも来年の３月で打ち切り、大変深刻な問題になってきていると私は思っているのですけれども、そのあたりの認識をまず伺いたいと思います。","respondent":"川島健康課長","answer":"区の認識ということですけれども、制度は平成２６年度に変更になったということですが、その当時から。それから６,０００円の負担感なのですが、私どもが把握できていないというふうなところで、少し実態がわからないです。","id":"exchange-138"},{"speaker":"南委員","kind":"質問・要望","question":"来年の４月からこういう状況になっていくわけですから、２３区だけではないわけですけれども、改めてその点の決意を伺いたいと思います。この事態についてどのような認識を持っているのか、その辺について伺います。","respondent":"川島健康課長、中村都市計画課長","answer":"もともと始まった制度に戻るというような説明がされております。当時、平成２６年の条例改正のときにも、なかなかこれを覆すのは難しいのかというのも正直なところです。航空機の部品、パネル等が落下して、先日、直近では、市街を走行している自動車の屋根に落下するといった事故などもございました。","id":"exchange-139"},{"speaker":"南委員","kind":"質問・要望","question":"ほかの重大インシデントとしていなくても落下物はあるということですから、これで済んでいるけれど、影響が出たらどうするのですか。それで、国がとっている対策でゼロになると考えているのかどうか、この辺についても改めて伺います。","respondent":"川島健康課長、中村都市計画課長","answer":"大気汚染の医療費助成の件につきましては、実際、私どもがお客様と直接接する窓口になっているというところもあります。説明会等の中では、その辺の都の担当者等との話の中では、そういう意見は伝えていきたいと考えています。国では、補償制度がしっかりしているというふうには説明はありましたけれども、この補償制度よりも予防に対する取組みが一番大事だと考えております。","id":"exchange-140"},{"speaker":"南委員","kind":"質問・要望","question":"ゼロにしていくよう求めるということは、具体的にどういうことでしょうか。具体的な対策が出されているけれども、それを徹底すればゼロになると考えているのか尋ねました。","respondent":"中村都市計画課長","answer":"補償制度は大事ですけれども、それよりも事故を起こさないという予防策が大事だと、区は考えております。区といたしましても、このようなゼロになる取組みを、可能な限り、考え得る限り行っていただくように、国に求めていくべきと考えております。","id":"exchange-141"},{"speaker":"南委員","kind":"質問・要望","question":"多くの区民が、落下物の危険も１つの理由にして上空飛行はやめてほしいと求めていること。区民の命、財産を守る上で、中止を求めるということがなぜできないのか。","respondent":"中村都市計画課長","answer":"落下物につきましては、国は今、調査中ということで、その回答が出たときには速やかに報告するということで、区もそれを求めております。","id":"exchange-142"},{"speaker":"こんの委員","kind":"質問・要望","question":"具体的な地域包括ケア、医療と介護の連携を具体的に進めるためにも、どうか人材確保・増員をお願いしたいと要望したい。このような現状で、いわゆる医療行政の削減という観点から、この状況を区はどのような認識でどう捉えていらっしゃいますか尋ねました。","respondent":"黒田人事課長、舟木保健予防課長","answer":"今年度の保健師につきましては、何名か採用するということを計画しておりまして、平成３０年の４月に向けて、今、採用の事務を行っているところです。小児に対するものについては有効性が低下するということも言われておりまして、国では定期接種化はされていない、検討されていないような現状です。","id":"exchange-143"},{"speaker":"こんの委員","kind":"質問・要望","question":"今のようなご答弁だったのかもしれないですが、財政削減というところではどのように考えるかということをお答えいただきたいと思っておりました。","respondent":"舟木保健予防課長","answer":"国として定期接種化に向けて検討している中で、検討しているものとなっておりますので、まだ区ではわからないような状況です。医療経済効果については、計算できないような状況です。","id":"exchange-144"},{"speaker":"こんの委員","kind":"質問・要望","question":"なぜ必要なのか、こういうスタートをさせているのかというところを、もう少し研究してほしいと求めました。どうか他区の状況も見ながら、品川区のこのような動きを考えてほしいと求めましたが、いかがか尋ねました。","respondent":"舟木保健予防課長","answer":"定期予防接種化が検討されているものとか、そういうものを中心に効果があるものとか、そういうことを考えて進めてまいりました。品川区はほかのワクチンについてもほかの区より実施している状況等もありますので、そういうバランスを見ながら総合的に考えてまいりたいと思います。","id":"exchange-145"},{"speaker":"こんの委員","kind":"質問・要望","question":"ほかの予防接種とバランスを見て考えていくというご答弁をいただきました。ぜひバランスを見て、季節性のインフルエンザも加えてお考えを今後も持っていただきたいと、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-146"},{"speaker":"渡部委員","kind":"質問","question":"３日というところに控えて、９日はこのような動きがあるみたいなものがあれば、改めての説明を求めました。","respondent":"鈴木文化観光課長、山崎商業・ものづくり課長","answer":"東急の１０月９日のイベントに関しての区の協力ですが、文化観光課では、沿線でのいろいろな地域のイベントについての支援を行っているところです。そのうち、例えば戸越銀座でございましたら、銀六商店街では銀六祭を１日延長しまして、イベントなどの実施を予定しております。１２商店街で、枚数にしまして３５５枚、ばちっと表示をする予定になっております。","id":"exchange-147"},{"speaker":"渡部委員","kind":"質問","question":"その辺というのは、各駅、警備についたりなどというのは何かあるのですか。東急で独自にやっているかどうか、もしくは区でも何人か出て回ったりするのかなどと思って、少しその辺だけ気になったのでの説明を求めました。","respondent":"鈴木文化観光課長","answer":"１０月９日の１日無料で乗り降りできるチケットの配付等に関しましては、全て東急の事業ということで、区のほうで人的なご協力の要請は来ていないのが現在のところです。","id":"exchange-148"},{"speaker":"渡部委員","kind":"提案","question":"私たちは、公衆浴場を何とか残していただきたい。必要なのかどうなのかを含めて、転換期に来ているのかというような課題だけ提案させていただいて、またの機会にしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-149"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/392487?Template=document&Id=1442#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":111124,"voices":345}},{"id":"h29-20171010-4","meetingId":"h29-c-settlement","date":"2017年10月10日","dateIso":"2017-10-10","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時２０分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を136件整理しています。","topics":[{"id":"topic-01","title":"◯鈴木（真）委員長 ただいまより決算特別委員会を開会いたします。 それでは、平成２８年度品川区一般会計歳入歳出決算","agenda":"◯鈴木（真）委員長 ただいまより決算特別委員会を開会いたします。 それでは、平成２８年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"渡部委員","kind":"質問","question":"それが壊れて、それがどうも認められないなどという話もあるのですが、その辺は何らかの形でクリアする方法はあるのでしょうか。例えば城南島のほうに移ったりとか、そのような場合、物理的に区内で何か行うということは不可能なのか尋ねました。","respondent":"中村都市計画課長","answer":"用途地域に定まりまして、それから大きな変更は今のところはありませんので、それは同じ規模のものが継続して建てられるかと思います。","id":"exchange-001"},{"speaker":"渡部委員","kind":"質問","question":"出ていくしかないですよねというような話に持っていこうと思ったのですけれども、もう１回、その辺を教えてもらえれば。ぼやかしていますけれども、環境に影響を及ぼすというようなものに認定されてしまったら、もうだめなのかどうなのかということの説明を求めました。","respondent":"中村都市計画課長","answer":"確かに委員ご指摘のとおり、例えばクリーニング店の溶剤だとか、こういったもので新たに規制されているものもあることは事実です。ただ、特定の薬品を使いますと、この辺は個別に建築計画の際はご相談をいただきながらアドバイスさせていただきたいというふうに考えております。","id":"exchange-002"},{"speaker":"渡部委員","kind":"質問","question":"商業振興だとか産業振興をしている部分もありつつ、だけれども、実はもうそこでできないではないかみたいな話も出てくるかと思うのです。ですから、設備等は寿命があるものですから、今後そのようなことがあるようでしたらご相談に乗ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"新妻委員","kind":"質問・要望","question":"１点目に、１１月にオープン予定の八潮北公園のスケートボードパークの進捗状況を伺います。２点目に、その進捗状況の中から、暑さ対策、安全対策、公園へのアクセスの案内は、どのようになっているか伺います。","respondent":"溝口公園課長","answer":"鋭意工事を進めているところでありまして、順調に進んでおり、オープンには間に合うような形で工事を今現在進められているところです。この公園に対しての案内、特徴を含めてなのですが、これにつきましては、オープン前日の１１月１９日にオープンイベントを予定しております。","id":"exchange-004"},{"speaker":"新妻委員","kind":"質問","question":"ＢＭＸをやらせてほしいという声が非常にありまして、これはBicycle Motocross（バイシクルモトクロス）競技用の自転車のことです。は今回できるパークが、設備上、ＢＭＸが使えるものなのかどうかお伺いいたします。","respondent":"溝口公園課長","answer":"基本的にはスケートボード、また、靴にローラーがついているインラインスケートを目的につくっております。ただ、他の先進事例を見ますと、同じようなところでＢＭＸという自転車の競技車両も使ってやっているところはあると聞いているところです。","id":"exchange-005"},{"speaker":"新妻委員","kind":"質問・要望","question":"ホームページを確認いたしますと、最新情報では、平成２７年度の状況しか公開されておりません。はこの情報を新しいものにしていただくことを要望するとともに、平成２８年度の成果、平成２７年度からの増減を教えてほしいと求めました。","respondent":"桑波田交通安全担当課長","answer":"撤去の数ですけれども、昨年度は１万２,１６６台の撤去を実施しております。その前年と比べますと、マイナス７８６台という状況になっているところです。","id":"exchange-006"},{"speaker":"新妻委員","kind":"質問","question":"駐輪場の整備も整えていただく中で、駐輪場に、しっかりととめるべきところにとめられている成果かとも思います。その上で、この立会川駅に近い競馬場通りの道路整備がオリンピックに向けてどのようにされていくのかお伺いしたいと思います。","respondent":"桑波田交通安全担当課長、多並道路課長","answer":"各駅につきましては、それぞれ放置禁止区域ということで指定して撤去等をやっております。そこの指定から漏れているところは、職員が巡回しまして、札づけをして、一定期間をおきまして撤去をし、対応しています。私からは、道路整備についてお答えします。いわゆる矢羽根といわれている自転車レーンの整備について、今、協議を進めながら設計作業を進めているところです。","id":"exchange-007"},{"speaker":"新妻委員","kind":"質問・要望","question":"最後に１点、この競馬場通りのなぎさ会館の隣に公衆便所があります。この改修状況の今後の予定を教えてほしいと求めました。","respondent":"溝口公園課長","answer":"公衆便所につきましては、来年度設計で、再来年度に改修の工事に入っていく予定をしています。","id":"exchange-008"},{"speaker":"新妻委員","kind":"意見","question":"安全面はもとより、女性に配慮をしたトイレ、例えば個室の中に物を置く台をちょっと大きめにとっていただく、また、洗面所のところにも物を置くときにちょっと台がある、また、ちょっと重いものでもかけられるような、そういう配慮をぜひお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１６３ページの交通安全啓発費、１７０ページの公園整備事業費でお伺いいたします。ゾーン３０の説明をしていただきたいのと、このゾーン３０の効果についてもの説明を求めました。","respondent":"桑波田交通安全担当課長","answer":"速度を３０kmに規制することによって、警察が地域の状況、声等を聞きながら指定するものです。荏原署にも地元からそういったお声をいただいているということで、来年度中には指定をしていく、こういった流れになっております。","id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問・要望","question":"どうしたらそういう地域が増えていくのか、その辺の手続的なことを教えていただきたいのと、ドライバーの方がゾーン３０を知らない人がまだまだ多い。","respondent":"桑波田交通安全担当課長","answer":"ゾーン３０につきましては、警察本部と交渉して公安委員会の決定をいただく、こういった流れで実施しております。各種キャンペーン等、そういったものを使いながら、ゾーン３０についても各警察署と連携を図りながら周知を図っていきたいと考えております。","id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この現状をどう捉えていらっしゃるのかお伺いしたいのが１点です。なぜ公園が増えないのか、公園をつくってくださらないのか、理由も伺います。","respondent":"溝口公園課長","answer":"そういったところの中で、１人当たりの面積でいきますと、やはりかなり地域間の差が出てくるというのは認識しています。これからも引き続き同様な形での取組みをしていきたいと考えているものです。","id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問・要望","question":"再開発とともに公園が増えているということなのですけれども、具体的にどこにどう増えているのか示してほしいと求めました。財源があるのに、なぜ必要なインフラ整備を行わないのか、この理由もあわせて伺います。","respondent":"溝口公園課長、高梨木密整備推進課長","answer":"公園につきましては、近年、１０年間で４６カ所も区内では増えている、そういった状況もあります。木密整備推進課では、密集住宅市街地整備促進事業で、その中で国や都の補助金をいただきながら防災広場の整備に鋭意取り組んでいるところです。","id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問","question":"この点についてどうしてなのか、先ほども尋ねましたが、なぜ財源があるのに必要なインフラ整備を行わないのか、この理由が伺えていません。お願いします。","respondent":"溝口公園課長","answer":"そういった中で、しっかりと木密整備の担当と公園の担当が連携して広場型の整備、そういったものを今現在進めているところです。これまでも公園整備をしていますし、今後も公園整備にしっかり取り組んでいきたいと思っているところです。","id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問・要望","question":"重ねて公園・児童遊園の増設を求めます。区民のために税金を使うように重ねて求めますが、いかがか尋ねました。","respondent":"溝口公園課長","answer":"これまでも公園整備、さまざまなまちづくりまたは防災の観点、そういったところを含めまして、区内全域を見渡して整備を進めてきております。今後も引き続き、さまざまな行政需要も勘案しながら、しっかりと公園整備にあたっていきたいというふうに考えているものです。","id":"exchange-015"},{"speaker":"飯沼委員","kind":"意見","question":"必要なところにできていません。区民は今の課長の説明を受けて絶対納得しませんので、ぜひ一緒に歩いてくださいとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"松永委員","kind":"質問","question":"初めに、１６３ページの交通安全啓発費の普及啓発費の中で、１,７２９万５,０４６円について伺います。交通安全週間のときのみあそこに警察官が立って注意喚起をしているのか、その辺について、スケジュールについて伺いたいと思います。","respondent":"桑波田交通安全担当課長","answer":"年２回全国で実施されておりますので、１０日間、そういったものを強化して事故を減らそうということを一斉に取り組んでいるところです。区としましても、一緒に現場でキャンペーンを実施したりとか、そういったものを１０日間はまたさらに強化してやっているところです。","id":"exchange-017"},{"speaker":"松永委員","kind":"質問・要望","question":"やはりそこでのタクシーの乗り入れ乗車ですか、その辺の対策はどのようにとられているのか。はそうした乗客に、「ここではだめです」というような周知をしていかなければならないと思うのですが、その辺の対策について伺いたいと思います。","respondent":"桑波田交通安全担当課長","answer":"やはり警察のほうでしかできませんので、そういったところは改めて警察、管轄署のほうへ申し入れしていきたいと思います。区としましては、いろいろな啓発看板等も設置しておりますので、タクシーの乗降についても啓発について進めてまいりたいと考えております。","id":"exchange-018"},{"speaker":"松永委員","kind":"確認","question":"次に、１６４ページの道路安全施設費１億円余を伺いたいと思います。矢羽根はきちんと整備されていくのか、それともそのままになってしまうのか、その辺を伺いたいと思います。","respondent":"多並道路課長","answer":"大田区も含めてネットワークで進めていこうと行っておりますので、国の今の勉強内容も含めまして、今後の進め方については考えていきたいと思います。ただ、今のご質問のところについては、都道であれば東京都のほうに申し入れていきたいと思ってあります。","id":"exchange-019"},{"speaker":"松永委員","kind":"提案","question":"提案でありますけれども、先ほどのタクシーの話のところで、東急口から少し歩いたところにタクシー乗り場があります。あそこを、もしできたら渋谷のようなスクランブル交差点にしてはどうかと思うのですけれども、いかがか尋ねました。","respondent":"多並道路課長","answer":"そういう観点も考えながら、できるところはどこか、そういうことをまちづくりの部署とも連携しながら検討していきたいと思っているところです。ただ、今の点については、もう少し慎重に考えなければいけないかと考えています。","id":"exchange-020"},{"speaker":"松永委員","kind":"質問・要望","question":"次に、１６６ページの歩道整備工事費４,３３２万７,４４０円のところについて伺います。それとも区が独自に歩きながらそうした歩道を見つけて、すぐに舗装されていくという形になるのか、その対策について伺いたいと思います。","respondent":"多並道路課長","answer":"車の上からもありますけれども、歩道については、降りてチェックするようなチェックの仕方をしております。そういうところを中心にチェックをして、確認した段階で、すぐ根上がりの対策工事ということで行っているところです。","id":"exchange-021"},{"speaker":"松永委員","kind":"質問","question":"空気と水の養分があるので、地面の深くまで根を伸ばすことができますという、新たな工法をつくられているそうです。本区におきましては、その根上がり対策としてどのような工法を使われているのかの説明を求めました。","respondent":"多並道路課長","answer":"ちょうどオリンピック・パラリンピック会場周辺の工事の関係で、これもあわせて公園課と連携しながら対策していこうということで検討しています。土壌改良材を中に入れ替えまして、今後、根上がりがないようにということで対策工事を行っているところです。","id":"exchange-022"},{"speaker":"松永委員","kind":"質問・要望","question":"そうした開かずの踏切は何カ所あるのか伺いまして、そこには待ち時間を緩和するために陸橋がつくられております。その陸橋ですが、その辺も自転車が乗り降りできるような歩道にしてもらいたいというご要望なのですが、そうしたご意見に対して伺いたいと思います。","respondent":"中村都市計画課長","answer":"やはり朝晩の通勤時間、こういったところでは一般の歩行者がそこでお待ちいただくというような、そういった現象は確認をしています。","id":"exchange-023"},{"speaker":"須貝委員","kind":"質問","question":"もし両方つけたら、この事故は起きなかったのではないですか。どう思われますか。","respondent":"桑波田交通安全担当課長","answer":"どちらかを優先道路ということで指定しまして、片方は必ずとまってもらう、そしてもう一方は優先ということでそのまま通行。２つともこういったところを一時停止とか、とまらなければ違反になる、そういったところで規制がかかっているところです。","id":"exchange-024"},{"speaker":"須貝委員","kind":"質問","question":"絶対とは言えないけれども、どうして人命がかかっているのに、なぜこういうことができないのですか。とまれというふうな、そういうことをやっていかなかったら、このような事故はなくならないではないか尋ねました。","respondent":"桑波田交通安全担当課長","answer":"そういったところの普及啓発を続けていく、そういったこともありますし、ドライバーに対しても注意喚起を実施していくです。こちらはゾーン３０ということで指定して規制をかけてまいりますので、そういったところで対応していきたいと考えております。","id":"exchange-025"},{"speaker":"須貝委員","kind":"質問・要望","question":"平成２３年度と比較して、区における住宅や倒壊で道路を閉塞する恐れのある建築物の耐震化率はどこまで進んだのですか、教えてください。そして耐震化率の目標は達成できるのですか、の説明を求めました。","respondent":"鈴木建築課長","answer":"精緻な数字を把握、検討、出そうという作業をしています。目標は、平成３２年度９５％ですから、なかなか難しい状況だです。","id":"exchange-026"},{"speaker":"須貝委員","kind":"質問","question":"それに多くの電線と、多くの看板類が、これはもう本当に今、危険な状況にあると思います。こういうものの対策は進んでいるのでしょうか、の説明を求めました。","respondent":"今井土木管理課長","answer":"道路上の障壁、そういうふうなバリアについても、警察と連携して対応をとっております。駅周辺については特にとっているところです。","id":"exchange-027"},{"speaker":"須貝委員","kind":"質問","question":"では、歩いてみるとどうですか。では、どうするのですかという話です。","respondent":"高梨木密整備推進課長","answer":"そういうところの技術的課題等の状況を注視しながら、検討を進めてまいりたいと考えているところです。平成３２年度末までに不燃化１０年プロジェクトとして、不燃領域率７０％達成に向けて取組みを加速させていく考えです。","id":"exchange-028"},{"speaker":"須貝委員","kind":"質問","question":"では、どうするのですか。今こういうふうに政府を挙げてでも、私は避難路の確保ということを最優先に考えるべきだと思いますが、その辺についてご見解の説明を求めました。","respondent":"高梨木密整備推進課長","answer":"引っ越しにかかわる住替えの費用であるとか、建替えについての不燃構造化の費用についても一部助成を開始するなど取組みを加速させているところです。","id":"exchange-029"},{"speaker":"須貝委員","kind":"質問・要望","question":"品川区には、宿直の人が今１人、たしか理事者の方がいらっしゃると思いますが、１人で大丈夫なのですか。これだけの人を、夜間、緊急事態があったときに、１人だけで大丈夫か尋ねました。","respondent":"高梨木密整備推進課長、古巻防災課長","answer":"最初に、避難路の機能強化について私から１点お答えをします。滝王子通りがありますが、こちらは平成２１年度から現況幅員７.２ｍを１０ｍに拡幅すべく事業を進めているところです。重層的に情報配信の仕組みを考えまして、より迅速に正確な情報が伝わるように努めていきたいと考えているところです。","id":"exchange-030"},{"speaker":"吉田委員","kind":"確認","question":"しかし、自転車も車もお互いにどちらにはみ出てはいけないという規制はないというふうに理解したのですけれども、その理解でいいのかどうか伺います。それで、品川区では、自転車は基本的には車道を通ることを原則するという理解でよいのか確認させてください。","respondent":"多並道路課長","answer":"ただ、もし交通量等を踏まえながら警視庁と協議しながら進めていくところがあれば、それはもちろん進めていこうと思っているところです。","id":"exchange-031"},{"speaker":"吉田委員","kind":"質問","question":"検討されるべき重点施策が示されておりまして、今のご答弁を伺うと、かなりの道のりがあると考えます。品川区として、法もできましたけれども、ちょっとざっくりした質問で申し訳ありませんが、自転車活用の方向性を伺いたいと思います。","respondent":"多並道路課長","answer":"ただ、この計画につきましては、今、政府で閣議決定を平成３０年４月か６月ぐらいに出る予定だということで、今のところ情報は来ています。","id":"exchange-032"},{"speaker":"吉田委員","kind":"質問","question":"車の運転手にとっても安心だし、自転車の親子にしても歩行者に気兼ねせずに済むと思うのですけれども、どう考えたらいいのでしょうか。警察とはルールの徹底などをどのようにすり合わせているのか伺います。","respondent":"桑波田交通安全担当課長","answer":"そういったところは、また国の動向を注視しながら、区としてのあり方を検討してまいりたいと思います。１３歳未満の子どもでありますとか、７０歳以上の方であれば、歩道を通行できるということになってあります。","id":"exchange-033"},{"speaker":"吉田委員","kind":"質問・要望","question":"必死でお子さんと一緒に車道を走らせて、危ないと周りが思うというような事例も伺っていますので、ぜひ徹底させてほしいと求めました。もしくは行おうとしていらっしゃるか伺いたいと思います。","respondent":"桑波田交通安全担当課長","answer":"区では、いろいろな交通安全啓発を実施しております。乗らない方であっても、いろいろ自転車に限らず幅広く周知しておりますので、乗らない方を対象にしても啓発しています。","id":"exchange-034"},{"speaker":"吉田委員","kind":"質問・要望","question":"８８件というのは、指導した数なのでしょうか。その後、どういう呼びかけがなされているか伺います。","respondent":"持田河川下水道課長","answer":"東京都と連携しながら、チラシを配ったりとか、模型を展示していろいろ呼びかけているところです。助成もありますが、設置をしていくというのはなかなか難しい実情があるところはこちらでもわかっておりますが、水質改善は重要な事業ですので。","id":"exchange-035"},{"speaker":"吉田委員","kind":"質問・要望","question":"立会川や目黒川の水をきれいにしてほしいという声は結構たくさん届くのです。使われていることをどのように確認しているのか伺いたいと思います。","respondent":"持田河川下水道課長","answer":"こちらの予想よりは、実はあまり使われていないというようなお答えもいただいているところです。そういった形で所管としては、やはり使っていただくという形でのＰＲが必要と感じているところです。","id":"exchange-036"},{"speaker":"吉田委員","kind":"質問・要望","question":"それから、障害者団体のほうから、なぜそのことがうまく伝わっていなかったのか。しながわ区民公園のだれでもトイレについては、同じ轍を踏まないようにしていただきたいのですが、その辺はいかがか尋ねました。","respondent":"溝口公園課長","answer":"それについては、事業者も含めて対応させていただいているというのが今の現状です。さまざまな声を聞きながら、だれでもトイレまたはトイレの整備を進めていきたいというふうに考えているものです。","id":"exchange-037"},{"speaker":"吉田委員","kind":"質問・要望","question":"あらかじめ立ち会わせてほしいと申し入れがあったというふうに聞いておりますので、そういう声はぜひ生かして、むだな工事とかお金を使わないようにしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"高橋（伸）委員","kind":"確認","question":"成果報告書１６６ページ、人孔蓋枠等整備費、１６４ページ、道路維持費の中の道路空洞修繕についてお伺いいたします。お伺いいたしますけれども、東京２３区のマンホールカードについて、カードに関する問い合わせがあったのかどうか。","respondent":"持田河川下水道課長","answer":"やはりオリジナルのデザイン、ご当地のデザインをして、それがカードになっているというような状況があるところです。区としてのデザインを考えて、そこから事業を進めていくという形になると思いますので、またしっかりと研究していきたいと思ってあります。","id":"exchange-039"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"モンチッチが世界３０カ国以上で愛されているということで、今、モンチッチのカードが柴又観光所で配布をしているということです。いろいろ検討していただきたいというのが私の要望なのですけれども、新しく新設してと、そういった施策の面でお伺いしたいと思います。","respondent":"持田河川下水道課長","answer":"一般には滑らないようにですとか、人がつまずかないようにですとか、幾つか検討すべき内容があるとは思います。しっかり検討していきまして、区のＰＲにもなるとは思いますので、そういったものを踏まえながら検討は進めていきたいというふうに考えてあります。","id":"exchange-040"},{"speaker":"高橋（伸）委員","kind":"質問","question":"続きまして、１６４ページ、道路維持費の道路空洞修繕についてお伺いいたします。点検をしたと思うのですけれども、区内にどの程度修繕の箇所、一番補修が必要だった箇所を教えてほしいと求めました。","respondent":"多並道路課長","answer":"平成２８年につきましては、２回目ということもあって、空洞自体は０というところでございました。もう少し軽易なところがあるということで確認したところが１カ所ありましたので、予防的な見地も含め、１件修繕を行ったです。","id":"exchange-041"},{"speaker":"高橋（伸）委員","kind":"質問","question":"平成２８年度の主要の施策の成果について、調査をしました結果、この報告書には道路空洞修繕で金額が４４３万６,１０８円が記載されております。Ｃの中で、そのどれかが当てはまるという中で、この修繕が行われたという解釈でよろしいのか尋ねました。","respondent":"多並道路課長","answer":"委託費２９９万円余に対して、工事費１４３万円ほどで行いました。その工事費につきましては、今のご指摘のとおり、対策を行ったものです。","id":"exchange-042"},{"speaker":"あくつ委員","kind":"確認","question":"毎年９億円もかかって困るのだ、できれば区民はあまり乗らないでほしいというお考えなのか、例えば東京都が言うような前向きな考えなのか。先ほど、そういうことも含めて品川区の区民の自転車の利用についてのご見解を伺いたいと思います。","respondent":"桑波田交通安全担当課長","answer":"条例の中でも、駅周辺の方はなるべく歩いていただいて、真に必要な方は自転車をお使いいただきたいということで進めているところです。","id":"exchange-043"},{"speaker":"あくつ委員","kind":"質問","question":"品川区における自転車事故の推移について、また、重症や死亡につながった自転車事故が発生しているのか教えてください。死亡事故が発生した場合、最高でどのぐらいの損害賠償責任を負うのか、一般論でも結構ですけれども、ご存知でしたらの説明を求めました。","respondent":"桑波田交通安全担当課長","answer":"５５件の事故が、５５件ありまして、平成２７年と比べますと１件の減少という状況でございました。こちらにつきましては、意識が戻らない状況になったということで、約９,５００万円の賠償を命じられたという事例が紹介されているところです。","id":"exchange-044"},{"speaker":"あくつ委員","kind":"質問","question":"ここで伺いたいのが、登録台数と言い替えてもいいのですけれども、これが品川区内にどれぐらいあるのか。数万台と書いてあるのですけれども、日常的に利用されている台数がそのうちどれぐらいあるのか教えていただけますか尋ねました。","respondent":"桑波田交通安全担当課長","answer":"自転車の保有台数ということでございましたが、人口も３０万人を超えておりまして、各家庭には１台もしくは２台以上あると思うのですが、正確な数字はとれていないところです。","id":"exchange-045"},{"speaker":"あくつ委員","kind":"質問","question":"品川区でのＴＳマークの加入状況がわかれば教えてください。今後ますます増えるであろう自転車事故に関して、保険加入の重要性についてどのように考えているのかの説明を求めました。","respondent":"桑波田交通安全担当課長","answer":"ＴＳマークにつきましては、いろいろな安全教育、もしくはスケアード・キャンペーン、こういったところで警察署と連携しながら推奨しています。警察署と連携しながら、自転車等の特約等が附帯でついておりますので、こういったところを啓発しています。","id":"exchange-046"},{"speaker":"あくつ委員","kind":"質問・要望","question":"このことについて品川区に確認をしたいのですが、品川区内で、この特別区交通災害共済に加入していた区民はどの程度存在していたのか。企画調整課なのかわかりませんけれども、の説明を求めました。","respondent":"柏原企画調整課長","answer":"平成１２年度当時の記録ですけれども、当時、品川区として区民の方が加入されていたのが４万人余です。それぞれコースがあったようですけれども、お一人５００円、１,０００円、２,０００円のそれぞれのコースがあったということは承知しています。","id":"exchange-047"},{"speaker":"あくつ委員","kind":"質問","question":"当時、この廃止によって４万人の方の保険はどこに行ってしまったのか伺いたいのが１つ。時間がないのであわせて伺いますが、新設の区民交通傷害保険制度について、当時、２３区のうち半数以上の１２区で採用を決定した。","respondent":"柏原企画調整課長","answer":"当時の４万人余の方が、民間の保険のメニューが出ましたので、そちらのほうに随時移行してもらったというところで聞いてあります。その後の２３区で行っていた保険事業が新たな商品という形で引き継がれた後に、当時、そういう判断もあったというところは聞いているところです。","id":"exchange-048"},{"speaker":"あくつ委員","kind":"質問","question":"現行の１,０００万円から１億円に引き上げられると決まった今、おそらく未加入のところについては、お互いの様子見をしている状況だと私は思います。検討していく、研究していくということも必要だと思うのですが、この点について最後にご見解を伺います。","respondent":"桑波田交通安全担当課長","answer":"こういったものを進めながら、他区の状況、こういった情報収集にも努めてまいりたいと思います。こちらも保険の補償が１０月１日から１億円に引き上げられたということがありましたので、引き続き対策を進めていきたいと考えております。","id":"exchange-049"},{"speaker":"安藤委員","kind":"質問・要望","question":"この点で伺いますが、今回の１４９ｍという高さは航空法による高さの最高限度めいっぱいとほぼイコールではないのか伺います。伺いますが、区は領域Ｃ以上が出る場合を風害と認識するという考えなのか伺いたいと思います。","respondent":"稲田都市開発課長","answer":"本日から第１７条に基づいて、公告・縦覧等を行い、夜は大崎ゲートシティの労政会館で説明会を実施するというものです。東京都も都市計画において、今日、一緒に説明をするものですので、同じく東京都でもお知らせをしています。","id":"exchange-050"},{"speaker":"安藤委員","kind":"質問・要望","question":"旧東海道に流入する通過交通の転換を図り、歩行者の安全に係ることを掲げていますが、交通量の調査は実施したのかどうか伺います。建物は何棟か、何戸、何世帯が立ち退きになるのか、何人が立ち退きになるか、それぞれ伺います。","respondent":"稲田都市開発課長、東野まちづくり立体化担当課長","answer":"説明会等の広報ですが、広報しながわです。領域Ｄが強風地域相当というところでございまして、区はＡとＢを目指して風環境を整えていこうというところでやっております。ピーク時間帯につきましては１８０台が通過しているというような結果が出ているものです。駅前広場につきましては、それら交通状況を改善するという点では、寄与するものとして考えております。","id":"exchange-051"},{"speaker":"安藤委員","kind":"質問・要望","question":"こうしたことで地元の理解がない広場整備の都市計画案の提出は、断念するよう求めたいのですけれども、それでもやるのですか。断念するよう求めますが、いかがか尋ねました。","respondent":"稲田都市開発課長、東野まちづくり立体化担当課長","answer":"今回この都市計画法第１７条の趣旨に基づいてやる公告・縦覧等ですが、東京都も公の広報に載せている。あわせて補完してホームページでもやっているということで、広くお知らせしていくというところにおいてやっているものです。地元の再開発協議会、そういうところからは、駅前広場をきちんとした整備をしてほしいという要望書等もいただいてあります。そういったところも踏まえまして、この駅前広場計画を考えていきたいというふうに思っております。","id":"exchange-052"},{"speaker":"安藤委員","kind":"質問・要望","question":"しかも説明もまともに行おうとせず、トップダウンで進めるこのような大型開発などは、ぜひ見直してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"筒井委員","kind":"質問・要望","question":"汚いというイメージ払拭のためにも、ぜひとも水質改善を進めていっていただきたいのですけれども、いかがでしょうか。ぜひとも早く行っていただきたいと考えておりますが、区としていかがお考えか尋ねました。","respondent":"持田河川下水道課長","answer":"下回っているという状態でございまして、現状としては、水質としてはそういう状況にあるです。東京都と連携しまして、さまざまな下水道の合流改善の施策なども進めてございまして、そういった形での合流改善を行っているというようなところです。","id":"exchange-054"},{"speaker":"筒井委員","kind":"質問・要望","question":"そして区外の方々に周知もしていっていただきたいと、東京の河川、運河はきれいだということをぜひとも周知を徹底していただきたいと考えております。そこで、分譲マンション実態調査を行われたのですけれども、その内容と調査結果についての評価をお伺いいたします。","respondent":"長尾住宅課長","answer":"分譲マンション実態調査ということで、東京都と連携しながら、区独自のマンション施策検討の基礎資料として活用するために調査を実施したものです。そういった部分でこちらが把握している状況とは違う状況もあるかもしれないというふうには認識しております。","id":"exchange-055"},{"speaker":"筒井委員","kind":"質問・要望","question":"防災力向上につなげるという意味で、今後増えていくマンションについて、いかがお考えでしょうか。その２点、お伺いいたします。","respondent":"長尾住宅課長","answer":"管理組合の方を対象にしまして、住宅課では、マンション管理組合の防災対策等検討交流会を実施しております。その中で、それぞれのマンションにおける防災対策がどういうふうにしていったらいいかというところを検討していただく支援を実施しております。","id":"exchange-056"},{"speaker":"大沢委員","kind":"質問","question":"１６３ページから交通安全のことで伺います。警察と連携をとりながら、今、どのようにそれを取り組んでいらっしゃるのかの説明を求めました。","respondent":"桑波田交通安全担当課長","answer":"親子自転車教室ということで、子どもにルールを教えるとともに、親も子に見本を見せるように周知を図っております。その他、自転車の安全利用キャンペーンですとか、高齢者講習といったところで連携を図りながら、周知を図っているところです。","id":"exchange-057"},{"speaker":"大沢委員","kind":"質問","question":"自転車のことについて伺いまして、今、７３０件というのは全体の交通事故についてですね。先ほど自転車は５５件ということで、ちょっとご答弁が私のものとかみ合っていないのですけれども、かみ合ったご答弁をお願いします。","respondent":"桑波田交通安全担当課長","answer":"自転車につきましては、昨年は、第一当事者、事故を起こした方が５５件ありまして、平成２７年と比べますと、１件ではありますが、減少しています。","id":"exchange-058"},{"speaker":"大沢委員","kind":"質問","question":"伺いたいのは、子どもを前後に乗せる大きな自転車、電動付きの自転車が今は非常に多くなっているのが現状です。それについては、課長、十分にご認識しているのかどうかの説明を求めました。","respondent":"桑波田交通安全担当課長","answer":"自転車は原則車道ということでありますけれども、そういった規制によって歩道も通行できるというふうになっておりますので、そういったところをあわせて周知しています。","id":"exchange-059"},{"speaker":"大沢委員","kind":"質問","question":"規制と決まりということですけれども、自転車は通常車道に沿って走るようにということで、私、理解しているのですが、それでいいか尋ねました。","respondent":"桑波田交通安全担当課長","answer":"自転車は原則車道の左側を通行していただくです。","id":"exchange-060"},{"speaker":"大沢委員","kind":"質問","question":"決まりと習慣が非常に齟齬が生じてしまっている、そこのところはどういうふうに帳尻を合わせて調和をとっていくのか、お考えがあればの説明を求めました。","respondent":"桑波田交通安全担当課長","answer":"自転車につきましては車道の左側ということで、こういったところを現在も路面の表示ですとか、ナビマーク、こういったレーンをつくりまして周知を図っているところです。","id":"exchange-061"},{"speaker":"大沢委員","kind":"質問・要望","question":"周知を図っていても、慣習、習慣がそうさせてしまって、私もまだ左を何となく走ってしまいます。そこらをしっかりと利用者にわかるようにやっていただきたいのですが、案というか、妙案をお持ちであればの説明を求めました。","respondent":"桑波田交通安全担当課長","answer":"警察と連携を図りながら、東京都、警視庁でつくっていますパンフレット等もあります。通行のしかた、こういったものも出ておりますので、そういったものを活用しながら周知を図っていきたいと考えております。","id":"exchange-062"},{"speaker":"大沢委員","kind":"質問・要望","question":"そこらをピンポイントでなるべく効果的に周知を図ってほしいと求めましたし、そこらをしっかりと線引きをしてほしいと求めました。なぜはす交いに渡るかの説明を求めました。","respondent":"桑波田交通安全担当課長","answer":"横断歩行者につきましては、それぞれ斜めに渡ることはできません。そのまま横断歩道に沿ってＬ字型で、もしくは反対側に回る、こういったものが正しい通行方法です。","id":"exchange-063"},{"speaker":"大沢委員","kind":"意見","question":"起こした人、起こされる側が両方とも不利益を被ってということに、はたまた行政が書いていなかったからという責任問題にもなりかねない。そこらを周知徹底、あるいは、何かの感じでしっかりあらわすことが必要だと思いますけれども、どう思いますかとの意見を述べました。","respondent":"桑波田交通安全担当課長","answer":"戸越三丁目のこちらの交差点に関しまして、荏原警察署のほうからも、そういったルールを守らない、こういったお話等も伺っております。もしくは街頭に警察官を立たせる、そういったところで対策してまいりますので、区のほうもできる啓発等は進めてまいりたいと考えております。","id":"exchange-064"},{"speaker":"大沢委員","kind":"質問","question":"それはお願いします。なぜスクランブル交差点のところ、はす交いに渡るかの説明を求めました。","respondent":"桑波田交通安全担当課長","answer":"こちらについては、斜めに横断することはできないです。そういったところもあわせて対策、啓発できるように、区としてはやっていきたいと考えております。","id":"exchange-065"},{"speaker":"大沢委員","kind":"質問","question":"斜めに渡ったほうが距離が短いからですよね。とまっていても事故があったくらいですから、とまっていても事故が起こらない可能性はゼロではないわけですから、お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"塚本委員","kind":"質問","question":"それから、時間があれば、１６８ページの水辺利活用事業ということでお伺いしたいと思います。そこで、まず最初にお伺いしたいのが、現在、品川区の無電柱化計画、類するようなものでもいいのですけれども、取組み状況をお伺いしたいと思います。","respondent":"多並道路課長","answer":"平成２９年１月には、今、ゼロベースで特に狭い道路への無電柱化をどう進められるかということで検討しています。それを含め、東京都の補助金のスキームなどがありますので、そういうものをにらみながら今後の進め方を検討しています。","id":"exchange-067"},{"speaker":"塚本委員","kind":"確認","question":"ありがとうございました。６ｍ以上の道幅がないと、これまでのやり方ですと難しい面があるというようなこともお伺いしてきましたけれども、そこを確認させてください。","respondent":"多並道路課長","answer":"６ｍ、要するに機器がどうしても小さくなっていなければいけないということで、そこがどうもクリアするのが難しいということが国の今のところです。今後の、特に木密地域の無電柱化をどう進めていけばいいかということは、よく注視しています。","id":"exchange-068"},{"speaker":"塚本委員","kind":"質問・要望","question":"わかりました。１つお伺いしておきたいのは、どういった優先順位で進めていこうというところを考えていらっしゃるのか、もう少し詳細にお伺いできればと思います。","respondent":"高梨木密整備推進課長、多並道路課長","answer":"木密地域において緊急車両が通行し、避難救援に資する道路が６ｍ以上の道路ということで、防災生活道路として位置づけをしております。その道路を中心に考えていきたいと、このように考えております。無電柱化の考え方ですけれども、そういうものとか、幅広く無電柱化を進めていくことを検討していきたい。ただ、特に一番重点的に置くべきところは防災ではないかということで、それはぶれることはないところです。","id":"exchange-069"},{"speaker":"塚本委員","kind":"質問","question":"こういった状況、区にも届いておりますでしょうか。その状況をお聞きしたいと思います。","respondent":"溝口公園課長","answer":"過去、３公園ほどバスケットゴールを設置したところではありますが、そういった状況もあります。今後もバスケットゴールの設置については、どういう形で設置できるのか、そういったところも含めて、今後検討していきたいと考えているものです。","id":"exchange-070"},{"speaker":"塚本委員","kind":"質問・要望","question":"具体的にバスケットゴールを設置していきましょうというふうなことを検討していこうとしたときに、やはりそういったところになってくるのか。","respondent":"溝口公園課長","answer":"２６６公園あるうちの多目的広場が設置されているのが４公園、そのうち中央公園についてはバスケットゴールを設置しているような状況です。","id":"exchange-071"},{"speaker":"塚本委員","kind":"質問・要望","question":"実は私、そちらでそういうバスケットゴールのご要望を伺っていると、ぜひこういった要望にも応えていっていただくように。ここにつきまして、まずこの検証結果、実験の結果として得られたものはどのようなものがあったかお伺いしたいと思います。","respondent":"持田河川下水道課長","answer":"昨年度、平成２８年度、実験を行いまして、結果としては１１ルート、２１４便、２,８０４名のお客様の乗船があったです。特に天王洲のエリア、また五反田を中心にしまして周遊するルート、こういったルートでお客様が多かったというふうな形で内容を把握しています。","id":"exchange-072"},{"speaker":"塚本委員","kind":"質問","question":"舟運ルートの開拓および可能性の検証ということで、区内イベントや観光施設との連携、水辺のにぎわい創出の手法の検討ということもございました。可能性というか、そういったところについてもお伺いしたいと思います。","respondent":"持田河川下水道課長","answer":"やはり訪れる水辺のスポット、いろいろ魅力的なものをつくれば、舟運のほうも広がっていくというふうに所管としては考えてあります。こういったこともございまして、そういった地域のさまざまなイベントと連携をしながら舟運の可能性は広がっていくというふうに考えてあります。","id":"exchange-073"},{"speaker":"塚本委員","kind":"質問・要望","question":"先だって、課長がテレビに出られて、テレビ朝日だったと思うのですけれども、取材をされておられまして、たまたま家へ帰ってテレビをつけたら映ったもので、おやおやと思ったら、品川区はやはりすごく水辺で注目されているというところだと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"いながわ委員","kind":"質問","question":"先ほど来、そういったところをしっかり改良していくべきではないかという思いがございましたので、その辺をまず１点お伺いするということ。もちろん抜ければ、国道から国道をつなぐ幹線道路になると思うので、その辺をお伺いしたいと思います。","respondent":"溝口公園課長、中村都市計画課長","answer":"委員ご指摘の立会道路側、光学通り側の電柱についても、何とか移設ができないかというのは整備にあわせて東電と交渉したところです。平成３１年３月いっぱいですが、これについては、まだ東京都は具体的に変更するとか、そういった情報は特にございません。交差する１６３号線、前捌きなども行っておりますので、混雑は起きるという想定はないです。","id":"exchange-075"},{"speaker":"いながわ委員","kind":"質問・要望","question":"１点、この横に白線というんですか、車両はこの白線の内側を通らなければいけないわけですね。そもそも駐停車禁止の中に、なぜバス停が設置してあるのだろうという疑問の声も聞こえてきたので、その辺がどういう状況なのかの説明を求めました。","respondent":"多並道路課長、中村都市計画課長","answer":"ただ、警察との関係で、やはりそこの道路自体は歩道がありませんから、そういうものを示していかなければいけないということです。そういったところから、交差点内でありながら、駐停車、その辺は状況によってできるというようなところで、警察と一緒に考えた結果です。今後またまちづくりにあわせて検討してまいります。","id":"exchange-076"},{"speaker":"のだて委員","kind":"質問・要望","question":"２９号線取消しを求めて、裁判も今年６月２９日に東京地裁に集団提訴を住民が行いました。裁判を行うほど根強い反対があるのはなぜだと考えているのか伺います。","respondent":"中村都市計画課長","answer":"そういったところを十分に理解をしていただく、理解を深めていただく、こういった説明を重ねながら、東京都のほうで今整備をしています。区としましても、これと連携して進めていく所存です。","id":"exchange-077"},{"speaker":"のだて委員","kind":"質問","question":"私が伺ったのは、なぜ裁判を行うほど根強い反対があるのかということですので、ぜひ伺いたいと思います。","respondent":"中村都市計画課長","answer":"そういったところで区民の皆様、あるいはほかの自治体などでも地域の皆様が関心を持っているというところだと思います。こういったところがクローズアップされたのだというふうに認識をしておりますけれども、それも道路のできた暁には、防災性が非常に向上するという。","id":"exchange-078"},{"speaker":"のだて委員","kind":"質問","question":"先日、立ち退きを迫られる方からお話を伺いましたら、自分の家だけれども自分の家と思えないという衝撃の声を伺いました。この２９号線によって、商店街、住宅街などが、町が壊されると考えているのか伺います。","respondent":"中村都市計画課長","answer":"今と変わらず、専門のコーディネーターに委託をしまして、専門家の観点から生活が再建できるように親身に相談に乗っていると聞いております。区といたしましても、地域の協力いただく皆様方の今後の生活がしっかりと成り立つように、東京都のほうにも求めてまいりたいと思います。","id":"exchange-079"},{"speaker":"のだて委員","kind":"質問・要望","question":"この区内の特定整備路線についても、都に見直しを求めてほしいと求めましたが、いかがでしょうか。そして、国が見直しを出した理由を区がどう捉えているのかも伺います。","respondent":"中村都市計画課長","answer":"その検討がなされるですが、これは東京都もそのような判断でこの事業を進めるということで、当初から対象外という判断でございました。","id":"exchange-080"},{"speaker":"のだて委員","kind":"質問・要望","question":"やめてほしいということで都に求めてほしいと求めましたが、平成２８年３月時点の見直し状況でも、廃止が２路線で１.８kmしかなっていません。２９号線のすぐ近くには、第二京浜国道もありますので、２９号線はぜひやめてほしいと都に求めてほしいと求めました。","respondent":"中村都市計画課長","answer":"１つは道路の整備、そういった考えに至ったところですので、最初から道路ありきで検討されてきたというところではございません。引き続き、品川区も東京都の木密課題の解決に向けた取組みに対して、連携して進めていく所存です。","id":"exchange-081"},{"speaker":"のだて委員","kind":"質問・要望","question":"次に、戸越公園駅再開発についても伺います。どういった声があったのかご説明ください。","respondent":"東野まちづくり立体化担当課長","answer":"こちらにつきましては、事業者による説明会が６月、区の都市計画素案としての説明会を８月に行ってあります。事業者による説明のときは、どちらかというと、まちづくりのために進めていただきたいというような声が多かったように思います。","id":"exchange-082"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひやめてほしいと求めましたけれども、いかがでしょうか。改めて、なぜこの超高層にしなければならないのかという声もありましたので、理由も伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"そういったものにつきまして、町の方みずからが、この再開発計画をされているものです。区としては、こちらを支援していく考えです。","id":"exchange-083"},{"speaker":"横山委員","kind":"確認","question":"区のホームページから飛ばせていただきまして確認しましたところ、六丁目、来年度ではなく平成２９年度ということでこちらはよろしいのでしょうか。現在の整備状況とスケジュール、そして地域の方々や子どもたちへの周知・啓発について確認させてください。","respondent":"桑波田交通安全担当課長","answer":"聞いているところは来年度で実施するです。いろいろな各種講話やキャンペーン、こういったものを通じながら、ゾーン３０に指定されましたということで周知を図っていくところです。","id":"exchange-084"},{"speaker":"横山委員","kind":"確認","question":"平成２９年度から既に進めていただいているということで、先行してホームページのほうには記載されているということの確認でよろしいか尋ねました。","respondent":"桑波田交通安全担当課長","answer":"早急に警視庁のほうでも対策をとって、何とか年度内に進められるように、決定がおりるように進めているものと認識しております。夏休みに向けての事故防止ということで、指導のチラシ等をつくりまして、周知を図らせていただいたところです。","id":"exchange-085"},{"speaker":"横山委員","kind":"質問・要望","question":"２点目が、先ほど６ｍという話が出てきましたけれども、コスト面というのはどういうふうになっておりますでしょうか。３点目、そういった点で理解をどう求めていくのか、そのあたりのお考えの説明を求めました。","respondent":"多並道路課長","answer":"今いただいた４点の件で、委員の今のご指摘のとおり、国でも検討の中では低コストという手法の考え方も入っております。いろいろな観点から検討するべきところだと思っていますので、ここはよく注視していきたいと思っているところです。","id":"exchange-086"},{"speaker":"横山委員","kind":"質問・要望","question":"４点、大変わかりやすく教えていただきました。最後にもう一度お願いいたします。","respondent":"多並道路課長","answer":"これからの進め方という点ですけれども、やはり大きいのは、防災面、特に木密地域等の狭い道路への無電柱化は進めていくべきだと考えています。","id":"exchange-087"},{"speaker":"横山委員","kind":"質問・要望","question":"３点目ですけれども、建設土木、専門職の現状についてお伺いをいたします。品川区におきまして、建設土木の専門職として働く女性や若者の現状について、どの程度把握しておられますか尋ねました。","respondent":"溝口公園課長","answer":"そういった中で、やはり公園という１つの切り口ではありますが、男性から女性、多様な意見を聞きながら、よりよい公園整備に努めているところです。技術職一体となって、男女問わず若い職員から高齢の職員の技術継承を含めて、さまざま取り組んでいるというのが現状です。","id":"exchange-088"},{"speaker":"横山委員","kind":"質問","question":"品川区において専門職としての技術の継承ですとか、建設土木の職場において、女性や若者のアイデアはどのように生かされているのでしょうか。公園の部分をお聞きしたのですけれども、女性や若者の生かし方の成功例、先進的な事例がありましたら教えていただけたらと思います。","respondent":"高梨木密整備推進課長","answer":"その中で若手職員がどういった不安を感じているのか、どういった疑問を感じているのかということを吸い上げながら検討していくということ。ベテラン職員と意見交換をしながら技術継承にも努めてまいるというようなことを取り組んでおります。","id":"exchange-089"},{"speaker":"横山委員","kind":"質問・要望","question":"専門性を求められる建設土木の業界におきまして、若者の方、そういった取組みを進めていただけたらと考えています。多様な人々による新鮮な視点を生かしていける場を増やしていただきたいと要望いたしますが、区のお考えの説明を求めました。","respondent":"高梨木密整備推進課長","answer":"技術職の区職員がしっかり働いている、またこういうふうになりたいというなり手育成というところも効果としてはあると考えておりますので、引き続き鋭意取り組んでまいりたいと考えております。","id":"exchange-090"},{"speaker":"横山委員","kind":"質問","question":"４点目に、子ども達のアイデアを活かした公園整備についてお伺いいたします。地域の思いをワークショップの形式を通して今回反映されているというふうに聞いておりますが、どのように反映されているのか尋ねました。","respondent":"溝口公園課長","answer":"平成２８年度に設計をさせていただきまして、現在、９月から工事に入って、今年度末の竣工を目指して、今現在、工事が進められているところです。","id":"exchange-091"},{"speaker":"横山委員","kind":"質問・要望","question":"１つのよいモデルケースとして、ほかの地区でも広げてほしいと求めましたが、いかがでしょうか。小学校の子どもたちのアンケート第１位の遊具を取り入れていただいたりということで、さらにブラッシュアップしていくお考えはありますか尋ねました。","respondent":"溝口公園課長","answer":"地域の方たちのワークショップという形なのか説明会、ご意見を聞きながら、よりよい公園整備に努めていきたいというふうに考えております。","id":"exchange-092"},{"speaker":"横山委員","kind":"質問・要望","question":"スリルを感じながらさまざまな遊びにチャレンジできる体験の場としての公園づくりもぜひ進めていただきたいと考えております。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-093"},{"speaker":"浅野委員","kind":"質問","question":"うれしい声も伺いましたので、本当に気をつけてやらないと、区民の方にも迷惑をかけてしまうのかということを私も改めて感じたものであります。そこに引っかかってというのでしょうか、１０人以上の方が倒れたといいましょうか、このような話も聞きました。","respondent":"多並道路課長","answer":"問題があれば、不良があればやり直させる等、指導しています。区としても対応するのと、その原因者である企業者等ともよく調整しながら、現実的に進めていきたいと思っているところです。","id":"exchange-094"},{"speaker":"浅野委員","kind":"質問・要望","question":"それとも道路を管理している方の責任なのか、これについて私も聞き取れなかった部分があるかと思いますけれども、教えてください。謝罪とかそういうことを求められたことは、具体的に過去にあったのかどうかということについても教えてほしいと求めました。","respondent":"多並道路課長","answer":"いろいろ地元の方からお話をいただくときは、まずは我々が現場でお話があった方にお話しさせていただいて、最初に状況をお聞きするところです。最終的には、その状況をお聞きした上で、そこの責任者、先ほど申したような原因者が対処していくというのが考え方の大きな流れです。","id":"exchange-095"},{"speaker":"浅野委員","kind":"質問","question":"その近くの方から話を伺いまして、丁寧な施工をされたのかと思いますので、これからもよろしくお願いしたいと思います。寝ている方も多いかと思いますので、何とかこの対処を検討してほしいと求めましたが、いかがか尋ねました。","respondent":"溝口公園課長","answer":"そういった中で、１つはやはり公園にありましたように、ボード類の禁止ということで注意喚起を促す。実際、９月にそういった方を見つけて、そういった公園については巡回警備等にあたりながら注意喚起を促していきたいというふうに考えているものです。","id":"exchange-096"},{"speaker":"西本委員","kind":"質問","question":"この階段を使わなければ行けないということでは、非常に不便をされているということなので、それについての整備はどうなのでしょうかということ。","respondent":"溝口公園課長、稲田都市開発課長","answer":"今、基本的には撤去していく方向で進めておりまして、公園における喫煙所の方針を平成２２年度に定めたところです。１つは大崎駅周辺まち運営協議会における帰宅困難者対策を検討しているというところでございまして、それの検討費用への支援です。目黒川沿いの遊歩道等の検討もこの中でやっております。","id":"exchange-097"},{"speaker":"西本委員","kind":"質問・要望","question":"それで、看板等々もありますが、看板で周知ができるのでしょうか。防災もいろいろなことがありますので、それはやはりご理解をしていただくような努力をぜひしてほしいと求めましたが、いかがか尋ねました。","respondent":"溝口公園課長、稲田都市開発課長","answer":"もう既に出入口のところに「この先、段差あり」という形での表示をしていますので、そういったところで対応させていただければと思います。そういったところを含めて、全体を含めて、今後どうしていくのか考えていきたいと考えています。先ほど言いました大崎駅東口第４地区西まちづくりというところにおきましては、周辺との関連も非常に出てくる地区です。","id":"exchange-098"},{"speaker":"本多委員","kind":"質問","question":"成果報告書の１７１ページの都市開発費について、いろいろと伺っていきますが、今まで取り上げたことの後追いをしていきたいと思います。こういう実績があるとか、これからはこういう考えでいくとか、地域貢献についての考え方の説明を求めました。","respondent":"稲田都市開発課長","answer":"市街地再開発事業を行う中におきましては、このように地域貢献施設というところで整備をしていくものもあります。区と再開発組合とでこの地区の地域貢献にはどういうものが必要かというところで、話し合いながら、協議しながら決めていくというものです。","id":"exchange-099"},{"speaker":"本多委員","kind":"質問・要望","question":"そういった思いをそれぞれ区は把握をするべきだと思いますし、把握をしていると思いますが、そういったことを踏まえて進めてほしいと求めました。","respondent":"稲田都市開発課長","answer":"それから駅から後背地へのデッキのバリアフリーでの接続、そういう公共的なところをしっかりやっていくという意味では、区も組合と一緒になりながら検討しています。","id":"exchange-100"},{"speaker":"本多委員","kind":"質問・要望","question":"その協議の状況を教えていただきたいのと、区内には駅が１４線４０駅ありますけれども、それぞれどの駅にもやはり課題があると思うのです。そういったことへの現状の認識がどうなっているのか、それとあわせて、現状についてはどのようなのかの説明を求めました。","respondent":"稲田都市開発課長、中村都市計画課長","answer":"大崎駅につきましては、ＪＲにも混雑緩和、安全対策というところで、区のほうからは今まで申し入れ等をしてきております。それから、ＪＲにつきましては、これは大井町駅が今年度、来年３月までにホームドアを設置するということで工事が進められているところです。","id":"exchange-101"},{"speaker":"本多委員","kind":"質問・要望","question":"利用者は、常に乗り降りするときはあふれているわけですから、どうしてもそれでは満足しないはずなのです。質問を１つしたいのが、２３区の担当部署にそういう話し合いをやるとか、もしあればお知らせほしいと求めました。","respondent":"中村都市計画課長","answer":"以前、東京都からそういった考えがあるということは聞いております。区といたしましても、そういった東京都の取組みに対して、可能な限り協力をしていくという考えです。","id":"exchange-102"},{"speaker":"本多委員","kind":"質問・要望","question":"羽田空港には１日１３便ということでバスが去年から始まって、運営はエリアマネジメントなので、区が把握している範囲で教えていただきたいのですが。","respondent":"稲田都市開発課長","answer":"それは運転手に支払ってやるということです。成田に行く便につきましては、ネットだと１,０００円なのですけれども、その場で買うと１,２００円という違いがあります。","id":"exchange-103"},{"speaker":"本多委員","kind":"質問","question":"ＪＲの、都営浅草線等もありますけれども、ＪＲ五反田駅の山手線、目黒川寄りに新しく改札口をつくってほしい。ＪＲとの協議を進めていきますということだったのですが、何か進展があれば教えてほしいと求めました。","respondent":"中村都市計画課長","answer":"ＪＲでは、五反田駅の混雑については十分認識をしているというところで、今何かいい案がないかどうかというところは検討していただいている最中です。","id":"exchange-104"},{"speaker":"たけうち委員","kind":"質問","question":"平成３２年には計画が一応終了を迎えるという中で、平成３２年以降は、もう助成が出ないのですかと聞かれたのです。平成３２年を超えてしまったら、これがなくなってしまうのですかと聞かれて、これについての説明を求めました。","respondent":"溝口公園課長、鈴木建築課長、長尾住宅課長","answer":"今回、整備を予定しております駐輪場につきましては、西大井駅周辺の駐輪対策という形で、駅利用者といった方を対象に整備を進めているものです。目標立てをしっかり検討していくわけですけれども、実際には平成３１年度になりますが、もう周知しながら促進事業を進めているところです。共益費としまして、消防設備の法定点検などの附帯施設の法定の点検、あとは小修繕等の附帯施設の維持保全に関する部分が項目としては入っております。","id":"exchange-105"},{"speaker":"たけうち委員","kind":"質問・要望","question":"今度、後から来た人は有料でとめなければいけないみたいなことで無用なトラブルがないように、しっかりその辺も考えていただきたいと要望します。なかなか木造住宅などは特に９５％と非常に厳しいなと思っていますが、どういうふうに言ったらいいか、もう一声の説明を求めました。","respondent":"鈴木建築課長、長尾住宅課長","answer":"先ほどちょっとお話ししましたように、基本的に最終的には平成３２年度時点で国も今後どうしていくかという方針が示されるかと思います。区民住宅のＬＥＤ化による電力の削減に伴う共益費のコスト削減の検討のお話ですけれども、それによるコストの削減効果も異なってくると考えられますので、検討していきたいと考えております。","id":"exchange-106"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、１７３ページの中延二丁目旧同潤会地区についてお伺いしたいと思います。平成３１年３月ということで、１年半で工事が完了となりますけれども、区としても取り組んでいただきたいという思いで質問したいと思います。","respondent":"高梨木密整備推進課長","answer":"そのうち建物完成後に建物に権利変換で戻ってくる権利者につきましては、１１７名の権利者のうち６５名が戻ってくるという形になっております。１９５戸の住宅を建設するのですが、そのうち１２３戸が保留床として分譲されるということで報告を受けているところです。","id":"exchange-107"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"なぜこれだけ出ることになるのかということを１点お聞かせいただきたいのと、つかむべきではないかと思うのですけれども、そこの説明を求めました。","respondent":"高梨木密整備推進課長","answer":"そのほかにも防火貯水槽の設置、施設の管理部分に地域の皆様も利用していただけるような集会室、これは発災時には帰宅困難者等の一時収容施設になる。","id":"exchange-108"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これからあと１年半ででき上がるわけですけれども、地域では本当にさまざまな課題があると思うのです。コミュニティを修復するという形で、区としてもぜひ誠意をもった形で進めていただきたいと思うのですけれども、その点だけお願いします。","respondent":"高梨木密整備推進課長","answer":"事業組合に対しましても、完成までの間、完成後につきましても、地域の皆様と真摯に向き合うよう、区としても指導してまいる所存です。","id":"exchange-109"},{"speaker":"伊藤委員","kind":"質問","question":"私は、成果報告書１６５ページ、道路新設改良費、それから１６９ページの都市計画費、それから水防訓練費に関連して質問します。さまざまアイデアが出ているわけでありますけれども、やはり品川道踏切について品川区として具体的に検討すべきと思いますが、いかがか尋ねました。","respondent":"中村都市計画課長","answer":"そういったものも設置が望ましいですが、やはりＪＲとの協議も十分必要ですので、その点は事業者に対してまずは働きかけを積極的に行ってまいりたいというふうに考えております。","id":"exchange-110"},{"speaker":"伊藤委員","kind":"質問","question":"こういう問題はおそらく先ほどほかの委員から質問があったけれども、新たな視点で検討すべきと思いますが、いかがでしょうか。答弁をお願いいたします。","respondent":"中村都市計画課長","answer":"この踏切の横断につきましては、品川区内、複数箇所あるかと思います。こういったところを可能な限り解消に向けて検討を進めてまいりたいと考えます。","id":"exchange-111"},{"speaker":"伊藤委員","kind":"質問・要望","question":"研究というとあれですけれども、研究か検討していただきたいと思うのですが、いかがでしょうか。改めて答弁をお願いいたします。","respondent":"中村都市計画課長","answer":"区内のスムーズな交通、区民の方のスムーズな移動、こういったものの実現に向けまして、積極的に検討してまいります。","id":"exchange-112"},{"speaker":"伊藤委員","kind":"提案","question":"そういうようなまちづくりをしてくださったらいかがでしょうかということの提案と、それから、浜川寮の隣に今空き地があります。新しいまちづくりの観点から、勝島地区についても都市計画を検討してみてはいかがでしょうかという質問ですが、いかがか尋ねました。","respondent":"中村都市計画課長","answer":"アンケート調査なども行う予定です。まずは計画、ビジョンを立てることが優先ではありますけれども、そういったところで今後取り組んでまいりたいと考えております。","id":"exchange-113"},{"speaker":"伊藤委員","kind":"質問・要望","question":"それから、この八潮・勝島地域をどういうふうにしていくのでしょうかということの現時点での見通しをお知らせください。お願いいたします。","respondent":"中村都市計画課長","answer":"今、ビジョンを策定するというところで、今後、方向性を地域の皆様の意見も聞きながら進めていきたいというふうに考えております。必要に応じて地域の皆様とも検討しながら、こういったものを検討していくということで、そのビジョンが第一歩というふうに考えております。","id":"exchange-114"},{"speaker":"伊藤委員","kind":"質問","question":"そうしたら、そのビジョンを、例えばどれぐらいの期間で策定をしていくのでしょうかということは聞けると思うのです。今から５年、１０年かけてそのことを検討していくとは思わないので、具体化していくかということについての答弁をお願いいたします。","respondent":"中村都市計画課長","answer":"今、勝島地区では、マンションなどが、平成２６年から毎年１戸ぐらい建っているというところで、ただ、今後、今のところは計画はないようですけれども、そういった動きがありますので、ビジョンにつきましては、今年度中を目標に策定に取り組んでいるところです。","id":"exchange-115"},{"speaker":"伊藤委員","kind":"質問・要望","question":"医院がないということのご指摘がありましたけれども、おそらく地域にお住まいの方は、もっとさまざまな要望があるでしょう。そのことに対する品川区の現状の考え方と、それから、あらゆる警察、消防の連携、それから自衛隊との連携について、改めて答弁をお願いいたします。","respondent":"古巻防災課長、川部防災安全担当課長","answer":"そういった情報をきちんと収集いたしまして、そういった状況に備えていくといったようなことをさらに進めていきたい、そのように考えております。今までの品川区と区内３消防署の合同水防訓練につきましては、それから近隣の鉄道事業者等々、そういった方々の連携の中で訓練を進めてまいりました。","id":"exchange-116"},{"speaker":"高橋（し）委員","kind":"質問","question":"立会川雨水放流管関係の工事について、状況と工期、そして完成するとどうなるかということが１点。下水道合流改善事業の勝島運河その２、その３とありますが、またそれも含めてお伺いいたします。","respondent":"持田河川下水道課長","answer":"東京都の説明ですと、このシールド工事が終わるのが平成３０年いっぱいかかるかと。平成２８年のこの事業は、今年度でこちらは既に終わっているということで、水質改善の効果の１つになるのではないかというふうに期待しています。","id":"exchange-117"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"それから、今お話があった水門、そして花海道、区民公園の北側と連続性がある。これらを一体で整備していくようなことが求められているのですが、今、具体的なことがわかればご説明ほしいと求めました。","respondent":"持田河川下水道課長","answer":"ただ、水辺の部分はさまざまな規制もありますし、東京都のほうで今後事業を進めていくところもあります。我々はそういう案を持ちながらも、今、東京都と協議をしていて、東京都としても検討中というようなところです。","id":"exchange-118"},{"speaker":"高橋（し）委員","kind":"質問","question":"現在でも大変危険ということですので、第一京浜を渡る横断歩道です、すみません、交通安全啓発費なのかもしれませんが。通勤、通学の方々だと思うのですが、その辺についての対応はどのようにお考えか尋ねました。","respondent":"桑波田交通安全担当課長","answer":"今、そういったマンション増加についての交通安全対策ですので、現場を見せていただいて、どのような対応がとれるのか、その辺のところはまた検討させていただきたいと思います。","id":"exchange-119"},{"speaker":"高橋（し）委員","kind":"意見","question":"すみません、はっきりと言わず、交通安全啓発費でした。そういったことで人口増加に伴って、そちらの交差点では、現在でもかなり人がおるということですので、ぜひ対応の検討をお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-120"},{"speaker":"若林委員","kind":"質問・要望","question":"これでこの１万１,０００人、こういう方々の通行が確保できるものになっている内容であったのかということの確認をさせてほしいと求めました。","respondent":"稲田都市開発課長","answer":"これは専用歩道を１本通して、車道の片斜線ももう１本トンネルを通すというところで計画は進めております。この４ｍの幅で事業者等々の人数が通行できるというところで計画を立てております。","id":"exchange-121"},{"speaker":"若林委員","kind":"確認","question":"この４ｍの新しい１本の歩道、あれを地元の人は６ｍ道路と言っているのですが、これはもう１回確認します。新生会ですか、本多委員等とともに私も参加をさせていただきましたけれども、安藤委員もいらっしゃったと思います。","respondent":"稲田都市開発課長","answer":"この組合が地元の町会にご説明をしたということなのですけれども、ご理解を得られていないと。今後も新たな対応策等も考えながら、地域の方々にもご説明を丁寧にして進めていきたいと考えています。","id":"exchange-122"},{"speaker":"若林委員","kind":"提案","question":"逆に建設的な提案、１万１,０００人の方々の通勤等、通行を何とか分散させるしかないというところが１つの大きなポイントだと思いますとの意見を述べました。","respondent":"稲田都市開発課長","answer":"この再開発の工事におきまして、地域の皆様には長年の間ご迷惑をかけている、工事の遅れも生じて非常にご迷惑をかけるというところにおきまして、地域の皆様方ともよく話し合いながら、よりよい対策ができるよう考えていきたいと思います。","id":"exchange-123"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"１７１ページ、１７１ページ、五反田地区コーディネート業務委託についてそれぞれお伺いします。五反田エリアの大きな施設２つが、今後の見通しがなかなかつけない中で、どのように五反田地区のにぎわいを創出していくのか。","respondent":"持田河川下水道課長、溝口公園課長、稲田都市開発課長","answer":"勝島運河のエリアということでエリア分けをいたしまして、どのような形のにぎわいが創出できるかというところについての検討をしています。ちょっと管理事務所から離れていますので、監視カメラを設置して、その映像を事務所内で見られるような形をとっております。まちの回遊性を高める商業、業務、文化機能の更新を促進する」と方針に謳っているところです。","id":"exchange-124"},{"speaker":"石田（し）委員","kind":"提案","question":"創業支援の一環でやってみてはどうかという提案もさせていただきましたが、カフェ等をつくっても、これはなかなかいいのではないかと。これは要望で終わりますとの意見を述べました。","respondent":"持田河川下水道課長、溝口公園課長","answer":"平成２８年度は、地域の方にこういった取組みをしているということをまず認識していただくというようなところが主目的でございまして。今後の利用状況等を見ながら、どういう形で利用者のサービス向上に向けて取り組めるのか、そういったものも含めて検討してまいりたいと思います。","id":"exchange-125"},{"speaker":"南委員","kind":"質問・要望","question":"とりわけマンションの耐震化の促進を求める質問です。平成２３年度当時の旧耐震のマンションの棟数、どこまで進捗が進んでいるかというところを知りたいので、ぜひ教えてほしいと求めました。","respondent":"鈴木建築課長","answer":"それから、大規模マンションの賃貸と分譲を分けて見ますと、賃貸マンションが６６５棟、耐震化率が９６.１％。分譲マンションが９９８棟ございまして、耐震化率が９３.７％というような状況です。","id":"exchange-126"},{"speaker":"南委員","kind":"質問","question":"９５％前後、分譲と賃貸と、そういう形、９４.６％なのですが、まだ０.４％分耐震が済んでいないところがあるというふうに考えていいのですか。その辺を明らかにしていただいて、区の考え方、どういうふうにそこを進めようとしているのか、その辺についても伺います。","respondent":"鈴木建築課長","answer":"どういった対応ですが、助成制度の説明も含めて、直接フェイス・トゥ・フェイスのやりとりを行ってあります。そういったところを総合的に行いながら、マンションの耐震化についても進めてまいりたいです。","id":"exchange-127"},{"speaker":"南委員","kind":"質問・要望","question":"現在残っている棟数を知りたいところなので、さっき伺ったつもりですけれども、教えてほしいと求めました。ですから、その点の区の見解を伺いたいのと、本当に自分だけの問題ではないというところの認識をしっかり持っていただくことが大事だと思うのです。","respondent":"鈴木建築課長","answer":"その説明の中で、これは一義的には一番重要なところでご説明するわけですけれども、やはり輸送道路の確保という広域的な観点もあります。そうした説明もしっかり行いながら、事業を確実に進めていきたいです。","id":"exchange-128"},{"speaker":"南委員","kind":"質問・要望","question":"もう１つ、そういうことで派遣をして訪問をしているのだけれども、賃貸の部分ももちろん同様にやっていらっしゃるという理解でいいのですか。そういう点での年次計画をしっかり立てていただきたい、この点もお願いをしておきたいと思いますので、考え方を伺いたいと思います。","respondent":"鈴木建築課長、稲田都市開発課長","answer":"所有者の方がお貸しになっている方々に対して、区分所有の方々もなかなか難しいところはありますが、そういったところが１つ課題かというところです。私からは、八潮のまちづくりの検討についてお答えします。その後、自治会長等々に話に行けたらというところで現時点では考えております。","id":"exchange-129"},{"speaker":"南委員","kind":"質問・要望","question":"ぜひ進めてほしいと求めました。八潮の再生計画ですけれども、ぜひこれは本当に時間を早めてやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-130"},{"speaker":"こんの委員","kind":"質問・要望","question":"各進捗状況を確認させていただきたいということと、１７５ページの区営住宅管理費から、エレベーター設置の可能性についてお伺いしたいと思います。５階建てのところは、まだ５階建てのところは何軒か残っているのですが、その辺りを教えてほしいと求めました。","respondent":"桑波田交通安全担当課長、稲田都市開発課長","answer":"４月には地下機械式も大森の水神公園内にできましたし、また、そういった用地等も確保しながら駐輪場の整備を進めているところです。現状ですが、去年ですと年に５回ほど開催していますが、まだどういう方向でまちづくりを進めるかというところの段階です。ただ、先ほど言いましたような状況ですので、まだ今後どうするかは決まっておりません。","id":"exchange-131"},{"speaker":"こんの委員","kind":"質問・要望","question":"こういう考え方はどうなのでしょうかというところなのですけれども、いわゆる区の区分所有というところで、駐輪場を確保できるような。日陰、日影の関係でという理由でしたけれども、南大井六丁目、五丁目と同じように、耐震化が必要な年数なのではないか尋ねました。","respondent":"稲田都市開発課長、長尾住宅課長","answer":"大井町のまちづくりの中で駐輪場等の区分所有等を考えられないかですが、例えば、このＥ地区におきましては、現状、区の駐輪場等もあります。区営住宅につきましては、耐震化自体は全て完了しております。","id":"exchange-132"},{"speaker":"こんの委員","kind":"質問・要望","question":"耐震化は済んでいるということですけれども、そうすると、増築の話とか日影の話とかというのが、あまりご答弁としてあれなので、またの機会に質問させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-133"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"だから、ぜひ支援してほしいと言われたけれども、この子が１９日のセレモニーにも来ると聞きました。有料でもいいではないか尋ねました。","respondent":"溝口公園課長","answer":"今後、やはりオリンピック・パラリンピック、１つ、スポーツの祭典としての行事が大きく迫っています。そういったものと連携して、そういったところと連携しながら、さらにスポーツ振興に取り組んでいきたいと考えているものです。","id":"exchange-134"},{"speaker":"石田（秀）委員","kind":"意見","question":"だけれども、私は基本的に水族館はしっかり観光の核として残していくべきだと思っています。は、これからどういう展開をしていくのだというところを、そういう部分でどうお考えなのかということの説明を求めました。","respondent":"溝口公園課長","answer":"しながわ区民公園の南側ゾーンの改修も予定しております。は入館者数の向上に向けて、公園、水族館一体となって取り組んでいきたいと考えているものです。","id":"exchange-135"},{"speaker":"石田（秀）委員","kind":"意見","question":"ぜひよろしくお願いします。やり方の方法はいろいろな形があると思うので、それに向けて強化をしていただいて、よりよい水族館にしてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-136"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/392487?Template=document&Id=1444#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":115755,"voices":334}},{"id":"h29-20171011-4","meetingId":"h29-c-settlement","date":"2017年10月11日","dateIso":"2017-10-11","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時１９分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を143件整理しています。","topics":[{"id":"topic-01","title":"◯鈴木（真）委員長 ただいまより、決算特別委員会を開会いたします。 それでは、平成２８年度品川区一般会計歳入歳出決算","agenda":"◯鈴木（真）委員長 ただいまより、決算特別委員会を開会いたします。 それでは、平成２８年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"横山委員","kind":"質問","question":"より正確に自分の気持ちを表現し、国語も英語も語彙を増やしてほしいと考えていますが、区のお考えと現在の指導方法を教えてください。品川区においては英語教育における対話力とレジリエンスについて、どのように指導しておりますか尋ねました。","respondent":"熊谷指導課長、大関教育総合支援センター長","answer":"今、品川区立学校教育要領の改訂を進めているところですけれども、次の教育要領に取り入れていきたいということで検討を進めているところです。自分自身の考え方について修正を行い、次にまたチャレンジしていこう、そういったことが生き抜く力を育てていくというふうに考えております。３番目にご質問がございましたスピーチ、子どもたちが説明したり発表したりする、そうした言語活動を大切にした授業展開を行っているところです。","id":"exchange-001"},{"speaker":"横山委員","kind":"質問・要望","question":"教員の質の向上についてもお伺いいたします。品川の英語教育を進めていただくために、英語教員の質の向上を要望いたしますが、ご見解をお伺いします。","respondent":"熊谷指導課長","answer":"ＪＴＥも含めて私どもで対応している英語科の専門教員、日本人の教員がおりますけれども、それも含めて研修を行っているところです。聞くこと、特に話すこと、聞くことを重視した英語教育に変わってきていることが２７歳から３８歳の世代との大きな違いとなっていると思います。","id":"exchange-002"},{"speaker":"横山委員","kind":"質問・要望","question":"イングリッシュキャンプについてお伺いいたします。対象が５、６年生からということや、品川区では利用していくお考えなのかどうかの説明を求めました。","respondent":"熊谷指導課長","answer":"今年度も福島県のブリティッシュヒルズでイングリッシュキャンプを実施したところです。実はＴＧＧにつきましては４年生でも可というふうに聞いておりますので、来年度検討をしていきたいと考えているところです。","id":"exchange-003"},{"speaker":"横山委員","kind":"質問・要望","question":"こちらは要望です。平成２７年度に冊子ができたかと思うのですが、現在の状況や効果などが何かありましたらお願いいたします。","respondent":"品川庶務課長","answer":"家庭教育ブックですが、心身の発達等を考慮して３種類の家庭教育力チェックシート、家庭教育ブックを作成しております。今年度、家庭訪問等で生徒・児童等に渡して活用をしています。","id":"exchange-004"},{"speaker":"新妻委員","kind":"質問・要望","question":"１７９ページ、１７８ページ、ＳＮＳによる相談についてお伺いをいたします。徴収方法や、滞納者がいるのかどうかお伺いをいたします。","respondent":"有馬学務課長","answer":"徴収方法につきましては、月毎にまとめて、今は入学のときに口座振替をお願いしておりまして、基本的には口座引き落としの形で対応しています。","id":"exchange-005"},{"speaker":"新妻委員","kind":"質問・要望","question":"滞納されているケースも考えられますので、ご家庭の状況をよく確認をしていただきながらしっかり対応してほしいと求めました。このアンケートの内容を教えてほしいと求めました。","respondent":"有馬学務課長","answer":"これは、中学校のほうで完全給食の実施率というのがまだ８０％前後ということで、まずはこれを９０％に持っていこうということが背景にはあります。","id":"exchange-006"},{"speaker":"新妻委員","kind":"提案","question":"この目的は、そして課題を捉えて見える化をしていく、それからメリットがどこにあるのかということも確認をしていく中で。この給食費の無償化に関しての品川区の見解として、無償化ということに対してどう捉えているか、お伺いをしたいと思いますとの意見を述べました。","respondent":"有馬学務課長","answer":"それから就学援助や多子家庭については、ただちに無償化に対してどうかというところの判断は難しいのかなと考えています。財源も相当かかりますので、これについては財源がしっかりつかないと難しいことではないかというふうに今のところ考えております。","id":"exchange-007"},{"speaker":"新妻委員","kind":"質問・要望","question":"続きまして、がん教育について伺います。この日野学園で開催をされましたその経緯といきさつなど日野学園の状況を教えてほしいと求めました。","respondent":"大関教育総合支援センター長","answer":"８年生を対象といたしまして実際に外部講師として医療従事者、病院の先生をお呼びして、がんに関して教育を行いました。これは品川区の教育会の体育部会の養護教諭を中心とした研究の中で、まずはやってみようという経緯の中で、日野学園で実施をしたような状況です。","id":"exchange-008"},{"speaker":"新妻委員","kind":"質問・要望","question":"非常にどうやって言ったら、話したら伝わるのだろうかという、講師の方も緊張しながら臨まれたがん教育であったと思います。１つ確認をしたいのですが、学校の中には養護教諭、この保健室の先生ががん教育にどのようにかかわったのか教えてほしいと求めました。","respondent":"大関教育総合支援センター長","answer":"今回の場合にはがんについて正しく理解をさせる、それから健康と命の大切さについて主体的に考えられるという２点を狙いとして取り組みました。そういった狙いを講師の先生にお伝えを直接したりするなど連絡調整等も養護教諭が担いました。","id":"exchange-009"},{"speaker":"新妻委員","kind":"質問","question":"１点気になったことがありまして、この授業を受ける中で、生徒たちが筆記用具を持っていなかったのではないかなと思うのです。こういう授業の場合というのは、こういう形が普通なのか、たまたまそのときは筆記用具がなかったのかの説明を求めました。","respondent":"大関教育総合支援センター長","answer":"筆記用具を持たせてしまうとメモをしてしまいがちですので、お話に集中できないということで意図的にその時間はメモをとらせず、後から感想やアンケートを書かせる形で振り返りの学習を行いました。","id":"exchange-010"},{"speaker":"新妻委員","kind":"質問・要望","question":"アンケートも非常に大事だと思います。今後、平成２９年度、これから品川区が目指すがん教育と今、次の流れが決まっているところがあれば教えてほしいと求めました。","respondent":"大関教育総合支援センター長","answer":"直接、その大変さを考えた生徒もおりましたし、あるいは生活習慣という部分が非常に大切だということを理解できた生徒もいました。ですので、今回１回目で学校現場からは課題として出てきた部分もありますので、また今後何校か校種も変えながら検証していきたいと考えています。","id":"exchange-011"},{"speaker":"新妻委員","kind":"質問・要望","question":"最後に、ＳＮＳを活用したいじめに関する相談について伺いたいと思います。品川区における平成２８年度、昨年度のいじめ対策に関しての成果を教えてほしいと求めました。","respondent":"大関教育総合支援センター長","answer":"全校に子どもたちがいじめに関する相談をするための目安箱を設置し、さらにＨＥＡＲＴＳ「学校支援チーム」が直接子どもたちからの。なお、アイシグナルと言いまして、パソコン等から自分の相談を匿名で行うことも、中学生以上につきましては取り組んでいるところです。","id":"exchange-012"},{"speaker":"中塚委員","kind":"質問","question":"１７９ページの教育総合支援センター運営費にかかわって、今回はカミングアウトとアウティングについて伺いたいと思います。これは子どもにとって悩みが深く、話しにくい苦しい気持ちがあると思うのですけれども、この点はいかがか尋ねました。","respondent":"大関教育総合支援センター長","answer":"そのことによって子どもたち、あるいは家庭から相談があったときに適切な対応をまずは受けとめることが重要と考えております。個別の内容につきましては非常に取り扱いが難しいものだと教育総合支援センターでは考えておりますが、丁寧にまずは受けとめる。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問","question":"多くが「誰にも話していない」か「ごく少数のみ」で、カミングアウトした人であっても相手は同級生が７割で担任の先生や保健の先生は１割ほどです。","respondent":"大関教育総合支援センター長","answer":"はいろいろな実態があるのだ、性に関する認識という部分は多様な考え方もあるのだという部分を、まずはいろいろな人権ということで。その中では、子どもたちにまずいろいろな考え方があるのだということに気づかせることから取り組んでいるところです。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"いろいろと取り組みも始まっているかと思いますけれども、ぜひ進めていただきたいと考えています。カミングアウトされた同級生や先生などへのサポートがそれぞれ必要だと思いますが、現状と今後の取り組みについて伺いたいと思います。","respondent":"大関教育総合支援センター長","answer":"生徒あるいは保護者から相談を受けた際に、教員が正しい理解をしておくという部分はまず前提として大切だと考えております。実際にＱ＆Ａの形で、このような問い合わせがあった場合はどういうふうに対応すべきかという部分も具体的に示しながら、研修を進めているところです。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問","question":"これまで秘密にしていた自分の性のありようを表明する段階は２段階あると伺いました。思春期を迎える小・中学校では、子どもたちが学校であらかじめ学ぶ機会が必要だと思いますけれども、現状についてお伺いします。","respondent":"大関教育総合支援センター長","answer":"例えばリーフレットなどで、相談の窓口はいろいろあるよという案内を、各学校では子どもたちに対して周知しています。その中の１つで、違いをきちんと認め合おう、認識しようという取り組みを市民科の中で行っているところです。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問","question":"そのカミングアウトの前にやはり自分のセクシュアリティについて悩んでいたり戸惑っていたり混乱しているときは気持ちの整理も必要ですから。","respondent":"島袋人権啓発課長、大関教育総合支援センター長","answer":"今のところカウンセリング相談で対応しておりますが、年代的に統計を見ますと２０歳以上の方が大多数を占めております。例えば夏休みに入る前など、そういった機会をある程度一定の時期ごとに家庭、そして子どもに配布をしているところです。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"学校の廊下や保健室など子どもたちが自由に見たり持って帰ったりできるようにしてほしいと求めましたけれども、この点はいかがでしょうか。現在は４校だと伺っておりますけれども、全校に配置を広げてほしいと求めましたが、この点についてはいかがか尋ねました。","respondent":"大関教育総合支援センター長、横山品川図書館長","answer":"よりそいホットラインにつきまして、相談窓口一覧の中に載せるかどうかにつきましては、さまざまな反応等もあろうかと思いますので、色々な状況等も考えながら検討していきたいと考えます。学校図書館の蔵書につきましても、各学校で選択をしているところでありますが、人権の中の１分野として資料を置かせていただくように配置してまいりたいと思います。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"市民科の中で取り扱いを検討したいと答弁がありましたけれども、どこまで検討が進んだのかお伺いしたいと思います。このＮＰＯ法人ＲｅＢｉｔの研修も活用してほしいと求めましたが、この点はいかがか尋ねました。","respondent":"大関教育総合支援センター長、島袋人権啓発課長","answer":"先ほどご案内いたしましたとおり５年生の段階で「大切なこと」を活用してさまざまな考え方があるという部分は全校児童に投げかけております。は区職員、教職員も含めた研修ですが、ＬＧＢＴに関する理解を正しく浸透させることが大事かと考えております。","id":"exchange-019"},{"speaker":"松永委員","kind":"質問","question":"初めに成果報告書の１７８ページのクラブ・部活動指導費について伺います。次にこのクラブ・部活動はどのような方々が指導していて、そして１つのクラブまたは１つの部に対して何人体制で行われているのか伺います。","respondent":"有馬学務課長、大関教育総合支援センター長","answer":"それで基本的には、各学校での対応ですのでそれほど人数が多くありません。ばらばらですので、それほど１つの学校のクラブで何人もいるということではなくて、基本的には１つのクラブで１人いるというのが現状です。その教員以外に、今学務課長より申し上げましたように、外部指導員に講師をお願いをしている実態があります。","id":"exchange-020"},{"speaker":"松永委員","kind":"質問","question":"先ほど質問をいたしました、クラブと部活動の違いについてお願いします。","respondent":"大関教育総合支援センター長","answer":"小学生の場合にはクラブ活動として行っております。中学生は部活動として、これは学習を終えた後の放課後等に行っている一般的な部活動をイメージしていただければと思います。","id":"exchange-021"},{"speaker":"松永委員","kind":"質問","question":"それから、外部指導員の方が３７名ということなのですけれども、１人当たりの費用は大体どのくらいなのですか。時給換算にするとどのくらいの金額になるのかも、合わせて伺いたいと思います。","respondent":"有馬学務課長、大関教育総合支援センター長","answer":"基本的には昨年度が１,３９６回でしたけれども、その前の年は１,５７５回あったです。単価は外部指導員につきましては１回４,０００円ということで対応をしています。先ほど３７人と申し上げましたのは運動系の部活動でございまして、それ以外に文化系の部活動では延べ３４人の方にご協力いただいているところです。","id":"exchange-022"},{"speaker":"松永委員","kind":"質問","question":"１回につき約４,０００円ということで、例えば夏休みなどの部活動で１回指導すると４,０００円という形になるのでしょうか。時間に換算すると、ちょっとそれではどうかなとは思うのですけれども、その辺について伺いたいと思います。","respondent":"有馬学務課長","answer":"基本的にはこの外部指導員について、現状の取り決めでは１回４,０００円ですので、２時間の場合もありますし４時間の場合もあるとは思いますけれども、その全額で対応しています。","id":"exchange-023"},{"speaker":"松永委員","kind":"質問","question":"次にクラブまたは部活動の指導について伺いたいと思います。そこで今年度、本区において部活動や授業中などにこうした体罰事例があったのかを伺いたいと思います。","respondent":"熊谷指導課長","answer":"昨年度の体罰の実態把握の調査結果ですけれども、品川区におきましては０件です。ですので、全く体罰にあたる案件はございませんでした。","id":"exchange-024"},{"speaker":"松永委員","kind":"質問・要望","question":"ただ、こうした事例はいつ起こるかわかりませんので、しっかりと子どもたちの健全育成に取り組んでほしいと求めました。質問いたしますが、生徒からいじめられていると言われた場合、どのような対応をされているのかお伺いします。","respondent":"大関教育総合支援センター長","answer":"万が一あった場合に、考え方といたしまして、あるいは学校が組織的に未然に防ぐ対応ができているのかという部分を考える必要があろうかと思います。ただ、子どもへの対応という部分も丁寧に行っておりますので、本区においては発生件数も少なくなってあります。","id":"exchange-025"},{"speaker":"松永委員","kind":"質問","question":"ここで教育委員会に伺いたいと思うのですけれども、もしこういうことが起こった場合に、教師としてこういう対応が正しかったのかを改めて伺いたいと思います。","respondent":"大関教育総合支援センター長","answer":"授業中にスマートフォンで教員の様子を撮影しているという時点で、まず授業が成立していない状況かと思います。そこに至る前の段階で、そういったいわゆる学級崩壊のような形にならないよう取り組んでいきますし、教育委員会としても指導・支援してまいります。","id":"exchange-026"},{"speaker":"松永委員","kind":"質問・要望","question":"時間がなくなりましたので、１８９ページの結核検診について質問いたします。例えば保健センター、医師会検査センターを利用してＱＦＴ検査の採血を集約して実施してみてはどうですか、区のお考えの説明を求めました。","respondent":"有馬学務課長","answer":"夏休み中に本国に１回帰ってしまうなど、やはり言葉の壁なども含めて、いろいろ背景はあると思います。","id":"exchange-027"},{"speaker":"須貝委員","kind":"質問","question":"私は１７８ページ、教育指導費についてお伺いいたします。これに対してどう思われるかもの説明を求めました。","respondent":"有馬学務課長","answer":"ですので、極端に格差が広がったというふうには考えておりません。平成２７年度から平成２９年度を見ますと、そう問題視するような格差が広がっているというふうには今のところ認識はしていないです。","id":"exchange-028"},{"speaker":"須貝委員","kind":"質問・要望","question":"学校選択、自由ですから皆さんに任せている。私は教育委員会に求められていると思いますが、もう一度ご見解の説明を求めました。","respondent":"有馬学務課長","answer":"学校間で切磋琢磨してレベルアップを図っていこうというのが１つの狙いですので、それが基本であるということはまず押さえておきたいと思います。大体今で言うと、平成２９年度は７７％ぐらいを占めているというような、そういった実態もあるです。","id":"exchange-029"},{"speaker":"須貝委員","kind":"質問・要望","question":"ではどうするのですか。これも大きな問題ではないか尋ねました。","respondent":"有馬学務課長","answer":"そうは言いつつ、そういう状況の中においてでも、８５～８６％の方については希望がかなっているというようなことも一方です。それから、学事制度審議会の中でもその辺の問題については検討はしていただいているところです。","id":"exchange-030"},{"speaker":"須貝委員","kind":"質問","question":"ですから、その辺は考えてほしい。でも現実こういうふうな状況に対して、どのようにお考えか尋ねました。","respondent":"有馬学務課長","answer":"３.１１以降の防災の面、地域との結びつきも考えながら学校を選択してくださいというような文面を入れて、学校選択制を行っているところです。ということで、必ずどちらか選べるというようなことは最低でも残していく必要は絶対にあるだろうというふうに思っています。","id":"exchange-031"},{"speaker":"須貝委員","kind":"質問・要望","question":"ではその学校はどうなったのですか。最後に一言お願いいたします。","respondent":"有馬学務課長、熊谷指導課長","answer":"その意識の高まりによって、それが子どもたちにも伝わっていっているということになっていると思います。ということで、教員の意識が子どもにも伝わっているということではないかというふうに考えております。昨年度からスタートした品川教育ルネサンスの中の大きな柱の１つに、地域とともにある学校づくり、コミュニティ・スクールがあります。","id":"exchange-032"},{"speaker":"田中委員","kind":"質問","question":"１７８ページ、１項教育総務費３目教育指導費、いじめ等防止プログラム経費について伺います。給食食材放射性物質検査費について伺います。","respondent":"有馬学務課長","answer":"給食食材の放射性物質の検査につきましてですが、次年度につきましてはまだこれからということで、予算編成についてこれから検討していく形になります。","id":"exchange-033"},{"speaker":"田中委員","kind":"質問・要望","question":"今後も区はその範を示すために給食の放射能検査を継続することを強く求めます。監査で指摘を受けた学校だと思いますが、その措置報告のとおり、指摘された点が改善されたというのはどこが確認をしているのか尋ねました。","respondent":"品川庶務課長","answer":"それから各学校につきましては、指導主事等が訪問をしています。その訪問の時点で直接理科室を見て確認をするというような業務を行っております。","id":"exchange-034"},{"speaker":"田中委員","kind":"確認","question":"校長連絡会に指示を出して、その後職員などにより全校の状況の確認をとることができたということか尋ねました。","respondent":"品川庶務課長、大関教育総合支援センター長","answer":"そこに指示が行き、そして理科準備室のほうを再度点検を行い、整理をしているところです。その後、定期的に指導主事が学校を回っておりますので、その段階で確認をしているというような状況です。理科準備室が確実に鍵がかかっているか、大方の学校は今回ご指摘がございましたことについてしっかりとできております。そういった部分の確認もして、徹底していますので、ご安心ください。","id":"exchange-035"},{"speaker":"田中委員","kind":"確認","question":"ではなぜ２０１６年にまた毒物・劇物管理で監査報告が出てしまったのかということを聞きたいです。２０１５年のときにきちんと監査報告が他の学校でも共有されて確認されるべきだったと思いますが、そのことを伺います。","respondent":"品川庶務課長","answer":"これはまさに委員のおっしゃるとおりで、学校の監査というのは毎年大体１０校弱の学校を定期的に監査をしております。こういう点につきましては、教育委員会としても徹底して指導をしていきたいと、このように考えております。","id":"exchange-036"},{"speaker":"田中委員","kind":"質問","question":"この事業をこれからも継続してほしいという立場で質問をします。子どもたちと大人に向けたＣＡＰプログラムの導入の目的をどのように区は捉えているのか伺います。","respondent":"大関教育総合支援センター長","answer":"やめてと言える、あるいは誰かに相談できるという部分を実際に団体の方のご協力を得てロールプレイ等を通じて子どもたちに学ばせてきたところです。これはやはり子どもたちのいじめ、虐待、性被害に遭わないための対処法の１つとしてこれまでも取り組んできたところです。","id":"exchange-037"},{"speaker":"田中委員","kind":"質問","question":"しかし、このＣＡＰの授業が２０１６年から縮小されていると伺いました。ＣＡＰの縮小について子どもたちや保護者に意見を聞く機会はあったのか伺います。","respondent":"大関教育総合支援センター長","answer":"その間、いじめ対応につきまして学校の取り組みもさまざま変化してきてあります。自分たちが話し合う、児童・生徒会役員が各校の取り組みについて情報交換をする、そのような取り組みを充実させているところです。","id":"exchange-038"},{"speaker":"田中委員","kind":"質問","question":"ＣＡＰの授業の継続を望みますが、見解を伺います。子どもたちの命を守っていくためにも、ＣＡＰプログラムの今後の方針をお知らせください。","respondent":"大関教育総合支援センター長","answer":"子どもたちの発達段階も踏まえながら、そのとき何が最も効果的であるかを十分学校と共通理解を図りながら、今後もＣＡＰにつきましては適切な学年で実施してまいりたいと考えます。","id":"exchange-039"},{"speaker":"田中委員","kind":"確認","question":"確か以前の答弁では、教員への発達障害の研修を行っていると伺っていました。しかし、教員等の研修計画を確認しましたが、普通学級の教員向け研修において読み取ることができませんでした。","respondent":"大関教育総合支援センター長","answer":"そのほか特別支援教育研修会といたしまして、各校の特別支援コーディネーターを複数指名していますが、そちらが参加する内容を研修会でも扱い。","id":"exchange-040"},{"speaker":"田中委員","kind":"質問・要望","question":"それぞれに合った対応で接し、発達障害を持つ子どもが孤立せずに済み、多様性を認め合える環境をつくってほしいです。発達障害、そしてＬＧＢＴなど多様性への理解が広がる、学べる場の提供を区へ強く要望したいのですが、区の見解を伺います。","respondent":"大関教育総合支援センター長","answer":"人権同和教育研修会の中において、さまざまな人権課題の１つとしてＬＧＢＴについても各校の担当教員に対して指導しています。そういったものを通じてＬＧＢＴについて相談のあった場合に適切な対応をするよう全ての学校に対して求めている、そのように扱ってあります。","id":"exchange-041"},{"speaker":"田中委員","kind":"質問","question":"その校長研修会でＬＧＢＴや発達障害について学んだ後に、きちんと教員へその研修内容が受け継がれているのかなども伺いたいと思います。今後のためにもぜひの説明を求めました。","respondent":"大関教育総合支援センター長","answer":"例えば校長研修会で伝達した内容につきましては、全ての校長は各学校で職員連絡会議、あるいは打ち合わせの場面などを通じて周知はしています。","id":"exchange-042"},{"speaker":"田中委員","kind":"質問・要望","question":"今回の人工芝生化は学校や学校に通う子どもたち、そして地域の要望を受け実現したものなのでしょうか。どのような経緯から人工芝生化に至ったのか伺います。","respondent":"品川庶務課長","answer":"近隣に対する砂ぼこりの対応というのは人工芝にすることによってかなり違ってきております。それから静電気等のお話がありましたが、水等をまいて対応するというようなことも対応策としています。","id":"exchange-043"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"町会等行事参加カードについて、その事業についてご質問をさせてほしいと求めました。スタンプを押していくということで、この事業の現況と、どの程度の町会・自治会が助成金を受けて今現在取り組んでいるのかの説明を求めました。","respondent":"品川庶務課長","answer":"行事参加カード事業ですが、今年から、委員お話しのように１年生から６年生まで全てカードを配布しまして、事業を進めているところです。それから今年度につきましては、これも９月１日現在なのですけれども、１５町会に配布をしているというような状況になります。","id":"exchange-044"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"例えば、荏原第四地区には１４町会あるのですが、児童が行事参加カードを持参して来た町会というのは１町会程度ということをお聞きしております。こういうカードをつくったのですから、改めて学校の先生のほうからも、保護者に対して啓発もやってほしいと求めました。","respondent":"品川庶務課長","answer":"ほぼ毎年のように１３地区の町会長会議に参加いたしまして、毎年内容変更がありましたので、その説明ということでお話をしているものです。今年度、このような点を十分踏まえまして、来年度に向けて現在のところ大きく見直しをかけているような状況です。","id":"exchange-045"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"続きまして１７９ページ、まちの人々に学ぶ事業経費のご質問をさせていただきたいと考えています。今後どういうふうに市民科における、外部講師を招いた授業を進めていく予定なのか、改めての説明を求めました。","respondent":"大関教育総合支援センター長","answer":"あるいはそれ以外に税に関する作文、あるいは標語などの取り組みについては、全ての学校で現在実施しています。各学校の状況も踏まえながら関係団体の方からもアドバイスをいただきながら、今後検討してまいりたいと思います。","id":"exchange-046"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"続きまして１８５ページ、学校環境整備事業に関連した質問をします。そして子どもたちのためにもやはりこれは生き物が生息しているわけですから、近隣に対しての配慮というか取り組みを改めてお聞きしたいと思います。","respondent":"品川庶務課長","answer":"学校の近隣に対する配慮ですが、基本的には近隣からいろいろなご要望があれば、学校としてもできる限り対応をしていきたいというスタンスです。","id":"exchange-047"},{"speaker":"あくつ委員","kind":"質問","question":"２点目は品川区の教育ということで、ＳＤＧｓと教育について伺ってまいります。時間があれば１８２ページ、人権尊重教育推進経費に関連いたしまして、アール・ブリュット展の子どもたちの鑑賞について伺います。","respondent":"大関教育総合支援センター長","answer":"次年度におきましても何校か子どもたちに、そういったことを研究してまいりたいというふうに考えているところです。情報収集も含めて、プログラミング教育は何年生でどのような単元を全校で行うべきかなどについても現在検討を進めているところです。","id":"exchange-048"},{"speaker":"あくつ委員","kind":"質問","question":"伺いたいのが、今どのようにお考えになって、どのように対応をされているのか。もしかしたら今置かれているのかもしれないというところで、現状と今後どういうふうにされていくのか、お考えの説明を求めました。","respondent":"大関教育総合支援センター長","answer":"今後、それを待ってということではなくて、市民科の中ではまずどのようにやろうかという部分も現在検討を進めている最中です。単元を考える際に、プログラミング教育という視点も今後の研究の１つのテーマになっていこうかと考えています。","id":"exchange-049"},{"speaker":"あくつ委員","kind":"質問・要望","question":"これは今、しっかりと見守っていかなければいけないということは、今後もまた議会質問等を通して確認をさせていただきたいと考えています。","respondent":"大関教育総合支援センター長","answer":"そういった内容を５年生の子どもたちが環境保護の観点も持ちながら学ぶような学習がございました。そういった学校裁量の市民科の学習の時間を現在新学習指導要領に基づいて品川区の教育要領のほうでは増やす方向で検討を進めているところです。","id":"exchange-050"},{"speaker":"あくつ委員","kind":"質問・要望","question":"加盟をしない理由、ぜひ教えてほしいと求めました。先ほどもご答弁ありましたけれども、品川区としては既に行っているという認識でいるのか、それについての説明を求めました。","respondent":"大関教育総合支援センター長","answer":"現在、そういったものを具体的に子どもたちが学んでいるところですので、特に加盟をしないということで考えているわけではございません。学校のほうで申請がある場合には、教育委員会としても応援してまいりたいと考えております。","id":"exchange-051"},{"speaker":"あくつ委員","kind":"質問","question":"伺いたいのが、「なるべく早い時期に情報提供をしていく」と、各学校にですね。教育委員会でアール・ブリュット展をごらんになった方がいるかどうか、子どもたちが鑑賞したのかどうか、その反応はどうかの説明を求めました。","respondent":"大関教育総合支援センター長","answer":"教育委員会といたしましてもアール・ブリュット展については話題とさせていただきまして、またその後の感想等については聞きたいと考えています。","id":"exchange-052"},{"speaker":"安藤委員","kind":"質問","question":"１８３ページ、図書館経費、１８５ページ、御殿山小学校西側敷地図書館建設工事費負担金および大崎図書館について伺います。解体後の跡地活用について、区は補助２９号線とする考えなのかどうか伺いたいと思います。","respondent":"柏原企画調整課長","answer":"その後ですけれども、道路の関係で協力をと、東京都のほうからそういったお話もあります。そういったところに活用できるかについては考えているといったところです。","id":"exchange-053"},{"speaker":"安藤委員","kind":"質問","question":"ゆたか図書館は老朽化を理由に改修、大崎図書館は改修も建てかえられもせずに移転・廃館とはどう考えてもおかしいのではないでしょうか。そういう検証をしたのですかどうか伺いたいと思います。","respondent":"横山品川図書館長","answer":"老朽化がひどく、またビジネス支援図書館としても機能しておりました大崎図書館につきましては、産業支援交流施設ＳＨＩＰの開設によりまして。","id":"exchange-054"},{"speaker":"安藤委員","kind":"質問","question":"それと、私が聞いたのは、今、建てかえは可能だという意味なのですか。技術的に建てかえは不可能なのですか、また、そういう検証をしっかりしたのですかということを伺ったので、答えるよう求めました。","respondent":"横山品川図書館長","answer":"１つ１つの工事を積み上げた結果、移転のほうが合理的だと判断しています。繰り返しになりますが、決定は区全体でしています。","id":"exchange-055"},{"speaker":"安藤委員","kind":"質問","question":"伺いたいと思います。それと、現地での建てかえできるというならば、移転ではなく現地での建てかえを検討すべきだと思いますけれども、いかがか尋ねました。","respondent":"横山品川図書館長","answer":"そういう意味では現地での建てかえというのを検討するのも１つの方策ではありますが、そことの連携を考えますと近接の地にあることが合理的です。そういう意味では、図書館を立ち上げた皆さんの思いもくんだ形で実現できたものと承知しております。","id":"exchange-056"},{"speaker":"安藤委員","kind":"質問・要望","question":"くむと言うのであれば現地での建てかえを強く求めたいと思います。ぜひ判断を変えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"本多委員","kind":"質問・要望","question":"どうなのですかと言われるので、その方たちはやはり御殿山は遠くて困る。その区の考え方と、あと移転、図書館が移転になりますというもともとの経緯とを説明するのが、区政運営に求められている事だと思うのです。","respondent":"横山品川図書館長","answer":"ビジネス支援の事業などを展開しているということを含めまして、地域に愛される図書館として進めていきたいということを、地域の皆様に丁寧にご説明に回るつもりでおります。","id":"exchange-058"},{"speaker":"筒井委員","kind":"質問","question":"１８１ページの品川英語力向上推進プラン、１８２ページ、帰国児童・生徒等支援費についてお伺いをいたします。そして、なぜ品川図書館に設置したのかという理由をお知らせください。","respondent":"横山品川図書館長","answer":"品川図書館での検証を経て、各館に導入を拡充させていく予定です。４９２万１,３４４円のうち、２カ月に一度メンテナンスを行いますので、それとＬＡＮの配線経費で３４万８,８４０円という内訳になってあります。","id":"exchange-059"},{"speaker":"筒井委員","kind":"質問・要望","question":"ですから、そして飽きずに図書館に来ていただいた方に利用していただく取り組みというのをぜひしていただきたいのですけれども、いかがか尋ねました。","respondent":"横山品川図書館長","answer":"今、お知らせにつきましては、使い勝手について改良の余地がございまして、更新が月に２回しかできないような制約がありますので、これをリアルタイムに更新できるような形にできないかというようなところで改良を重ねてまいるつもりでおります。","id":"exchange-060"},{"speaker":"筒井委員","kind":"質問","question":"ぜひともそうした工夫、仕組みづくり、よろしくお願い申し上げます。このデジタルサイネージを今は区役所の庁舎と品川図書館に設置していると思いますけれども、今後拡大のご予定というのはあるのか尋ねました。","respondent":"横山品川図書館長、中元広報広聴課長","answer":"品川図書館での検証と改良の状況を見まして、各図書館に拡充していきたいと考えています。広報広聴課のほうでもデジタルサイネージについて、今システムの構築を今年度予算で行っているところです。","id":"exchange-061"},{"speaker":"筒井委員","kind":"質問・要望","question":"１年生から６年生の英語科、英語のペーパーテストの成績というのは、成績向上が見られているのでしょうか。すなわち他区や他県と比べて品川区の英語力は高まっているのか、そうしたことをお伺いします。","respondent":"熊谷指導課長","answer":"平成１８年度から１年生からの英語教育を行ってまいりました。１年生からやってきた子どもが９年生になった平成２８年１２月１日、昨年度、文部科学省が英語教育実施状況調査というものを行いました。","id":"exchange-062"},{"speaker":"筒井委員","kind":"質問","question":"２３区ではどのぐらいの順位なのかということと、またこの英語力向上推進プランに当たって課題もあるかと思うのですけれども、課題は何かということと、あわせてその対策としてどういったことをお考えか尋ねました。","respondent":"熊谷指導課長","answer":"残念ながら２３区の中でどのぐらいの位置かということにつきましては、私どものほうで把握しておりません。いわゆるコミュニケーションの部分、対話の部分、そういったところを児童・生徒に今後一層つけていきたいというふうに考えているところです。","id":"exchange-063"},{"speaker":"筒井委員","kind":"質問・要望","question":"３７.９％というのは大変すばらしい数字だと思いますし、ぜひコミュニケーションの部分についても力を入れていっていただきたいと考えております。品川区の英語教育において、一般の生徒との兼ね合いというか、関係性というのはどうなっているのでしょうかお伺いいたします。","respondent":"大関教育総合支援センター長","answer":"国別では一番多いのが中国、その次がフィリピン、韓国、インドネシア、ネパールという状況で、その次にアメリカが出てまいります。","id":"exchange-064"},{"speaker":"鈴木（博）委員","kind":"質問","question":"１８８ページの３目学校給食費に関連して、１８９ページの４目学校保健費に関連して、性教育についてお尋ねいたします。不登校などにＨＥＡＲＴＳがかかわったことによる具体的な成果などはいかがか尋ねました。","respondent":"大関教育総合支援センター長","answer":"例えば不登校の子どもへの対応においてですが、そういったことで本人の直接の支援だけではなくて、家族支援から取り組むことによって。なお、つないだだけで終わりということではなく、定期的な見守り等をＨＥＡＲＴＳは家庭訪問を通じて行っております。","id":"exchange-065"},{"speaker":"鈴木（博）委員","kind":"質問","question":"教育心理指導員が２名、学校生活指導専門員が１名の体制のようですが、小学校の元教諭などの職種の方もいらっしゃるのでしょうか。現在の人員体制で支援活動が十分に行えるのか、若干不安になってきたのですが、増員等の計画はあるのか尋ねました。","respondent":"大関教育総合支援センター長","answer":"教育心理相談員、対応件数が増加していることに伴いまして、昨年度より教育心理相談員を１名増員して人員の拡充をしています。ＨＥＡＲＴＳの中で直接は雇用はしてございませんが、学校担当の指導主事がおりますので、指導主事とＨＥＡＲＴＳで連携して対応しております。","id":"exchange-066"},{"speaker":"鈴木（博）委員","kind":"質問","question":"次に学校のアレルギー対応についてお尋ねします。平成２８年度の小学校・中学校・義務教育学校における食物アレルギーの事故ないしニアミスの事例はあったのか尋ねました。","respondent":"有馬学務課長","answer":"平成２８年度の学校のアレルギー対応のヒヤリハット、ニアミスの件ですけれども、昨年度は小学校で３件、中学校で１件、合計４件発生しております。","id":"exchange-067"},{"speaker":"鈴木（博）委員","kind":"質問","question":"怪しいものは除去するということで、安全性を非常に重視していまして、食べられるか食べられないか２つに１つということになっています。いずれ方向転換していくと思うのですが、それに対して今、教育委員会の認識というのはいかがか尋ねました。","respondent":"有馬学務課長","answer":"該当者に卵を半分ならいいよですとか、個々にそれを対応していくということは、部分除去から今は完全除去に変えてきた経緯もあります。","id":"exchange-068"},{"speaker":"鈴木（博）委員","kind":"質問","question":"次に、性感染症予防教育についてお尋ねします。性教育の重要性について区はどのように考えているか、再度ご答弁をお願いいたします。","respondent":"大関教育総合支援センター長","answer":"その重要性をどのように受け止めているかですが、学習指導要領に位置づけられた内容であり、大切な教育活動の１つであると受け止めております。","id":"exchange-069"},{"speaker":"鈴木（博）委員","kind":"意見","question":"性感染症の症状、予防法、避妊法などについての知識の提供を段階的には行うべきだと考えます。品川区では学級担任や保健体育の教員及び養護教諭が指導しているというお話でしたが、その具体的な授業内容についてご説明くださいとの意見を述べました。","respondent":"大関教育総合支援センター長","answer":"７年生になりましたら具体的に思春期状態での生殖機能については個別具体的な内容を集団で指導する場合、適切に対応をしながら６時間行っております。","id":"exchange-070"},{"speaker":"鈴木（博）委員","kind":"提案","question":"このような公益団体が主催する研修への参加もご検討すべきではないかということはご提案します。今後も一層の性感染症予防、不幸な子どもをなくすための予防に関する教育の充実をお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-071"},{"speaker":"木村委員","kind":"質問","question":"私からは１７８ページの下から１３行目、いじめ防止対策費４,０１８万円余から質問します。いじめる側がいじめられる側に対してどのように対応していくのか、その解決策の説明を求めました。","respondent":"大関教育総合支援センター長","answer":"そしていじめの４層構造について、その対応について学校がどのように対応すべきかというお問い合わせであったかと認識しております。自分はいじめる側にも、いじめられる側にもなるかもしれないということに気づかせるような指導を、各学校でしています。","id":"exchange-072"},{"speaker":"木村委員","kind":"質問・要望","question":"そもそも特色ある教育活動経費とはどのような目的で行われている事業なのか教えてほしいと求めました。そして各学校において何らかの取り組みをしておりますけれども、各学校の生徒たちが話し合って、学校ぐるみでそういうものを決めるのか尋ねました。","respondent":"熊谷指導課長","answer":"予算執行の事務につきましては、内容に応じて所管課が行っております。こういった人物に子どもたちを育てたいといった思いが特色ある教育活動経費として申請されてきているところです。","id":"exchange-073"},{"speaker":"木村委員","kind":"質問","question":"は校長先生の趣味や考え方に偏ってしまうおそれがあろうかと思いますけれども、それでいいのでしょうか。そしてまた校長が変わるたびに事業内容も変わっていくのか、例えば１年毎に変わっていくのかについてもお聞きいたします。","respondent":"熊谷指導課長","answer":"体験授業、体験学習、どれをとり入れていくかということが継続的に行われていくようになってきております。ですので、校長が変わったら内容、取り組みが変わるということではなく、これがつながっていくという方向になってきているところです。","id":"exchange-074"},{"speaker":"木村委員","kind":"質問","question":"生徒に夢を見せるわけですから、どのようにして選考していくのか、これもお聞かせください。そして、体験授業が小学校１校となっていますけれども、どのような授業を行っているのか、これもの説明を求めました。","respondent":"熊谷指導課長","answer":"最後のご質問で、体験授業の小学校１校ではどのような授業を行ったのかというお尋ねだと思いますけれども、今年度も実施しております。陸上競技体験ですが、シドニーオリンピック男子４００メートルリレーで６位入賞した小島茂之さんを講師に短距離走の指導を受けたところです。","id":"exchange-075"},{"speaker":"木村委員","kind":"意見","question":"次に、この田植え体験学習ですけれども、田植え体験学習は立会小学校で取り組んでおりますけれども、何のための田植えの体験なのか、生徒には何を学んでほしいのか、また体験後に生徒にこのようなところが変わったなという変化があったかどうかについての説明を求めました。","respondent":"大関教育総合支援センター長","answer":"ご案内いただきました立会小学校の田植え体験学習はおよそ１０年続いております。実際に毎年５年生が立会小学校では農家の方と交流しながら実際の活動を行うことによって、例えば給食の残飯率が低くなるというような成果もあります。","id":"exchange-076"},{"speaker":"塚本委員","kind":"質問","question":"２人の問題行動をする生徒が存在するので、そういった今の学校の学級運営上でのいろいろな問題というのをどのように認識しておりますでしょうか。その原因としてどこに、どういうことがあると考えておりますか尋ねました。","respondent":"大関教育総合支援センター長","answer":"これまでもさまざまな子どもがいたところにさらに近年で言う発達障害等に関する認識が、改めてここでその対応が求められる。したがいまして、各小学校に特別支援教室を配置して対応したり、必要な学級に学習支援員を配置していただくというような対応を進めているところです。","id":"exchange-077"},{"speaker":"塚本委員","kind":"意見","question":"授業が進まない、そのときに教育委員会の方々にもご相談する中で、最初にやはり出てくるのは担任です。その意味でまずこの教員・担任の指導力強化、こういったことについてどういった対策が今されているかの説明を求めました。","respondent":"大関教育総合支援センター長","answer":"通常学級を担当している担任についても校内研修で必ず特別支援においてどのようなポイントが必要かを、学校に対する支援もしている最中です。今後とも研修とともに充実してまいりたいと考えております。","id":"exchange-078"},{"speaker":"塚本委員","kind":"質問・要望","question":"もう１つは先ほどご答弁もいただいた特別支援教室がこの平成２８年度から全国的に展開をされておりまして、その成果と言うのですか、その辺のことがどういうふうに成果として出てきているのかをお聞かせほしいと求めました。","respondent":"大関教育総合支援センター長","answer":"実は前期と後期で年２回申請を受け付けておりますが、３学期ぐらいに予定していたよりも多くの児童に対応せざると得ないという課題がございました。","id":"exchange-079"},{"speaker":"塚本委員","kind":"質問・要望","question":"これがいわゆるさっき言った学級運営等にどのような効果が出ているかについてお伺いしたいのと、合わせて介助員のお話もありました。あるいは通級指導、特別支援教室等で一定程度抑制されていくと思っておられるのかというところも含めてお聞かせほしいと求めました。","respondent":"大関教育総合支援センター長","answer":"あるいは学習支援員の部分は、やはりどうしても必要なある一定数が求められる状況もありますので、ここ数年は増えてきた傾向があります。","id":"exchange-080"},{"speaker":"塚本委員","kind":"質問・要望","question":"これは前々からいろいろなところで指摘されていることだと思いますが、この点も大変に重要なところであるというふうに捉えております。情報共有につきましてどのように図っていくのか、具体策等ありましたらお知らせほしいと求めました。","respondent":"大関教育総合支援センター長","answer":"これまでも就学支援シート、就学予定の全家庭に配布をして２割近くの回収率ということですが、各学校では情報を共有してきたところです。徐々に解決していけると考えますので、引き続き連携は深めてまいりたいと考えております。","id":"exchange-081"},{"speaker":"塚本委員","kind":"質問","question":"保護者の理解というところも含めまして、取り組みのほうをよろしくお願いしたいと思います。義務教育６校が実績としては出ておりますが、この辺の予算と実績の差についてお伺いしたいのと、幾つかご紹介ほしいと求めました。","respondent":"熊谷指導課長","answer":"１年目、最初の年ということで５月からというふうになりまして、全体的に経費が想定よりも抑えられたということがあります。学校支援ということで、職場体験ができる事業所を見つける際にも学校支援地域本部が中心となって動いてくださっている状況です。","id":"exchange-082"},{"speaker":"塚本委員","kind":"確認","question":"ご紹介いただきありがとうございました。比較的順調に行っているのか、それともやりたい活動に比べて少し人手が足りないというような状況があるのかについてだけ最後確認をさせてください。","respondent":"熊谷指導課長","answer":"は学校単位でやってきたところですけれども、これからは中学校単位であったり横の連携ということでコーディネーター連絡会がありますので、そういった中でボランティアを共有していきましょうという動きをただいまとっているところです。","id":"exchange-083"},{"speaker":"のだて委員","kind":"質問・要望","question":"準要保護者の認定基準について伺います。今後も生活保護費の引き下げに連動させないように求めますが、いかがか尋ねました。","respondent":"有馬学務課長","answer":"生活保護基準が平成２５年度から３ヵ年かけて変わってきましたけれども、改定以前の基準を区のほうは維持しているです。今後適切に検討・判断していきたいと思っておりまして、今の段階で何か変えるとか変えないとか、そういうものを決めているものではございません。","id":"exchange-084"},{"speaker":"のだて委員","kind":"質問・要望","question":"この間も求め続けていますが、１日目の質疑の中で、要保護の方については入学前からの支給が要綱上可能になったという趣旨の説明がありました。準要保護者についても入学前からの支給をすべきだと思いますが、いかがか尋ねました。","respondent":"有馬学務課長","answer":"確かにこの平成２９年３月末で要保護児童生徒援助費補助金の交付要綱が改正されまして、就学予定者の保護者も対象にするという改正がされたです。ただし、準要保護者に対してもどうあるべきかということは、今後も検討はしていきたいと思っているところです。","id":"exchange-085"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回の改正で要綱上も可能になりましたので、ぜひ進めてほしいと求めましたがいかがでしょうか。合わせて、先進事例については情報収集もしているのかどうかも伺いたいと思います。","respondent":"有馬学務課長","answer":"例えば２月１日現在で居住をしていること、入学したら再度新１年生のときにはもう一度申請を行うなどというのが基本になっているようです。","id":"exchange-086"},{"speaker":"のだて委員","kind":"質問・要望","question":"それともう１つ私が危惧しているのは、生活保護を受けていないけれども保護基準にある方もいるかもしれないと。そういった方への対応はどうしているのか伺います。","respondent":"有馬学務課長","answer":"所得の面から見て、例えば要保護の基準にあてはまるかもしれない方への対応というご質問だと思いますけれども、学務課のほうでは判断できません。そういったことは学務課では調べようがありませんので、その人に申請をいただくというような形で対応をしているというのが現状です。","id":"exchange-087"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ実現していただきたいですし、実現するまでこの配慮もぜひしてほしいと求めましたので、要望しておきます。準要保護者についてもこの要保護者と同じように増額してほしいと求めましたが、いかがか尋ねました。","respondent":"有馬学務課長","answer":"このたび、中学校では４万７,４００円というふうに金額が改訂をされております。この金額を準要保護に適用するかどうかですけれども、他の自治体の動向も確認しながら、合わせて検討してまいりたいと思っているところです。","id":"exchange-088"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ実施していただきたいと思うのですけれども、この間こういった質問をいたしますと、補助の復活を求めることも必要だと思うのです。あわせてこの間、都へも加算してほしいということを求めてほしいと求めましたが、いかがか尋ねました。","respondent":"有馬学務課長","answer":"これを新入学学用品のみでなかなか要求していくのはまだまだハードルが高いかなと考えています。は最初に、今ベースとなっております財調単価、こちらのほうの改定をまず都に求めていくということが先決になるのではないかと思ってあります。","id":"exchange-089"},{"speaker":"のだて委員","kind":"質問・要望","question":"この財調単価については求めていくことを検討するということですか、ぜひ求めてほしいと求めました。ぜひ準要保護者の入学準備金、要保護と同額にするよう改めて求めたいと思うのですけれども、ご見解の説明を求めました。","respondent":"有馬学務課長","answer":"この準要保護の新入学学用品については、やはりこの１年ぐらいでいろいろと注目を浴びてきたというふうに捉えております。さまざまな動きが各自治体でもあるということを踏まえまして、検討は進めてまいりたいと思います。","id":"exchange-090"},{"speaker":"のだて委員","kind":"質問・要望","question":"これまで区は公立に入学したことを確認してから就学援助を支給しているとの説明がありましたが、国立や私立についても記述がありました。なぜ私立や国立を対象にしないのか伺います。","respondent":"有馬学務課長","answer":"私立につきましては、この平成２９年４月からですけれども、ある一定の所得以内の方には年額１０万円の支給があるというようなこともあります。そういったこともありますので、今のところは私立は対象にはしていないです。","id":"exchange-091"},{"speaker":"のだて委員","kind":"質問・要望","question":"教育機会均等について考えれば、私立を除く必要はないと思いますので、ご検討ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-092"},{"speaker":"西本委員","kind":"質問・要望","question":"１７８ページの教育指導費に入るのでしょうか、どういう内容なのかご説明をほしいと求めました。なぜこれをやっているのでしょうかお答えをお願いします。","respondent":"大関教育総合支援センター長、有馬学務課長","answer":"大人と子どもが向き合い、具体的な部分は国や都を通じて今後どのようにすべきか情報収集をしたいと考えているところです。どのように授業時数を確保して取り組んでいくべきなのかをその時点で検討せねばならないと考えていますが。保護者から原発事故の後、食の安全性の担保を求められて、一層の安全確保のために検査をしようということで始めたものです。今年度につきましてはストロンチウムの検査回数を減らしてきたというような経過もあります。","id":"exchange-093"},{"speaker":"西本委員","kind":"質問","question":"ですから今も影響が残っていて、風評被害ということに直結しております。市場価格の半分もしくは３分の２ぐらいにやっと戻ってきたところで、そのチェックは品川区ではなくて国がしっかりとやるべきなのではないか尋ねました。","respondent":"大関教育総合支援センター長、有馬学務課長","answer":"当然、その他まずは実現できる状況を整えることも必要かと思いますので、そこは教育委員会だけではなく区全体で考えていくべき内容と考えております。厚生労働省が出している出荷制限の対象品目を毎月確認している中で、いまだに関東甲信越をはじめ、一部の食品がまだ残っているという状況もあります。","id":"exchange-094"},{"speaker":"西本委員","kind":"質問・要望","question":"やはり考えていただきたいのは、教育機関ですから、子どもたちの教育に資するのかということです。そして国のほうからいろいろな指針が来るかとは思いますけれども、そのお考えを最後にお聞きしたいと思います。","respondent":"大関教育総合支援センター長","answer":"品川の子どもたちのことを第一に今後も検討してまいります。","id":"exchange-095"},{"speaker":"大沢委員","kind":"質問・要望","question":"１８０ページの言語能力向上推進事業を質問します。話の初めに携帯社会だ、まずこの特別チームができるに至った社会的な事情、背景について聞かせてほしいと求めました。","respondent":"大関教育総合支援センター長","answer":"実際に学校現場でさまざまな取り組みが行われる中、品川区では平成２８年度には京陽小学校で３年間続けて言語能力向上のための取り組みをしています。","id":"exchange-096"},{"speaker":"大沢委員","kind":"意見","question":"これが言語力だと思うのですけれども、先ほど別の説明をされていましたけれども、それを踏まえてもう１回の説明を求めました。","respondent":"大関教育総合支援センター長","answer":"先ほど申し上げました例えば重点課題の発信力の中の例示で説明という部分がございました。この説明という部分は、４人で取り組んでつくった作品についてクラスの中で発表する、どのようにどういう工夫があるのかを説明する。","id":"exchange-097"},{"speaker":"大沢委員","kind":"質問","question":"知識、情緒に基づいてコミュニケートをするということで、では具体的なものに入っていきましょうか。相手にうまく自分の意思を伝える、要は会話力をより高めるためにはまず何が必要と考えますか尋ねました。","respondent":"大関教育総合支援センター長","answer":"相手に自分の意思を伝えるため、その結果会話力が高まるために必要なことというのは、まずさまざまな表現力が必要かと思います。それを発信する、人前で話そうとする意欲がまず何よりも大事だと考えます。","id":"exchange-098"},{"speaker":"大沢委員","kind":"質問","question":"ちょっと話が私の伺いたい内容とかみ合っていないような感じなのですけれども、そのためにはメモすることが私は大事だと思うのですけれども、先ほどの京陽小学校においてそのような授業の中でそういう指導はされているのか尋ねました。","respondent":"大関教育総合支援センター長","answer":"実際に友達のグループの発表を聞く際には、他のグループの子どもたちはワークシートに要点をまとめて、自分が感じたことなどについても合わせて書いておくことで、後から感想を述べたり、お互いに意見を交換し合うような授業場面がございました。","id":"exchange-099"},{"speaker":"大沢委員","kind":"意見","question":"思考をして初めて言葉というものが出るわけでありまして、この一連の作業において思考のないところには１つの言葉も出ない、具現化しないわけです。何が必要だとお考えになりますかとの意見を述べました。","respondent":"大関教育総合支援センター長、熊谷指導課長","answer":"京陽小学校に限らず、他の小学校などでも聞く態度についての学びというものは低学年の段階から努めております。この言語能力向上推進事業、平成２３年度から始まった事業ですが、情緒を育てるということがまず根底にあります。","id":"exchange-100"},{"speaker":"大沢委員","kind":"質問","question":"わからなくても通読させる、読ませるという作業が必要だと思うのですけれども、そこのところはどのようにお考えになるのか。ただ現代文におきましては現代の作家ですから、やはり、そこのところはどういうふうにお考えになりますか。","respondent":"熊谷指導課長","answer":"１年生から、実は現行の学習指導要領では、古典を重視しています。今も三木小学校や浅間台小学校では暗唱をとり入れた授業を行っていますので、そういったことが子どもたちの情緒を育てる第一歩になると考えています。","id":"exchange-101"},{"speaker":"大沢委員","kind":"質問・要望","question":"わからない文章でも読ませるということが１つ、例えば図画工作、いわゆる子どもたちの心の琴線に触れるような教科だと思うのです。子どもたちの情緒を大いに育むような効果を上げていただきたいと思うのですけれども、今の２点についてご感想なりお考えの説明を求めました。","respondent":"大関教育総合支援センター長、熊谷指導課長","answer":"各教科等でどのように取り組めるか、そういった場面からも情緒を育める場面は、図画工作にもご案内いただいたとおりあります。小さいうちからいいものを見たり聞いたり感じたり、そして暗唱したり、そういうことをしていく中で、子どもたちの豊かな心が育まれるよう、学校教育を一層推進してまいりたいと思います。","id":"exchange-102"},{"speaker":"大沢委員","kind":"質問・要望","question":"貴重な１分が残っているのでお願いだけ最後にしますけれども、１８１ページに英語力向上についてのいろいろな事業があります。そこのところも今お話しをしたことに加味をしながら、この事業がさらに飛躍するように進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-103"},{"speaker":"浅野委員","kind":"質問","question":"図書館で保管をする場合にはそれなりの設備があって、保存できるような環境を整えているのかどうか、特別な対応をされているのか伺います。","respondent":"横山品川図書館長","answer":"通常のやり方とあまり変わらないのですが、ラックに保存させていただきまして、ただあまり振動などが加わらないような形で保存しています。ビデオテープについても同様です。","id":"exchange-104"},{"speaker":"浅野委員","kind":"質問","question":"どのような形で調査をしているのかについて教えてほしいと求めました。調査が終わった後、次の非構造部材の耐震化をやるまでの間なのですけれども、その間にまた検討するようなことがあるのかどうかの説明を求めました。","respondent":"品川庶務課長","answer":"平成２７年に工事を進めていたのですが、なかなか平成２７年３月に出たガイドブックへの対応というのがとれていない状況でした。これを来年度以降対応していきたいと、このように考えております。","id":"exchange-105"},{"speaker":"浅野委員","kind":"質問","question":"例えばこの体育器具につきましては、使える期間と言うのでしょうか。種類によって違いがあると思いますけれども、何点か教えてほしいと求めました。","respondent":"有馬学務課長","answer":"ですのでものによって年数の違いというのはありますけれども、一応メーカーで耐用年数は一定程度定めているものがあると認識しております。今ここで跳び箱は何年か、マットは何年かということは資料の持ち合わせがないので、年数というものは申し訳ありませんがわかりません。","id":"exchange-106"},{"speaker":"浅野委員","kind":"質問","question":"今、データがないということを伺いました。なかなかスリリングでおもしろいと言うのでしょうか、私の友達がすべり落ちまして、ちょっとしたけがをしたということがございました。","respondent":"大関教育総合支援センター長","answer":"さまざまな学校器具等を体育で使用するために、当然教員は指導前に点検を行っております。不備があれば改善の必要があるかどうかを管理職に毎年報告をするような仕組みをどの学校も行っております。","id":"exchange-107"},{"speaker":"浅野委員","kind":"質問","question":"アスファルトですか、そしてまた遊んでいくという、このようなことをやはりしっかりと学んでいくのかなと思います。そのような取り組みというものは、少し質問から外れるかもしれませんけれども、あるのかどうかも含めて教えてほしいと求めました。","respondent":"大関教育総合支援センター長","answer":"例えば１５分休み、どの小学校でも監護当番を決めまして、複数の教員が安全のため見守っているところです。","id":"exchange-108"},{"speaker":"浅野委員","kind":"質問","question":"そして子どものころから危険を感知する、そのような能力をこれからもつけていっていただきますようお願いを申し上げまして、今回の質問とします。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-109"},{"speaker":"飯沼委員","kind":"質問・要望","question":"３０日に延長を求めますがいかがでしょうか。最終答申の前には区民への説明会をぜひ行ってほしいのですがいかがか尋ねました。","respondent":"篠田学校計画担当課長","answer":"説明会ですけれども、期間も十分とっているというふうに考えておりますので、説明会を今回設ける予定はございません。まだこれから検討する余地はありますし、検討していくことになりますけれども、説明会を開催するという方向性は今のところ考えていないところです。","id":"exchange-110"},{"speaker":"飯沼委員","kind":"質問","question":"委員長、済みません。ちょっと語尾がよく聞こえなかったので、考えていないとおっしゃったのか尋ねました。","respondent":"篠田学校計画担当課長","answer":"説明会に関しましては、今回、それから最終答申の場におきましても、きちんとした周知を図っていくことで説明会にかえていきたいというふうに考えているところです。","id":"exchange-111"},{"speaker":"飯沼委員","kind":"質問・要望","question":"目的は達成をされているのかどうか伺います。選択制に対する区教委の評価と、特に子どもにとってどうであるのかという点において、４点お伺いをします。","respondent":"篠田学校計画担当課長","answer":"こちらに対する評価ですけれども、基本的にまず１つは学校のあり方が大きく変わったというのがあります。そういった意味では、積極的に呼び込むための努力をしているというところで大きな変化があったというふうに考えているところです。","id":"exchange-112"},{"speaker":"飯沼委員","kind":"質問・要望","question":"各学校の特色とは一体どういうものなのか、具体的に幾つか挙げてほしいと求めました。なぜよいと思っているのか、そこを聞かせていただきたいのと、つかんでいるところでの説明を求めました。","respondent":"篠田学校計画担当課長","answer":"保護者の方々にとりましても、先ほど委員からお話のあったとおり、肯定する声が７割ということで、非常に好評を得ているものです。あるいはクラブ活動で力を入れており、そして結果を出している学校などそれぞれさまざまな形で個性が発揮されているものと認識しております。","id":"exchange-113"},{"speaker":"飯沼委員","kind":"質問・要望","question":"一般質問でも取り上げましたけれども、選択制によって地元の児童の３割、小学校で３割が地元から転出をしています。理解できませんので見解をぜひお伺いしたいと思います。","respondent":"篠田学校計画担当課長","answer":"必ずしも学校選択により６割が転出しているわけではないということはご説明させていただきたいと思います。中学校に関しましては、一貫教育の実効性を高めるために、さまざまな方策を合わせて考えていくといったような形で答申をいただいたものです。","id":"exchange-114"},{"speaker":"飯沼委員","kind":"質問・要望","question":"格差を特色ある学校と言って選ばせるのではなく、学校選択制はきっぱりやめるべきと思います。建物、中学生なら近隣校との連携を組むなど教育環境の整備を行っていくことが教育委員会に求められることと思いますが、いかがか尋ねました。","respondent":"篠田学校計画担当課長","answer":"そういった形で教育環境が劣ることがないように、教育委員会としても最善の努力をしています。これは今後とも行っていくことです。","id":"exchange-115"},{"speaker":"高橋（し）委員","kind":"質問","question":"他自治体でも多学年で実施された学校が多いと伺っています。実施されたのが民間のテストだと思いますが他の学校等と比較して平均点よりも非常によかった教科、逆にちょっと足りなかった教科をお尋ねいたします。","respondent":"熊谷指導課長","answer":"その中で全体を通してよかった教科は国語、算数、数学、英語です。反対に残念ながら社会、理科について課題が各学年で見られました。","id":"exchange-116"},{"speaker":"高橋（し）委員","kind":"質問","question":"理科についてやや少し届かないというところがあるとお伺いしましたが、理科教育に関しては東京都教育委員会のほうも小・中・高と力を入れております。小学校であれば３クラス、２クラスの理科を持つことになるということで、この２点についてどうお考えか尋ねました。","respondent":"熊谷指導課長","answer":"定着しなかったということで、その辺のところについてこれから見直しを教育要領でもしていきたいというふうに思っているところです。しっかり研修を行っていくと同時に校内事情も加味しながら、管理職がしっかり管理監督していくということも必要ではないかと思います。","id":"exchange-117"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"理科教育については今後も少しお話を伺っていきたいと思います。義務教育学校では中学校の教員が小学校、つまり５、６年生などの授業を持つ例があるか尋ねました。","respondent":"熊谷指導課長","answer":"前期課程にするか後期課程にするかというところがありますので、そのまま持ちあがりでというのは１年間の中ではあまりありません。","id":"exchange-118"},{"speaker":"高橋（し）委員","kind":"質問","question":"済みません。６年生の、あるいは６年生、７年生の理科の授業を持つということが行われているでしょうかということです。","respondent":"熊谷指導課長","answer":"そのように持ちあがりでということはやってあります。","id":"exchange-119"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"こうやっているのだからその手当を東京都のほうから講師の先生を充ててほしいというふうに要望していただきたいということが１つ。区費で講師をそこに充てて、その円滑なつなぎをやるということを実現していただきたいというのですが、いかがか尋ねました。","respondent":"熊谷指導課長","answer":"それから２つ目としましては、固有教員でも実際にはやっているところですが、例えば授業として英語等では一緒にやっていくということもあります。それにつきましても指導助手の配置等を学校からの要望に応じてつけているところです。","id":"exchange-120"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"せっかくの義務教育学校で小学校・中学校の連携を行うために、そういった現行の課題は、義務教育学校になっても解決されていないのですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-121"},{"speaker":"伊藤委員","kind":"確認","question":"この当時の担任の指導が適切であったのかということの確認と、言葉、非常に重要です。ですからこういうことについて今現在どのような指導を行っているのか尋ねました。","respondent":"大関教育総合支援センター長","answer":"したがいまして初任者研修では子どもへの対応の仕方についても必ず指導しています。１００％ではございませんが、１年生の担任も当然ですが、特別な配慮について共通理解を持てるように各学校へは指導をしています。","id":"exchange-122"},{"speaker":"伊藤委員","kind":"確認","question":"幼稚園・保育園とは全く違った環境に子どもが来るわけですよ。その後の生活にも影響を与えるのではないかということを確認したかったので、どう指導していくかということについての答弁をお願いいたします。","respondent":"熊谷指導課長","answer":"その先生の言葉遣いだったり態度だったり人格だったり、そういったものは子どもたちの一生を左右するといっても過言ではないと思います。ですので、また研修等も通じて、また体罰等もしっかり見過ごさないというところでやっていきたいというふうに思っております。","id":"exchange-123"},{"speaker":"伊藤委員","kind":"質問","question":"しっかりとＰＤＣＡサイクルをやって、改めて学校の薬品の管理について、それからＰＤＣＡについてどうお考えですかということをお聞かせください。お願いいたします。","respondent":"大関教育総合支援センター長","answer":"しっかりと薬品簿を必ずつけること、それを担当者だけに任せるのではなくて、管理職も必ず毎月確認をすることを徹底してまいったところです。","id":"exchange-124"},{"speaker":"伊藤委員","kind":"意見","question":"監査で指摘されているのだから。そのことに対して何が問題なのかをさらにもう一歩原因を追究していって、最終的な解決にはならないと思うので、もう一言答弁をお願いいたしますとの意見を述べました。","respondent":"品川庶務課長","answer":"そこで学校長の管理のもとで理科教員に指示をし、徹底をさせていきたいと考えております。指導主事が適宜学校のほうを回っておりますので、そういう段階でしっかりと確認をしていくという体制をとっていきたいと考えております。","id":"exchange-125"},{"speaker":"伊藤委員","kind":"質問","question":"で指導もしてきているけれども変わっていない現状があるので、そこはさらに検討していくべきではないでしょうかということを指摘をしております。さらに前に進んだ原因究明と対応策の検討をお願いしたいのですが、いかがか尋ねました。","respondent":"品川庶務課長","answer":"学校も十数校監査を受けた中で、１校、２校というところで、それもほんの１行書くのを忘れたという点での指摘もあります。しっかりと学校教員間の引き継ぎを徹底していくということを教育委員会からも十分指導していきたいと、このように考えております。","id":"exchange-126"},{"speaker":"伊藤委員","kind":"確認","question":"自民党・子ども未来の一般質問の答弁で、品川区は市民科の中で道徳の教科書も使って学習をさせるという答弁がありました。確認したいのは、それから住み分けと整合性をどうしていくのでしょうかというのを確認いたしますのでお願いいたします。","respondent":"大関教育総合支援センター長","answer":"市民科教育に関する検討部会を教育委員会が主導いたしまして、その中で従来と変わりなく道徳の内容も扱うという方向です。道徳的価値の理解、自分を見つめながらどのように生き方について考えていくか、市民科の中で道徳的な項目を従来どおり扱っていく考えです。","id":"exchange-127"},{"speaker":"伊藤委員","kind":"確認","question":"数値での評価はしないことを確認できたのだけれども、今現在で品川区の考えている範囲で結構ですから、お答えください。お願いいたします。","respondent":"大関教育総合支援センター長","answer":"これまでも、市民科の教科書と、そして道徳の教科書を両方併用していくことに何ら問題はないという部分は確認がとれております。なお、内容が重なる部分等がありますので、さらに両方を品川としてはより活用しやすい方向に改善していけるよう検討を進めている最中です。","id":"exchange-128"},{"speaker":"伊藤委員","kind":"質問","question":"教科書を２つ使っていくなどしっくりこない部分もあるので、また別の機会に質問していこうと思います。お願いいたします。","respondent":"大関教育総合支援センター長","answer":"さまざまな人権課題を扱いながらＬＧＢＴだけではなくて障害者、あるいは高齢者に対する対応等も含めまして、さまざまな角度から子どもたちにはいろいろな人がいる、それがこの世の中だということは指導してまいりたいと思います。","id":"exchange-129"},{"speaker":"石田（し）委員","kind":"提案","question":"１７７ページ、１７８ページ、ページがわからないのですが先ほどの人権に関連してダイバーシティ教育についてお伺いをいたしますとの意見を述べました。","respondent":"熊谷指導課長、大関教育総合支援センター長","answer":"ですので、どのぐらいいたかということを私どもで把握することができない状況です。ＳＮＳ、メール等でどのようにいじめへの対応ができるかというご質問ですが、その状況等を見守ってまいりたいと考えております。本区におきましては部活動外部指導員を配置しておりますので、そういう意味では他の自治体に比べて支援体制が整っているのではないかと思います。","id":"exchange-130"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"これは要望です。子どもたちを守るとともに、教師の方たちを守るという立場で、しっかりと仕事をしていただければというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-131"},{"speaker":"南委員","kind":"質問・要望","question":"学習指導要領では６年生までに習う漢字は１,００６文字だというふうに思っていますが、その点の確認をしたいと思います。学習指導要領では国と、やはり国以上に詰め込みを求めているのではないかというふうに思っておりますが、その点についてまず伺いたいと思います。","respondent":"熊谷指導課長","answer":"ただ、次の学習指導要領では２０字、新しい漢字が小学校段階で増えます。国語部会等でこの漢字のあり方についても、どうしたら子どもたちにとってよりよいものになるか、教材の開発等も含めて検討しています。","id":"exchange-132"},{"speaker":"南委員","kind":"質問・要望","question":"そして、脳の発達というか、国の学習指導要領では３年生に対してはここまで求めていないわけですよね。こういうものによって子どもの成長・発達、そういう問題意識は持っていないのかどうか、この点についての認識を伺います。","respondent":"熊谷指導課長、大関教育総合支援センター長","answer":"そうならないように７、８、９年生では繰り返し繰り返し漢字ステージに取り組んでいくということをとっております。ただ、次の教育要領の改訂ではそういったところも踏まえていきたいと考えております。習熟度にも焦点を当てまして、単元ごとに理解をした場合には発展的な内容に取り組めるよう学習の集団を編成して、学習を進めております。","id":"exchange-133"},{"speaker":"南委員","kind":"質問・要望","question":"品川区で実際にしているわけですから事実なのですけれども、この増加しているということについての認識を伺いたいと思います。私は品川区の教育委員会が求めている教育内容とこの実態はやはり大きな乖離があるのではないかなというふうに思っているのです。","respondent":"熊谷指導課長","answer":"固定学級ではなくて随時クラスを変更して、上に上がったり、そういった中で切磋琢磨していくことも重要なのではないかというふうに思っています。平成２３年度の家庭学習の実態状況調査ということなのですけれども、保護者と連携しながら進めてまいりたいと思います。","id":"exchange-134"},{"speaker":"南委員","kind":"質問・要望","question":"劣等感を持たせるようなやり方はやめていただきたい。それから詰め込みはやめていただきたいということ、そして勉強ができないとかやりたくないという子どもをつくらないような工夫をお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-135"},{"speaker":"こんの委員","kind":"確認","question":"もし時間がありましたら１８６ページの空調改修工事費に関連して、学校避難所の観点から体育館の空調設備設置についてをお伺いしたいと思います。","respondent":"熊谷指導課長","answer":"そして、やはり意識の改革ということで、９月５日に学校働き方改革、品川働き方ルネサンスの実施についてという通知を教育長名で出しました。実施開始日につきましても１０月からスタートということで、できるところから始めていこうというふうに思っています。","id":"exchange-136"},{"speaker":"こんの委員","kind":"提案","question":"私ども公明党として提案してきたことがさらに盛り込まれまして、概算要求の段階ではありますけれども、かなり具体的に進めようとされてきておりますとの意見を述べました。","respondent":"熊谷指導課長","answer":"さまざまな働き方改革に向けた支援を国としても考えているということがよくわかりました。品川区としてできること、例えばコミュニティ・スクール等を通じた学校支援なども含めながらやっていきたいと考えております。","id":"exchange-137"},{"speaker":"こんの委員","kind":"質問・要望","question":"現在、学校における防犯対策や不審者対策としてどのような対策をとられていますでしょうか。それともまだ不十分で、今後も対策をしていかなければいけないと思ってらっしゃるのか、その辺の評価はどのようにしてらっしゃるのか尋ねました。","respondent":"品川庶務課長","answer":"学校内に防犯カメラ等も設置をしっかりとしていますし、昨今通学路等にも防犯カメラを設置している状況です。ただ、事例等によって今後新たに加えていくもの等もあるかもしれませんが、現在のところでは十分ではないかと考えております。","id":"exchange-138"},{"speaker":"こんの委員","kind":"質問","question":"各学校で校内にさすまたが設置をされていると思いますけれども、それは現在どのような形で使われているのでしょうか。今学校に設置をされているさすまた、いわゆる校内での防犯対策が十分とはなかなか思えない感じがしますが、その点はいかがか尋ねました。","respondent":"品川庶務課長","answer":"コスト面等いろいろ考えますと、そのあたりの導入については少し検討をしていきたいというふうに考えております。何分、各学校に多く入れていかなければいけませんので、そういった面も考えながらやっていかなければいけないと考えています。","id":"exchange-139"},{"speaker":"こんの委員","kind":"質問・要望","question":"確かに財政的なことは考えてしまうのでしょうけれども、子どもの安全が第一ですので、ぜひその点を念頭において考えてほしいと求めました。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-140"},{"speaker":"石田（秀）委員","kind":"質問","question":"中学校の位置づけを含めて、コミュニティ・スクールは再考していくべきではないかなと考えていますけれども、その辺も教えてほしいと求めました。","respondent":"篠田学校計画担当課長","answer":"実際の制度の変更というのは翌年のそのまた次ぐらいになるだろうと、どんなに早くても翌年の当初にはならざるを得ないのかなと考えています。","id":"exchange-141"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ここは１０８万円対ゼロということになっているので、そうするとどういう話が来たかというと、全園児の診断をやってほしいという話もあった。","respondent":"佐藤保育課長","answer":"この辺に関しましては我々のほうとしても特別支援の関係で、早期発達を促す点について頑張っていきたいというところを基本と考えております。国と都は独自の要綱を持って、独自で８０万円を出しているというところで、なかなか区としては変えられない部分はあります。","id":"exchange-142"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"本当に１０８万円対ゼロみたいなところがあると、その辺についてぜひ再度お考えをほしいと求めましたので、もう一段最後答弁いただいて終わりにします。","respondent":"佐藤保育課長","answer":"区内の全ての乳幼児が健全に健やかに育っていけるようにする事が私どもの使命と考えておりますので、私立幼稚園協会等とも相談して、さまざま検討していきたいと考えております。","id":"exchange-143"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/392487?Template=document&Id=1446#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":113464,"voices":335}}]);
